#[serde(rename_all = "lowercase")]
enum N8nReadOnlyServerId {
    Eec,
    Hetzner,
}

impl N8nReadOnlyServerId {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Eec => "eec",
            Self::Hetzner => "hetzner",
        }
    }
}

