/// Host-only resource scope carried beside an internally built invoke request.
///
/// This is deliberately neither serialized nor `Debug`: external invoke JSON
/// cannot construct it, and provider input/context never contain the URI.
struct TrustedResourceBinding {
    server_id: N8nReadOnlyServerId,
    connector_id: ConnectorId,
    operation: OperationId,
    zone_id: ZoneId,
    request_id: RequestId,
    resource_uri: String,
}

impl TrustedResourceBinding {
    fn resource_uri_for<'a>(&'a self, request: &InvokeRequest) -> HostResult<&'a str> {
        if self.connector_id != request.connector_id
            || self.operation != request.operation
            || self.zone_id != request.zone_id
            || self.request_id != request.id
        {
            return Err(HostError::PreflightFailed(
                "trusted n8n resource binding does not match the invoke request".to_string(),
            ));
        }
        let expected = match request.connector_id.as_str() {
            "fcp.n8n" if N8N_RUN_ONCE_OPERATIONS.contains(&request.operation.as_str()) => {
                expected_n8n_read_only_resource_uri(
                    self.server_id,
                    request.operation.as_str(),
                    &request.input,
                )?
            }
            "fcp.mcp-bridge"
                if request.operation.as_str() == N8N_OFFICIAL_MCP_PROVIDER_OPERATION
                    && request
                        .input
                        .as_object()
                        .is_some_and(serde_json::Map::is_empty) =>
            {
                format!("fwc-mcp-bridge://{}", self.server_id.as_str())
            }
            "fcp.mcp-bridge" if request.operation.as_str() == N8N_OFFICIAL_MCP_CALL_OPERATION => {
                let object = request.input.as_object().ok_or_else(|| {
                    HostError::PreflightFailed(
                        "trusted n8n MCP tool call input must be an object".to_string(),
                    )
                })?;
                if object.len() != 2
                    || !object.contains_key("name")
                    || !object.contains_key("arguments")
                {
                    return Err(HostError::PreflightFailed(
                        "trusted n8n MCP tool call input shape was denied".to_string(),
                    ));
                }
                let name = object.get("name").and_then(Value::as_str).ok_or_else(|| {
                    HostError::PreflightFailed(
                        "trusted n8n MCP tool call name was denied".to_string(),
                    )
                })?;
                if !matches!(
                    name,
                    N8N_OFFICIAL_MCP_PUBLISH_TOOL
                        | N8N_OFFICIAL_MCP_UNPUBLISH_TOOL
                        | N8N_OFFICIAL_MCP_ARCHIVE_TOOL
                        | N8N_OFFICIAL_MCP_EXECUTE_TOOL
                ) || !object.get("arguments").is_some_and(Value::is_object)
                {
                    return Err(HostError::PreflightFailed(
                        "trusted n8n MCP tool call is not an approved lifecycle tool".to_string(),
                    ));
                }
                format!(
                    "fwc-mcp-bridge://{}/tools/{}",
                    self.server_id.as_str(),
                    encode_n8n_resource_segment(name)
                )
            }
            _ => {
                return Err(HostError::PreflightFailed(
                    "trusted n8n resource binding operation was denied".to_string(),
                ));
            }
        };
        if expected != self.resource_uri {
            return Err(HostError::PreflightFailed(
                "trusted n8n resource binding is not canonical for the invoke request".to_string(),
            ));
        }
        if request.connector_id.as_str() == "fcp.n8n" {
            validate_n8n_read_only_resource_uri(self.server_id, &self.resource_uri)?;
        }
        Ok(&self.resource_uri)
    }
}

