fn invoke_request_from_preflight(request: &HostPreflightRequest) -> HostResult<InvokeRequest> {
    let capability_token = request.capability_token.clone().ok_or_else(|| {
        HostError::PreflightFailed("capability token is required for live preflight".to_string())
    })?;
    let zone_id = request.zone_id.clone().ok_or_else(|| {
        HostError::PreflightFailed("zone_id is required for live preflight".to_string())
    })?;
    let operation = request.operation.parse().map_err(|error| {
        HostError::InvalidFilter(format!(
            "invalid preflight operation '{}': {error}",
            request.operation
        ))
    })?;

    Ok(InvokeRequest {
        r#type: "invoke".to_owned(),
        id: request.request_id.clone(),
        connector_id: request.connector_id.clone(),
        operation,
        zone_id,
        input: request.params.clone().unwrap_or(serde_json::Value::Null),
        capability_token,
        holder_proof: None,
        context: None,
        idempotency_key: None,
        lease_seq: None,
        deadline_ms: None,
        correlation_id: None,
        provenance: None,
        approval_tokens: request.approval_tokens.clone(),
    })
}

fn simulate_request_from_host(request: &HostSimulateRequest) -> HostResult<SimulateRequest> {
    let capability_token = request.capability_token.clone().ok_or_else(|| {
        HostError::PreflightFailed("capability token is required for live simulate".to_string())
    })?;
    let connector_id = request.connector_id.parse().map_err(|error| {
        HostError::InvalidFilter(format!(
            "invalid simulate connector id '{}': {error}",
            request.connector_id
        ))
    })?;
    let zone_raw = request.zone_id.as_deref().ok_or_else(|| {
        HostError::PreflightFailed("zone_id is required for live simulate".to_string())
    })?;
    let zone_id = zone_raw.parse().map_err(|error| {
        HostError::InvalidFilter(format!("invalid simulate zone_id '{zone_raw}': {error}"))
    })?;
    let operation = request.operation.parse().map_err(|error| {
        HostError::InvalidFilter(format!(
            "invalid simulate operation '{}': {error}",
            request.operation
        ))
    })?;

    Ok(SimulateRequest {
        r#type: "simulate".to_owned(),
        id: RequestId::new(request.request_id.clone()),
        connector_id,
        operation,
        zone_id,
        input: request.input.clone().unwrap_or(serde_json::Value::Null),
        capability_token,
        estimate_cost: request.estimate_cost,
        check_availability: request.check_availability,
        context: None,
        correlation_id: None,
    })
}

fn invoke_request_from_simulate(request: &HostSimulateRequest) -> HostResult<InvokeRequest> {
    let simulate_request = simulate_request_from_host(request)?;
    Ok(InvokeRequest {
        r#type: "invoke".to_owned(),
        id: simulate_request.id.clone(),
        connector_id: simulate_request.connector_id.clone(),
        operation: simulate_request.operation.clone(),
        zone_id: simulate_request.zone_id.clone(),
        input: simulate_request.input.clone(),
        capability_token: simulate_request.capability_token.clone(),
        holder_proof: None,
        context: simulate_request.context.clone(),
        idempotency_key: None,
        lease_seq: None,
        deadline_ms: Some(request.deadline_ms),
        correlation_id: simulate_request.correlation_id.clone(),
        provenance: None,
        approval_tokens: request.approval_tokens.clone(),
    })
}

fn map_simulate_cost_confidence(confidence: CostEstimateConfidence) -> SimulateCostConfidence {
    match confidence {
        CostEstimateConfidence::Low => SimulateCostConfidence::Low,
        CostEstimateConfidence::Medium => SimulateCostConfidence::Medium,
        CostEstimateConfidence::High => SimulateCostConfidence::High,
    }
}

fn map_simulate_cost_estimate(estimate: fcp_core::CostEstimate) -> SimulateCostEstimate {
    SimulateCostEstimate {
        api_credits: estimate.api_credits,
        estimated_duration_ms: estimate.estimated_duration_ms,
        estimated_bytes: estimate.estimated_bytes,
        confidence: estimate.confidence.map(map_simulate_cost_confidence),
    }
}

fn map_simulate_resource_availability(
    availability: ResourceAvailability,
) -> SimulateResourceAvailability {
    SimulateResourceAvailability {
        available: availability.available,
        rate_limit_remaining: availability.rate_limit_remaining,
        rate_limit_reset_at: availability.rate_limit_reset_at,
        details: availability.details,
    }
}

fn simulate_receipt_for_request(
    request: &HostSimulateRequest,
    input: &serde_json::Value,
    phase: SimulatePhase,
    would_succeed: bool,
    duration_ms: u64,
) -> HostResult<SimulateReceipt> {
    Ok(SimulateReceipt {
        receipt_id: format!("sim_{}", RequestId::random()),
        connector_id: request.connector_id.clone(),
        operation: request.operation.clone(),
        phase,
        would_succeed,
        input_digest: Some(hex::encode(request_input_hash(input)?)),
        duration_ms,
        simulated_at: Utc::now(),
    })
}

async fn record_simulate_receipt_summary(
    lifecycle: &HostAdminStateStore,
    receipt: &SimulateReceipt,
) {
    if let Err(err) = lifecycle.record_simulate_receipt(receipt.clone()).await {
        tracing::warn!(
            event = "simulate_receipt_persist_error",
            connector_id = %receipt.connector_id,
            operation = %receipt.operation,
            receipt_id = %receipt.receipt_id,
            error = %err,
            "failed to persist simulate receipt"
        );
    }
}

fn is_simulate_unsupported(error: &HostError) -> bool {
    matches!(
        error,
        HostError::RegistryError(message)
            if message.contains("Unknown method: simulate")
                || message.contains("does not support simulation")
                || message.contains("unsupported")
    )
}

fn request_input_hash(input: &serde_json::Value) -> HostResult<[u8; 32]> {
    let bytes = to_deterministic_cbor(input).map_err(|error| {
        HostError::Internal(format!("failed to canonicalize input payload: {error}"))
    })?;
    Ok(*blake3::hash(&bytes).as_bytes())
}

fn approval_token_signing_bytes(token: &ApprovalToken) -> HostResult<Vec<u8>> {
    fcp_host::canonical_approval_token_bytes(token).map_err(|error| {
        HostError::Internal(format!("failed to canonicalize approval token: {error}"))
    })
}

fn verify_approval_tokens(
    tokens: &[ApprovalToken],
    verifying_key: Option<&Ed25519VerifyingKey>,
) -> HostResult<()> {
    if tokens.is_empty() {
        return Ok(());
    }
    let key = verifying_key.ok_or_else(|| {
        HostError::PreflightFailed(
            "approval tokens were supplied, but FCP_HOST_APPROVAL_PUBLIC_KEY[_FILE] is not configured"
                .to_string(),
        )
    })?;

    for token in tokens {
        let signature = token.signature.as_ref().ok_or_else(|| {
            HostError::PreflightFailed(format!(
                "approval token `{}` is unsigned and cannot be verified",
                token.token_id
            ))
        })?;
        let signature = Ed25519Signature::try_from_slice(signature).map_err(|error| {
            HostError::PreflightFailed(format!(
                "approval token `{}` has an invalid signature: {error}",
                token.token_id
            ))
        })?;
        let bytes = approval_token_signing_bytes(token)?;
        key.verify(&bytes, &signature).map_err(|error| {
            HostError::PreflightFailed(format!(
                "approval token `{}` failed signature verification: {error}",
                token.token_id
            ))
        })?;
    }

    Ok(())
}

const MAX_N8N_EXTERNAL_APPROVAL_BYTES: usize = 64 * 1024;

fn n8n_run_once_binding_hash(
    server_id: N8nReadOnlyServerId,
    resource_uri: &str,
    operation: &str,
    input: &Value,
) -> HostResult<[u8; 32]> {
    request_input_hash(&json!({
        "server_id": server_id.as_str(),
        "resource_uri": resource_uri,
        "operation": operation,
        "input": input,
    }))
}

fn validate_external_n8n_approval(
    token: Option<&ApprovalToken>,
    approval_ref: &str,
    expected_connector: &str,
    expected_operation: &str,
    expected_zone: &ZoneId,
    expected_input_hash: [u8; 32],
    expected_constraints: &[InputConstraint],
    verifying_key: Option<&Ed25519VerifyingKey>,
) -> HostResult<()> {
    let token = token.ok_or_else(|| {
        HostError::PreflightFailed(
            "n8n write run-once requires an external owner approval token".to_string(),
        )
    })?;
    let encoded = fcp_cbor::to_canonical_cbor(token).map_err(|_| {
        HostError::PreflightFailed("n8n external approval token is not encodable".to_string())
    })?;
    if encoded.len() > MAX_N8N_EXTERNAL_APPROVAL_BYTES {
        return Err(HostError::PreflightFailed(
            "n8n external approval token exceeds the bounded size".to_string(),
        ));
    }
    verify_approval_tokens(std::slice::from_ref(token), verifying_key)?;
    if token.token_id != approval_ref || !token.is_valid(n8n_run_once_now_ms()) {
        return Err(HostError::PreflightFailed(
            "n8n external approval token does not match approvalRef or expiry".to_string(),
        ));
    }
    let work_zone = ZoneId::work();
    if expected_zone != &work_zone || token.zone_id != work_zone {
        return Err(HostError::PreflightFailed(
            "n8n external approval token must be bound to z:work".to_string(),
        ));
    }
    let ApprovalScope::Execution(scope) = &token.scope else {
        return Err(HostError::PreflightFailed(
            "n8n external approval token scope is not execution".to_string(),
        ));
    };
    if scope.connector_id != expected_connector
        || scope.method_pattern != expected_operation
        || scope.request_object_id.is_some()
        || scope.input_hash != Some(expected_input_hash)
        || scope.input_constraints.len() != expected_constraints.len()
        || !scope.input_constraints.iter().all(|actual| {
            expected_constraints.iter().any(|expected| {
                actual.pointer == expected.pointer && actual.expected == expected.expected
            })
        })
        || !expected_constraints.iter().all(|expected| {
            scope.input_constraints.iter().any(|actual| {
                actual.pointer == expected.pointer && actual.expected == expected.expected
            })
        })
    {
        return Err(HostError::PreflightFailed(
            "n8n external approval token target binding was denied".to_string(),
        ));
    }
    Ok(())
}

fn claims_principal(claims: &fcp_crypto::cose::CwtClaims) -> Option<&str> {
    claims
        .get_subject()
        .or_else(|| match claims.get(fcp2_claims::PRINCIPAL_ID) {
            Some(ciborium::Value::Text(principal)) => Some(principal.as_str()),
            _ => None,
        })
}

fn capability_token_b64(token: &fcp_core::CapabilityToken) -> HostResult<String> {
    let bytes = token.raw().to_cbor().map_err(|error| {
        HostError::Internal(format!(
            "failed to serialize capability token for verification: {error}"
        ))
    })?;
    Ok(base64::engine::general_purpose::STANDARD.encode(bytes))
}

fn object_id_from_token_id_bytes(token_id: &[u8]) -> ObjectId {
    if token_id.len() == 32 {
        let mut bytes = [0_u8; 32];
        bytes.copy_from_slice(token_id);
        ObjectId::from_bytes(bytes)
    } else {
        ObjectId::from_unscoped_bytes(token_id)
    }
}

fn revocation_cascade_token_id(
    token: &fcp_core::CapabilityToken,
    claims: &fcp_crypto::cose::CwtClaims,
) -> HostResult<ObjectId> {
    if let Some(token_id) = claims.get_jti() {
        return Ok(object_id_from_token_id_bytes(token_id));
    }

    let bytes = token.raw().to_cbor().map_err(|error| {
        HostError::PreflightFailed(format!(
            "revocation cascade could not derive a token id from the capability token: {error}"
        ))
    })?;
    Ok(ObjectId::from_unscoped_bytes(&bytes))
}

fn revocation_cascade_issuer_kid(token: &fcp_core::CapabilityToken) -> HostResult<KeyId> {
    let kid = token.raw().get_key_id().map_err(|error| {
        HostError::PreflightFailed(format!(
            "revocation cascade could not read the token issuer KID: {error}"
        ))
    })?;
    KeyId::try_from_slice(&kid).map_err(|error| {
        HostError::PreflightFailed(format!(
            "revocation cascade rejected token issuer KID: {error}"
        ))
    })
}

fn verify_live_revocation_cascade(
    state: &AppState,
    token: &fcp_core::CapabilityToken,
    claims: &fcp_crypto::cose::CwtClaims,
) -> HostResult<()> {
    let token_id = revocation_cascade_token_id(token, claims)?;
    let issuer_kid = revocation_cascade_issuer_kid(token)?;
    state
        .revocation_cascade
        .verify(token_id, issuer_kid)
        .map_err(|error| {
            HostError::PreflightFailed(format!(
                "capability token rejected by revocation cascade: {error}"
            ))
        })?;
    Ok(())
}

fn decode_hybrid_owner_invoke_evidence(raw: &str) -> HostResult<HybridOwnerInvokeEvidence> {
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(raw.trim())
        .map_err(|error| {
            HostError::PreflightFailed(format!(
                "hybrid owner evidence tag is not valid base64 CBOR: {error}"
            ))
        })?;
    ciborium::from_reader(bytes.as_slice()).map_err(|error| {
        HostError::PreflightFailed(format!(
            "hybrid owner evidence tag is not a valid evidence envelope: {error}"
        ))
    })
}

fn hybrid_owner_invoke_evidence(
    request: &InvokeRequest,
) -> HostResult<Option<HybridOwnerInvokeEvidence>> {
    let Some(raw) = request
        .context
        .as_ref()
        .and_then(|context| context.request_tags.get(HYBRID_OWNER_EVIDENCE_TAG))
    else {
        return Ok(None);
    };
    decode_hybrid_owner_invoke_evidence(raw).map(Some)
}

fn verify_live_hybrid_owner_capability(
    state: &AppState,
    request: &InvokeRequest,
) -> HostResult<()> {
    // br-jhbk1: when the host is NOT configured with a hybrid-owner
    // verifier (FCP_HOST_HYBRID_OWNER_CONTEXT_FILE unset) AND the
    // request carries the hybrid-owner evidence tag, the caller is
    // explicitly asking for V4 hybrid-owner verification. The host
    // cannot honor that intent without a verifier, so fail CLOSED
    // rather than silently letting the request through. The pre-fix
    // behavior of returning Ok(()) here regardless of whether the
    // request claimed hybrid-owner governance was an auth-bypass-via-
    // missing-config: an operator who forgot to set the env var
    // silently accepted ALL invokes — including ones that should
    // require post-quantum V3-to-V4 migration verification. See
    // docs/audit/security-audit-saas-alpha-2026-05-02.md §a.
    //
    // Tokens that do NOT carry the evidence tag continue to take the
    // legacy V3-only path (no verifier needed) for back-compat.
    let Some(verifier) = state.hybrid_owner_verifier.as_deref() else {
        if hybrid_owner_invoke_evidence(request)?.is_some() {
            return Err(HostError::PreflightFailed(format!(
                "request carries hybrid-owner evidence tag `{HYBRID_OWNER_EVIDENCE_TAG}` \
                 but this host is not configured for hybrid-owner verification \
                 (set {HYBRID_OWNER_CONTEXT_FILE_ENV} to enable; br-jhbk1)"
            )));
        }
        return Ok(());
    };
    let evidence = hybrid_owner_invoke_evidence(request)?.ok_or_else(|| {
        HostError::PreflightFailed(format!(
            "missing hybrid owner evidence tag `{HYBRID_OWNER_EVIDENCE_TAG}` for owner-governed capability token"
        ))
    })?;
    verifier.verify_capability_token(&request.zone_id, &request.capability_token, &evidence)
}

fn capability_constraints_from_claims(
    claims: &fcp_crypto::cose::CwtClaims,
) -> HostResult<CapabilityConstraints> {
    let Some(encoded_constraints) = claims.get(fcp2_claims::CONSTRAINTS) else {
        return Err(HostError::PreflightFailed(
            "capability token is missing constraints required for live execution".to_string(),
        ));
    };

    let mut bytes = Vec::new();
    ciborium::into_writer(encoded_constraints, &mut bytes).map_err(|error| {
        HostError::PreflightFailed(format!(
            "failed to reserialize capability constraints claim: {error}"
        ))
    })?;
    ciborium::from_reader(&bytes[..]).map_err(|error| {
        HostError::PreflightFailed(format!(
            "failed to decode capability constraints claim: {error}"
        ))
    })
}

fn live_constraint_resource_uri(input: &Value) -> Option<String> {
    ["resource_uri", "resource", "uri", "url"]
        .iter()
        .find_map(|key| {
            input
                .get(*key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned)
        })
}

fn verified_live_constraint_resource_uri(
    request: &InvokeRequest,
    trusted_resource: Option<&TrustedResourceBinding>,
) -> HostResult<Option<String>> {
    let input_resource = live_constraint_resource_uri(&request.input);
    let Some(binding) = trusted_resource else {
        return Ok(input_resource);
    };
    let bound_resource = binding.resource_uri_for(request)?;
    if input_resource
        .as_deref()
        .is_some_and(|resource| resource != bound_resource)
    {
        return Err(HostError::PreflightFailed(
            "trusted resource binding conflicts with invoke input".to_string(),
        ));
    }
    Ok(Some(bound_resource.to_string()))
}

fn enforce_live_capability_constraints(
    request: &InvokeRequest,
    claims: &fcp_crypto::cose::CwtClaims,
    principal: &str,
    resource_uri: Option<&str>,
) -> HostResult<()> {
    let constraints = capability_constraints_from_claims(claims)?;
    let input_cbor = to_deterministic_cbor(&request.input).map_err(|error| {
        HostError::PreflightFailed(format!(
            "failed to canonicalize request input for capability constraints: {error}"
        ))
    })?;
    let requested_at_unix_ms = u64::try_from(Utc::now().timestamp_millis()).map_err(|_| {
        HostError::PreflightFailed(
            "system clock produced a negative timestamp for capability constraint enforcement"
                .to_string(),
        )
    })?;
    let principal = PrincipalId::new(principal).map_err(|error| {
        HostError::PreflightFailed(format!(
            "capability token principal is not canonical for constraint enforcement: {error}"
        ))
    })?;

    let descriptor = RequestDescriptor {
        object_id: ObjectId::from_unscoped_bytes(request.id.0.as_bytes()),
        operation: request.operation.clone(),
        principal,
        host: String::new(),
        resource_uri: resource_uri.unwrap_or_default().to_string(),
        requested_at_unix_ms,
        observed_calls: 1,
        observed_bytes: input_cbor.len().try_into().unwrap_or(u64::MAX),
    };

    match DefaultConstraintEnforcer::new().evaluate(&constraints, &descriptor) {
        ConstraintEvaluation::Allow => Ok(()),
        ConstraintEvaluation::Deny(reason) => {
            let audit_descriptor = capability_constraint_audit_descriptor(
                request.id.0.as_str(),
                request.connector_id.as_str(),
                request.operation.as_str(),
                request.zone_id.as_str(),
                &descriptor,
            );
            emit_capability_constraint_denial_audit_event(
                &audit_descriptor,
                &reason.kind,
                "fcp-host.live",
            );

            Err(HostError::PreflightFailed(format!(
                "capability constraint denied during live execution ({:?}): {}",
                reason.kind, reason.explanation
            )))
        }
    }
}

const DEPLOYMENT_TIER_DENIED_AUDIT_EVENT_TYPE: &str = "deployment_tier.denied";
const OWNER_SINGLE_HOST_ADMITTED_AUDIT_EVENT_TYPE: &str =
    "deployment_tier.owner_single_host_admitted";
const OWNER_SINGLE_HOST_ADMISSION_ENV: &str = "FCP_HOST_OWNER_SINGLE_HOST_ADMISSION";
const OWNER_SINGLE_HOST_ADMISSION_MODE: &str = "owner-approved-single-host";

#[derive(Debug, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct OwnerSingleHostAdmission {
    version: u8,
    mode: String,
    zone_id: String,
    connector_id: String,
    operation: String,
}

impl OwnerSingleHostAdmission {
    fn parse(raw: &str) -> HostResult<Self> {
        let admission: Self = serde_json::from_str(raw).map_err(|error| {
            HostError::InvalidFilter(format!(
                "{OWNER_SINGLE_HOST_ADMISSION_ENV} must be a valid owner admission object: {error}"
            ))
        })?;
        if admission.version != 1 || admission.mode != OWNER_SINGLE_HOST_ADMISSION_MODE {
            return Err(HostError::InvalidFilter(format!(
                "{OWNER_SINGLE_HOST_ADMISSION_ENV} requires version=1 and mode={OWNER_SINGLE_HOST_ADMISSION_MODE}"
            )));
        }
        if admission.zone_id.trim().is_empty()
            || admission.connector_id.trim().is_empty()
            || admission.operation.trim().is_empty()
        {
            return Err(HostError::InvalidFilter(format!(
                "{OWNER_SINGLE_HOST_ADMISSION_ENV} identifiers must be non-empty"
            )));
        }
        Ok(admission)
    }

    fn matches(&self, request: &InvokeRequest, tier: SafetyTier) -> bool {
        matches!(tier, SafetyTier::Risky | SafetyTier::Dangerous)
            && self.zone_id == request.zone_id.as_str()
            && self.connector_id == request.connector_id.as_str()
            && self.operation == request.operation.as_str()
    }
}

fn owner_single_host_admission_allows(
    request: &InvokeRequest,
    tier: SafetyTier,
    raw: Option<&str>,
) -> HostResult<bool> {
    raw.map(OwnerSingleHostAdmission::parse)
        .transpose()
        .map(|admission| admission.is_some_and(|value| value.matches(request, tier)))
}

fn current_deployment_classification() -> DeploymentClassification {
    // The host binary does not yet have live mesh quorum signals wired into
    // AppState. Classify the production boundary as single-host Evaluation so
    // Risky/Dangerous dispatch fails closed until those signals exist.
    classify_deployment_mode(MeshQuorumSignals::single_host_evaluation())
}

fn select_host_truth_precedence_boot_from_env_values(
    signals: MeshQuorumSignals,
    default_env: Option<&str>,
    insufficient_peers_behavior_env: Option<&str>,
    default_graduated_env: Option<&str>,
    min_healthy_peers_env: Option<&str>,
) -> Result<TruthPrecedenceBootResolution, TruthPrecedenceBootError> {
    resolve_truth_precedence_boot_resolution(
        signals,
        default_env,
        insufficient_peers_behavior_env,
        default_graduated_env,
        min_healthy_peers_env,
    )
}

fn read_optional_trimmed_truth_precedence_env(
    name: &'static str,
) -> Result<Option<String>, TruthPrecedenceBootError> {
    read_optional_trimmed_env_string(name).map_err(|error| {
        TruthPrecedenceBootError::InvalidEnvValue {
            var: name,
            value: error.to_string(),
            expected: "valid unicode environment value",
        }
    })
}

fn current_truth_precedence_boot_resolution()
-> Result<TruthPrecedenceBootResolution, TruthPrecedenceBootError> {
    let default_env = read_optional_trimmed_truth_precedence_env(TRUTH_PRECEDENCE_DEFAULT_ENV)?;
    let insufficient_peers_behavior_env =
        read_optional_trimmed_truth_precedence_env(V2_INSUFFICIENT_PEERS_BEHAVIOR_ENV)?;
    let default_graduated_env =
        read_optional_trimmed_truth_precedence_env(V2_DEFAULT_GRADUATED_ENV)?;
    let min_healthy_peers_env =
        read_optional_trimmed_truth_precedence_env(V2_MIN_HEALTHY_MESH_PEERS_ENV)?;
    let signals = MeshQuorumSignals::single_host_evaluation();
    select_host_truth_precedence_boot_from_env_values(
        signals,
        default_env.as_deref(),
        insufficient_peers_behavior_env.as_deref(),
        default_graduated_env.as_deref(),
        min_healthy_peers_env.as_deref(),
    )
}

fn boot_event_timestamp() -> String {
    Utc::now().to_rfc3339_opts(SecondsFormat::Millis, true)
}

fn emit_truth_precedence_boot_error(error: &TruthPrecedenceBootError) {
    let timestamp = boot_event_timestamp();
    match error {
        TruthPrecedenceBootError::InvalidEnvValue {
            var,
            value,
            expected,
        } => {
            tracing::error!(
                target: "fcp_host::deployment_mode",
                event = "fcp.host.boot_refused_truth_precedence",
                event_type = "fcp.host.boot_refused_truth_precedence",
                bead_id = "flywheel_connectors-hr0rr.2.6",
                actor = "host",
                redaction_scope = "public",
                correlation_id = "boot",
                timestamp = %timestamp,
                env_var = *var,
                env_value = %value,
                expected = *expected,
                exit_code = TRUTH_PRECEDENCE_BOOT_CONFIG_EXIT_CODE,
                "fcp-host truth-precedence boot configuration is invalid"
            );
        }
        TruthPrecedenceBootError::RefusedBoot {
            observed,
            required,
            behavior,
            reason,
        } => {
            tracing::error!(
                target: "fcp_host::deployment_mode",
                event = "fcp.host.boot_refused_truth_precedence",
                event_type = "fcp.host.boot_refused_truth_precedence",
                bead_id = "flywheel_connectors-hr0rr.2.6",
                actor = "host",
                redaction_scope = "public",
                correlation_id = "boot",
                timestamp = %timestamp,
                precedence_default = "v2_requested",
                behavior_chosen = behavior.label(),
                mesh_peer_count = *observed,
                min_healthy_peers = *required,
                exit_code = TRUTH_PRECEDENCE_BOOT_CONFIG_EXIT_CODE,
                reason = *reason,
                "fcp-host refused V2 mesh-native boot"
            );
        }
    }
}

fn emit_operational_model_selection_log(selection: &TruthPrecedenceBootSelection) {
    let timestamp = boot_event_timestamp();
    if let Some(warning) = selection.warning.as_deref() {
        tracing::warn!(
            target: "fcp_host::deployment_mode",
            event = "fcp.host.boot_truth_precedence",
            event_type = "fcp.host.boot_truth_precedence",
            bead_id = "flywheel_connectors-hr0rr.2.6",
            actor = "host",
            redaction_scope = "public",
            correlation_id = "boot",
            timestamp = %timestamp,
            precedence_default = if selection.requested == fcp_policy::OperationalModelVersion::V2MeshNative {
                "v2_requested"
            } else {
                "v1_requested"
            },
            requested_model = selection.requested.label(),
            effective_model = selection.effective.label(),
            behavior_chosen = selection.behavior_chosen.label(),
            mesh_peer_count = selection.mesh_peer_count,
            min_healthy_peers = selection.min_healthy_peers,
            insufficient_peers = selection.insufficient_peers,
            explicit_v2_requested = selection.explicit_v2_requested,
            graduated_v2_default = selection.graduated_v2_default,
            degraded_from = selection.degraded_from.as_deref().unwrap_or("none"),
            "{warning}"
        );
    } else {
        tracing::info!(
            target: "fcp_host::deployment_mode",
            event = "fcp.host.boot_truth_precedence",
            event_type = "fcp.host.boot_truth_precedence",
            bead_id = "flywheel_connectors-hr0rr.2.6",
            actor = "host",
            redaction_scope = "public",
            correlation_id = "boot",
            timestamp = %timestamp,
            precedence_default = if selection.requested == fcp_policy::OperationalModelVersion::V2MeshNative {
                "v2_requested"
            } else {
                "v1_requested"
            },
            requested_model = selection.requested.label(),
            effective_model = selection.effective.label(),
            behavior_chosen = selection.behavior_chosen.label(),
            mesh_peer_count = selection.mesh_peer_count,
            min_healthy_peers = selection.min_healthy_peers,
            insufficient_peers = selection.insufficient_peers,
            explicit_v2_requested = selection.explicit_v2_requested,
            graduated_v2_default = selection.graduated_v2_default,
            degraded_from = selection.degraded_from.as_deref().unwrap_or("none"),
            "fcp-host operational model selected"
        );
    }
}

fn deployment_tier_refusal_reason_code(refusal: &DeploymentTierRefusal) -> &'static str {
    match refusal {
        DeploymentTierRefusal::TierRequiresMeshActive { .. } => "TIER_REQUIRES_MESH_ACTIVE",
        DeploymentTierRefusal::TierForbidden { .. } => "TIER_FORBIDDEN",
    }
}

fn deployment_tier_refusal_payload(refusal: &DeploymentTierRefusal) -> String {
    serde_json::to_string(refusal).unwrap_or_else(|error| {
        format!("{{\"kind\":\"serialization_error\",\"message\":\"{error}\"}}")
    })
}

fn deployment_tier_refusal_message(refusal: &DeploymentTierRefusal) -> String {
    format!(
        "deployment tier admission denied: {}",
        deployment_tier_refusal_payload(refusal)
    )
}

fn emit_deployment_tier_denial_audit_event(
    request: &InvokeRequest,
    tier: SafetyTier,
    classification: &DeploymentClassification,
    refusal: &DeploymentTierRefusal,
) {
    let lease_coordinator = match classification.signals.lease_coordinator_reachable {
        None => "n/a",
        Some(true) => "reachable",
        Some(false) => "unreachable",
    };
    let refusal_payload = deployment_tier_refusal_payload(refusal);
    tracing::warn!(
        audit_event_type = DEPLOYMENT_TIER_DENIED_AUDIT_EVENT_TYPE,
        reason_code = deployment_tier_refusal_reason_code(refusal),
        refusal = %refusal_payload,
        safety_tier = ?tier,
        deployment_mode = classification.mode.label(),
        deployment_reason = classification.reason.label(),
        healthy_peer_count = classification.signals.healthy_peer_count,
        lease_coordinator,
        revocation_fresh = classification.signals.revocation_snapshot_fresh,
        request_id = request.id.0.as_str(),
        connector_id = request.connector_id.as_str(),
        operation = request.operation.as_str(),
        zone_id = request.zone_id.as_str(),
        "deployment_tier_denied_audit_event"
    );
}

fn emit_owner_single_host_admission_audit_event(request: &InvokeRequest, tier: SafetyTier) {
    tracing::warn!(
        audit_event_type = OWNER_SINGLE_HOST_ADMITTED_AUDIT_EVENT_TYPE,
        reason_code = "OWNER_APPROVED_SINGLE_HOST_OPERATION",
        safety_tier = ?tier,
        deployment_mode = "evaluation",
        request_id = request.id.0.as_str(),
        connector_id = request.connector_id.as_str(),
        operation = request.operation.as_str(),
        zone_id = request.zone_id.as_str(),
        "owner_single_host_admitted_audit_event"
    );
}

const HRW_LEASE_LOCAL_NODE_ENV: &str = "FCP_HOST_HRW_LEASE_LOCAL_NODE";
const HRW_LEASE_NODES_ENV: &str = "FCP_HOST_HRW_LEASE_NODES";
const HRW_LEASE_CURRENT_SEQ_ENV: &str = "FCP_HOST_HRW_LEASE_CURRENT_SEQ";
const CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL: &str = "connector_state_write";
const CONNECTOR_STATE_LEASE_REQUIRED_QUORUM_SIGNATURES: usize = 2;

#[derive(Debug, Clone, PartialEq, Eq)]
struct HrwLeaseRoutingConfig {
    local_node: TailscaleNodeId,
    eligible_nodes: Vec<TailscaleNodeId>,
    current_lease_seq: Option<u64>,
}

#[derive(Debug, Clone, Default)]
struct ConnectorLeaseDurableEvidence {
    lease_object_id: Option<ObjectId>,
    lease_seq: Option<u64>,
    expiry_unix_secs: Option<u64>,
    quorum_signers_count: Option<usize>,
    validation_status: Option<&'static str>,
    validation_error: Option<String>,
    validated_at_unix_secs: Option<u64>,
    source: Option<&'static str>,
    warnings: Vec<String>,
}

impl ConnectorLeaseDurableEvidence {
    fn mark_invalid_lease(&mut self, lease_object_id: ObjectId, error: String) {
        self.validation_status = Some("invalid");
        self.validation_error = Some(error.clone());
        self.validated_at_unix_secs = Some(current_unix_secs_u64());
        self.warnings.push(format!(
            "Durable lease object `{lease_object_id}` failed live lease validation: {error}"
        ));
    }
}

#[cfg(test)]
static TEST_HRW_LEASE_ROUTING_OVERRIDE: std::sync::Mutex<Option<Option<HrwLeaseRoutingConfig>>> =
    std::sync::Mutex::new(None);
#[cfg(test)]
static TEST_HRW_LEASE_ROUTING_OVERRIDE_SERIAL: std::sync::Mutex<()> = std::sync::Mutex::new(());

#[cfg(test)]
struct TestHrwLeaseRoutingOverrideGuard {
    _serial: std::sync::MutexGuard<'static, ()>,
}

#[cfg(test)]
impl Drop for TestHrwLeaseRoutingOverrideGuard {
    fn drop(&mut self) {
        *TEST_HRW_LEASE_ROUTING_OVERRIDE
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = None;
    }
}

#[cfg(test)]
fn set_test_hrw_lease_routing_override(
    config: Option<HrwLeaseRoutingConfig>,
) -> TestHrwLeaseRoutingOverrideGuard {
    let serial = TEST_HRW_LEASE_ROUTING_OVERRIDE_SERIAL
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let mut guard = TEST_HRW_LEASE_ROUTING_OVERRIDE
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    assert!(guard.is_none(), "HRW lease routing override already set");
    *guard = Some(config);
    TestHrwLeaseRoutingOverrideGuard { _serial: serial }
}

fn parse_hrw_lease_node_id(raw: &str, env_name: &str) -> HostResult<TailscaleNodeId> {
    TailscaleNodeId::try_new(raw.to_owned()).map_err(|error| {
        HostError::InvalidFilter(format!("invalid {env_name} node id `{raw}`: {error}"))
    })
}

fn parse_hrw_lease_node_set(raw: &str, env_name: &str) -> HostResult<Vec<TailscaleNodeId>> {
    let mut seen = HashSet::new();
    let mut nodes = Vec::new();
    for raw_node in raw.split(',') {
        let trimmed = raw_node.trim();
        if trimmed.is_empty() {
            continue;
        }
        let node = parse_hrw_lease_node_id(trimmed, env_name)?;
        if seen.insert(node.as_str().to_owned()) {
            nodes.push(node);
        }
    }
    if nodes.is_empty() {
        return Err(HostError::InvalidFilter(format!(
            "{env_name} must list at least one node id"
        )));
    }
    Ok(nodes)
}

fn parse_hrw_lease_routing_config_from_env_values(
    local_node: Option<&str>,
    eligible_nodes: Option<&str>,
    current_lease_seq: Option<u64>,
) -> HostResult<Option<HrwLeaseRoutingConfig>> {
    match (local_node, eligible_nodes) {
        (None, None) if current_lease_seq.is_none() => Ok(None),
        (None, None) => Err(HostError::InvalidFilter(format!(
            "set {HRW_LEASE_LOCAL_NODE_ENV} and {HRW_LEASE_NODES_ENV} when using {HRW_LEASE_CURRENT_SEQ_ENV}"
        ))),
        (Some(local_node), Some(eligible_nodes)) => {
            let local_node = parse_hrw_lease_node_id(local_node, HRW_LEASE_LOCAL_NODE_ENV)?;
            let eligible_nodes = parse_hrw_lease_node_set(eligible_nodes, HRW_LEASE_NODES_ENV)?;
            if !eligible_nodes.iter().any(|node| node == &local_node) {
                return Err(HostError::InvalidFilter(format!(
                    "{HRW_LEASE_NODES_ENV} must include local node `{}`",
                    local_node.as_str()
                )));
            }
            Ok(Some(HrwLeaseRoutingConfig {
                local_node,
                eligible_nodes,
                current_lease_seq,
            }))
        }
        (Some(_), None) | (None, Some(_)) => Err(HostError::InvalidFilter(format!(
            "set both {HRW_LEASE_LOCAL_NODE_ENV} and {HRW_LEASE_NODES_ENV} to enable singleton_writer HRW lease routing"
        ))),
    }
}

fn current_hrw_lease_routing_config() -> HostResult<Option<HrwLeaseRoutingConfig>> {
    #[cfg(test)]
    {
        if let Some(config) = TEST_HRW_LEASE_ROUTING_OVERRIDE
            .lock()
            .expect("HRW lease routing override lock poisoned")
            .clone()
        {
            return Ok(config);
        }
    }

    let local_node = read_optional_trimmed_env_string(HRW_LEASE_LOCAL_NODE_ENV)?;
    let eligible_nodes = read_optional_trimmed_env_string(HRW_LEASE_NODES_ENV)?;
    let current_lease_seq = read_env_u64(HRW_LEASE_CURRENT_SEQ_ENV)?;
    parse_hrw_lease_routing_config_from_env_values(
        local_node.as_deref(),
        eligible_nodes.as_deref(),
        current_lease_seq,
    )
}

fn json_schema_declares_singleton_writer(value: &Value) -> bool {
    match value {
        Value::Object(map) => {
            let state_model = map
                .get("x-fcp-state-model")
                .or_else(|| map.get("x-fcp-state_model"))
                .or_else(|| map.get("state_model"))
                .and_then(Value::as_str);
            if state_model == Some("singleton_writer") {
                return true;
            }
            map.values().any(json_schema_declares_singleton_writer)
        }
        Value::Array(values) => values.iter().any(json_schema_declares_singleton_writer),
        _ => false,
    }
}

fn operation_requires_hrw_lease(
    tool: &ToolDescriptor,
    connector_declares_singleton_writer: bool,
) -> bool {
    connector_declares_singleton_writer || json_schema_declares_singleton_writer(&tool.input_schema)
}

fn update_len_prefixed(hasher: &mut blake3::Hasher, bytes: &[u8]) {
    hasher.update(&u64::try_from(bytes.len()).unwrap_or(u64::MAX).to_le_bytes());
    hasher.update(bytes);
}

fn singleton_writer_lease_subject_id(request: &InvokeRequest) -> ObjectId {
    singleton_writer_connector_lease_subject_id(&request.connector_id, &request.zone_id)
}

fn singleton_writer_connector_lease_subject_id(
    connector_id: &ConnectorId,
    zone_id: &ZoneId,
) -> ObjectId {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"FCP-HOST-SINGLETON-WRITER-HRW-LEASE-V2");
    update_len_prefixed(&mut hasher, connector_id.as_str().as_bytes());
    update_len_prefixed(&mut hasher, zone_id.as_str().as_bytes());
    ObjectId::from_bytes(*hasher.finalize().as_bytes())
}

fn lease_node_id_hash(node: &TailscaleNodeId) -> String {
    format!(
        "blake3:{}",
        hex::encode(blake3::hash(node.as_str().as_bytes()).as_bytes())
    )
}

fn lease_expiry_rfc3339(expiry_unix_secs: u64) -> Option<String> {
    let secs = i64::try_from(expiry_unix_secs).ok()?;
    DateTime::<Utc>::from_timestamp(secs, 0)
        .map(|timestamp| timestamp.to_rfc3339_opts(SecondsFormat::Secs, true))
}

fn connector_lease_status_payload(
    connector_id: &ConnectorId,
    zone_id: &ZoneId,
    routing: Option<&HrwLeaseRoutingConfig>,
    durable: &ConnectorLeaseDurableEvidence,
) -> Value {
    const SCHEMA_VERSION: &str = "1.0.0";

    let subject_id = singleton_writer_connector_lease_subject_id(connector_id, zone_id);
    let mut warnings = durable.warnings.clone();
    let mut ranked_holders = Vec::new();
    let mut holder_node_id_hash = Value::Null;
    let mut local_node_id_hash = Value::Null;
    let mut local_is_holder = Value::Null;
    let routing_lease_seq = routing.and_then(|routing| routing.current_lease_seq);
    let durable_lease_seq = durable.lease_seq;
    let fencing_token = routing_lease_seq.or(durable_lease_seq);
    if let (Some(routing_seq), Some(durable_seq)) = (routing_lease_seq, durable_lease_seq)
        && routing_seq != durable_seq
    {
        warnings.push(format!(
            "Host HRW routing fencing token {routing_seq} differs from durable fcp-store lease_seq {durable_seq}; host enforcement follows routing while durable evidence follows the stored lease object."
        ));
    }
    let expiry = durable
        .expiry_unix_secs
        .and_then(lease_expiry_rfc3339)
        .map_or(Value::Null, Value::String);
    let expiry_unix_secs = durable.expiry_unix_secs.map_or(Value::Null, Value::from);
    let quorum_signers_count =
        u64::try_from(durable.quorum_signers_count.unwrap_or(0)).unwrap_or(u64::MAX);
    let required_quorum_signers_count =
        u64::try_from(CONNECTOR_STATE_LEASE_REQUIRED_QUORUM_SIGNATURES).unwrap_or(u64::MAX);
    let quorum_satisfied = durable
        .quorum_signers_count
        .map(|count| count >= CONNECTOR_STATE_LEASE_REQUIRED_QUORUM_SIGNATURES);
    if let Some(count) = durable.quorum_signers_count
        && count < CONNECTOR_STATE_LEASE_REQUIRED_QUORUM_SIGNATURES
    {
        warnings.push(format!(
            "Durable lease object has {count} quorum signatures, below the required {CONNECTOR_STATE_LEASE_REQUIRED_QUORUM_SIGNATURES}; host status treats this as non-quorum lease evidence."
        ));
    }

    if let Some(routing) = routing {
        let ranked = fcp_mesh::planner::rank_lease_holders_by_hrw(
            zone_id,
            &subject_id,
            &routing.eligible_nodes,
        );
        for (index, node) in ranked.iter().enumerate() {
            ranked_holders.push(json!({
                "rank": index + 1,
                "node_id_hash": lease_node_id_hash(node),
                "is_local_node": node == &routing.local_node,
            }));
        }
        if let Some(holder) = ranked.first() {
            holder_node_id_hash = json!(lease_node_id_hash(holder));
            local_node_id_hash = json!(lease_node_id_hash(&routing.local_node));
            local_is_holder = json!(holder == &routing.local_node);
        } else {
            warnings.push(
                "HRW lease routing is configured, but no eligible lease holder was available."
                    .to_owned(),
            );
        }
        if routing.current_lease_seq.is_none() {
            warnings.push(
                "No current fencing token floor is configured; stale lease_seq values cannot be fenced by this status snapshot."
                    .to_owned(),
            );
        }
    } else {
        warnings.push(
            "Singleton-writer HRW lease routing is not configured for this host process."
                .to_owned(),
        );
    }

    json!({
        "status": "ok",
        "command": "fcp-host",
        "subcommand": "connector lease status",
        "schema_version": SCHEMA_VERSION,
        "source": if routing.is_some() { "host-hrw-routing" } else { "host-unconfigured-hrw-routing" },
        "connector_id": connector_id.to_string(),
        "zone_id": zone_id.as_str(),
        "subject_id": subject_id.to_string(),
        "purpose": CoreLeasePurpose::ConnectorStateWrite,
        "holder_node_id_hash": holder_node_id_hash,
        "fencing_token": fencing_token,
        "durable_lease_seq": durable_lease_seq,
        "expiry": expiry,
        "expiry_unix_secs": expiry_unix_secs,
        "quorum_signers_count": quorum_signers_count,
        "required_quorum_signers_count": required_quorum_signers_count,
        "quorum_satisfied": quorum_satisfied,
        "durable_validation": {
            "status": durable.validation_status.unwrap_or("unavailable"),
            "error": durable.validation_error,
            "validated_at_unix_secs": durable.validated_at_unix_secs,
        },
        "lease_object_id": durable.lease_object_id.map(|object_id| object_id.to_string()),
        "lease_evidence_source": durable.source.unwrap_or("unavailable"),
        "local_node_id_hash": local_node_id_hash,
        "local_is_holder": local_is_holder,
        "ranked_holders": ranked_holders,
        "live_host": {
            "requested": true,
            "state": "queried",
            "route_available": true,
            "route": "/rpc/admin/connectors/{connector_id}/lease/status",
        },
        "telemetry": {
            "event_names": metrics::LEASE_EVENT_NAMES,
            "handoffs_counter": metrics::LEASE_HANDOFFS_TOTAL_METRIC,
            "handoff_duration_histogram": metrics::LEASE_HANDOFF_DURATION_SECONDS_METRIC,
            "redaction_scope": "public"
        },
        "warnings": warnings,
    })
}

#[must_use]
fn connector_lease_flush_before_yield_payload(
    connector_id: &ConnectorId,
    zone_id: &ZoneId,
    state_root: &StdPath,
    flush: &fcp_store::ConnectorStateLeaseYieldFlush,
    warnings: Vec<String>,
) -> Value {
    json!({
        "status": "ok",
        "command": "fcp-host",
        "subcommand": "connector lease flush-before-yield",
        "schema_version": "1.0.0",
        "source": "host-canonical-state-flush",
        "connector_id": connector_id.to_string(),
        "zone_id": zone_id.as_str(),
        "state_root": {
            "path": state_root.display().to_string(),
            "source": "host",
        },
        "purpose": CoreLeasePurpose::ConnectorStateWrite,
        "flush": {
            "root_present": flush.root_object_id.is_some(),
            "connector_id": flush.connector_id.to_string(),
            "zone_id": flush.zone_id.as_str(),
            "instance_id": flush.instance_id.as_ref().map(InstanceId::as_str),
            "root_object_id": flush.root_object_id.as_ref().map(ToString::to_string),
            "head_object_id": flush.head_object_id.as_ref().map(ToString::to_string),
            "last_canonical_seq": flush.last_canonical_seq,
            "lease_seq": flush.lease_seq,
            "lease_object_id": flush.lease_object_id.as_ref().map(ToString::to_string),
            "status_source": "fcp-store",
        },
        "telemetry": {
            "event_name": metrics::LEASE_FLUSHED_ON_YIELD_METRIC,
            "purpose_label": CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
            "outcome_label": "success",
            "redaction_scope": "public",
        },
        "warnings": warnings,
    })
}

#[derive(Debug, Serialize)]
#[serde(tag = "code")]
enum HrwLeaseRouteRefusal<'a> {
    LeaseRoutingConfigMissing {
        local_node_env: &'static str,
        node_set_env: &'static str,
    },
    LeaseQuorumConfigInvalid {
        configured_eligible_nodes_count: usize,
        required_quorum_signers_count: usize,
        node_set_env: &'static str,
    },
    NotSelectedCoordinator {
        #[serde(flatten)]
        reason: &'a fcp_mesh::planner::LeaseTransferReason,
        #[serde(skip_serializing_if = "Option::is_none")]
        yield_flush: Option<HrwLeaseYieldFlushEvidence>,
    },
    LeaseFenced {
        zone_id: ZoneId,
        subject_id: ObjectId,
        purpose: CoreLeasePurpose,
        current_lease_seq: u64,
        provided_lease_seq: Option<u64>,
        #[serde(skip_serializing_if = "Option::is_none")]
        handoff_reason: Option<&'a fcp_mesh::planner::LeaseTransferReason>,
        #[serde(skip_serializing_if = "Option::is_none")]
        yield_flush: Option<HrwLeaseYieldFlushEvidence>,
    },
}

#[derive(Debug, Serialize)]
struct HrwLeaseYieldFlushEvidence {
    status: &'static str,
    root_present: bool,
    root_object_id: Option<String>,
    head_object_id: Option<String>,
    last_canonical_seq: Option<u64>,
    lease_seq: Option<u64>,
    lease_object_id: Option<String>,
}

impl From<&fcp_store::ConnectorStateLeaseYieldFlush> for HrwLeaseYieldFlushEvidence {
    fn from(flush: &fcp_store::ConnectorStateLeaseYieldFlush) -> Self {
        Self {
            status: "flushed",
            root_present: flush.root_object_id.is_some(),
            root_object_id: flush.root_object_id.as_ref().map(ToString::to_string),
            head_object_id: flush.head_object_id.as_ref().map(ToString::to_string),
            last_canonical_seq: flush.last_canonical_seq,
            lease_seq: flush.lease_seq,
            lease_object_id: flush.lease_object_id.as_ref().map(ToString::to_string),
        }
    }
}

fn hrw_lease_refusal_message(refusal: &HrwLeaseRouteRefusal<'_>) -> String {
    hrw_lease_refusal_message_for("invoke", refusal)
}

fn hrw_lease_refusal_message_for(action: &str, refusal: &HrwLeaseRouteRefusal<'_>) -> String {
    let payload = serde_json::to_string(refusal).unwrap_or_else(|error| {
        format!("{{\"reason\":\"serialization_error\",\"message\":\"{error}\"}}")
    });
    format!("HRW lease routing refused singleton_writer {action}: {payload}")
}

fn missing_hrw_lease_routing_config_error(action: &str) -> HostError {
    let refusal = HrwLeaseRouteRefusal::LeaseRoutingConfigMissing {
        local_node_env: HRW_LEASE_LOCAL_NODE_ENV,
        node_set_env: HRW_LEASE_NODES_ENV,
    };
    HostError::PreflightFailed(hrw_lease_refusal_message_for(action, &refusal))
}

fn enforce_hrw_singleton_writer_quorum_config(
    action: &str,
    routing: &HrwLeaseRoutingConfig,
) -> HostResult<()> {
    if routing.eligible_nodes.len() >= CONNECTOR_STATE_LEASE_REQUIRED_QUORUM_SIGNATURES {
        return Ok(());
    }
    let refusal = HrwLeaseRouteRefusal::LeaseQuorumConfigInvalid {
        configured_eligible_nodes_count: routing.eligible_nodes.len(),
        required_quorum_signers_count: CONNECTOR_STATE_LEASE_REQUIRED_QUORUM_SIGNATURES,
        node_set_env: HRW_LEASE_NODES_ENV,
    };
    Err(HostError::PreflightFailed(hrw_lease_refusal_message_for(
        action, &refusal,
    )))
}

fn parse_hrw_launch_zone_id(
    connector_id: &ConnectorId,
    allowed_zones: &[String],
) -> HostResult<ZoneId> {
    match allowed_zones {
        [zone] => zone.parse::<ZoneId>().map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid singleton_writer HRW launch zone `{zone}` for connector `{connector_id}`: {error}"
            ))
        }),
        [] => Err(zone_envelope_required_error(connector_id)),
        zones => Err(HostError::InvalidFilter(format!(
            "singleton_writer HRW launch routing for connector `{connector_id}` requires exactly one allowed_zones entry, got {}",
            zones.len()
        ))),
    }
}

fn connector_lease_query_zone_id(
    connector_id: &ConnectorId,
    config: &ConnectorConfig,
    query_zone: Option<&str>,
    action: &str,
) -> HostResult<ZoneId> {
    if let Some(zone) = query_zone.map(str::trim).filter(|zone| !zone.is_empty()) {
        return zone.parse::<ZoneId>().map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid connector lease {action} zone `{zone}`: {error}"
            ))
        });
    }

    if !connector_config_declares_singleton_writer(config) {
        return Ok(ZoneId::work());
    }

    match config.allowed_zones.as_slice() {
        [zone] => zone.parse::<ZoneId>().map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid singleton_writer lease {action} zone `{zone}` for connector `{connector_id}`: {error}"
            ))
        }),
        [] => Err(zone_envelope_required_error(connector_id)),
        zones => Err(HostError::InvalidFilter(format!(
            "singleton_writer lease {action} for connector `{connector_id}` requires an explicit zone query because allowed_zones has {} entries",
            zones.len()
        ))),
    }
}

fn connector_lease_status_zone_id(
    connector_id: &ConnectorId,
    config: &ConnectorConfig,
    query_zone: Option<&str>,
) -> HostResult<ZoneId> {
    connector_lease_query_zone_id(connector_id, config, query_zone, "status")
}

fn connector_lease_flush_before_yield_zone_id(
    connector_id: &ConnectorId,
    config: &ConnectorConfig,
    query_zone: Option<&str>,
) -> HostResult<ZoneId> {
    connector_lease_query_zone_id(connector_id, config, query_zone, "flush-before-yield")
}

fn enforce_hrw_singleton_writer_launch_route(
    config: &ConnectorConfig,
    routing: Option<&HrwLeaseRoutingConfig>,
) -> HostResult<()> {
    if !connector_config_declares_singleton_writer(config) {
        return Ok(());
    }
    let Some(routing) = routing else {
        return Err(missing_hrw_lease_routing_config_error("launch"));
    };
    enforce_hrw_singleton_writer_quorum_config("launch", routing)?;

    let connector_id: ConnectorId = config.id.parse().map_err(|err| {
        HostError::InvalidFilter(format!("invalid connector id '{}': {err}", config.id))
    })?;
    let zone_id = parse_hrw_launch_zone_id(&connector_id, &config.allowed_zones)?;
    let subject_id = singleton_writer_connector_lease_subject_id(&connector_id, &zone_id);
    let selection = fcp_mesh::planner::admit_lease_holder(
        &zone_id,
        &subject_id,
        CoreLeasePurpose::ConnectorStateWrite,
        &routing.eligible_nodes,
        &routing.local_node,
    )
    .map_err(|reason| {
        metrics::record_lease_fenced(
            CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
            "launch_not_selected_coordinator",
        );
        tracing::warn!(
            event = "hrw_lease_launch_refused",
            connector_id = %connector_id,
            zone_id = %zone_id,
            reason = ?reason,
            "singleton_writer connector launch refused by HRW lease routing"
        );
        let refusal = HrwLeaseRouteRefusal::NotSelectedCoordinator {
            reason: &reason,
            yield_flush: None,
        };
        HostError::PreflightFailed(hrw_lease_refusal_message_for("launch", &refusal))
    })?;

    tracing::debug!(
        event = "hrw_lease_launch_admitted",
        connector_id = %connector_id,
        zone_id = %zone_id,
        subject_id = %selection.subject_id,
        holder = %selection.holder.as_str(),
        "singleton_writer connector launch admitted by HRW lease routing"
    );
    Ok(())
}

async fn flush_singleton_writer_before_hrw_yield(
    state: &AppState,
    connector_id: &ConnectorId,
    zone_id: &ZoneId,
    reason: &fcp_mesh::planner::LeaseTransferReason,
) -> HostResult<HrwLeaseYieldFlushEvidence> {
    connector_lease_yield_flush_context_for_registered_connector(state, connector_id, zone_id)
        .await
        .map(|context| {
            metrics::record_lease_flushed_on_yield(
                CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
                "success",
            );
            tracing::warn!(
                event = "hrw_lease_yield_flush_before_refusal",
                connector_id = %connector_id,
                zone_id = %zone_id,
                root_object_id = context.flush.root_object_id.as_ref().map(ToString::to_string),
                head_object_id = context.flush.head_object_id.as_ref().map(ToString::to_string),
                last_canonical_seq = ?context.flush.last_canonical_seq,
                lease_seq = ?context.flush.lease_seq,
                "flushed singleton_writer connector state before HRW lease yield"
            );
            HrwLeaseYieldFlushEvidence::from(&context.flush)
        })
        .map_err(|error| {
            metrics::record_lease_flushed_on_yield(
                CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
                "error",
            );
            let refusal = HrwLeaseRouteRefusal::NotSelectedCoordinator {
                reason,
                yield_flush: None,
            };
            HostError::PreflightFailed(format!(
                "{}; flush-before-yield failed: {error}",
                hrw_lease_refusal_message(&refusal)
            ))
        })
}

async fn enforce_hrw_lease_route(
    state: &AppState,
    request: &InvokeRequest,
    routing: Option<&HrwLeaseRoutingConfig>,
    connector_declares_singleton_writer: bool,
) -> HostResult<()> {
    let subject_id = singleton_writer_lease_subject_id(request);
    let Some(routing) = routing else {
        metrics::record_lease_fenced(
            CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
            "invoke_missing_routing_config",
        );
        return Err(missing_hrw_lease_routing_config_error("invoke"));
    };
    enforce_hrw_singleton_writer_quorum_config("invoke", routing)?;

    let selection = fcp_mesh::planner::admit_lease_holder(
        &request.zone_id,
        &subject_id,
        CoreLeasePurpose::ConnectorStateWrite,
        &routing.eligible_nodes,
        &routing.local_node,
    )
    .map_err(|reason| {
        tracing::warn!(
            event = "hrw_lease_route_refused",
            connector_id = %request.connector_id,
            operation = %request.operation,
            zone_id = %request.zone_id,
            reason = ?reason,
            "singleton_writer invoke refused by HRW lease routing"
        );
        reason
    });
    let selection = match selection {
        Ok(selection) => selection,
        Err(reason) => {
            let yield_flush =
                if connector_declares_singleton_writer && routing.current_lease_seq.is_some() {
                    Some(
                        flush_singleton_writer_before_hrw_yield(
                            state,
                            &request.connector_id,
                            &request.zone_id,
                            &reason,
                        )
                        .await?,
                    )
                } else {
                    None
                };
            if let Some(current_lease_seq) = routing.current_lease_seq
                && request
                    .lease_seq
                    .is_none_or(|provided| provided < current_lease_seq)
            {
                let refusal = HrwLeaseRouteRefusal::LeaseFenced {
                    zone_id: request.zone_id.clone(),
                    subject_id,
                    purpose: CoreLeasePurpose::ConnectorStateWrite,
                    current_lease_seq,
                    provided_lease_seq: request.lease_seq,
                    handoff_reason: Some(&reason),
                    yield_flush,
                };
                metrics::record_lease_fenced(
                    CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
                    "stale_or_missing_lease_seq_after_handoff",
                );
                tracing::warn!(
                    event = "hrw_lease_route_fenced_after_handoff",
                    connector_id = %request.connector_id,
                    operation = %request.operation,
                    zone_id = %request.zone_id,
                    subject_id = %subject_id,
                    current_lease_seq,
                    provided_lease_seq = ?request.lease_seq,
                    reason = ?reason,
                    "singleton_writer invoke refused by stale HRW handoff fence"
                );
                return Err(HostError::PreflightFailed(hrw_lease_refusal_message(
                    &refusal,
                )));
            }
            metrics::record_lease_fenced(
                CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
                "invoke_not_selected_coordinator",
            );
            let refusal = HrwLeaseRouteRefusal::NotSelectedCoordinator {
                reason: &reason,
                yield_flush,
            };
            return Err(HostError::PreflightFailed(hrw_lease_refusal_message(
                &refusal,
            )));
        }
    };

    if let Some(current_lease_seq) = routing.current_lease_seq
        && request
            .lease_seq
            .is_none_or(|provided| provided < current_lease_seq)
    {
        let refusal = HrwLeaseRouteRefusal::LeaseFenced {
            zone_id: request.zone_id.clone(),
            subject_id,
            purpose: CoreLeasePurpose::ConnectorStateWrite,
            current_lease_seq,
            provided_lease_seq: request.lease_seq,
            handoff_reason: None,
            yield_flush: None,
        };
        metrics::record_lease_fenced(
            CONNECTOR_STATE_WRITE_LEASE_PURPOSE_LABEL,
            "stale_or_missing_lease_seq",
        );
        tracing::warn!(
            event = "hrw_lease_route_fenced",
            connector_id = %request.connector_id,
            operation = %request.operation,
            zone_id = %request.zone_id,
            subject_id = %subject_id,
            current_lease_seq,
            provided_lease_seq = ?request.lease_seq,
            "singleton_writer invoke refused by HRW lease fence"
        );
        return Err(HostError::PreflightFailed(hrw_lease_refusal_message(
            &refusal,
        )));
    }

    tracing::debug!(
        event = "hrw_lease_route_admitted",
        connector_id = %request.connector_id,
        operation = %request.operation,
        zone_id = %request.zone_id,
        subject_id = %selection.subject_id,
        holder = %selection.holder.as_str(),
        current_lease_seq = ?routing.current_lease_seq,
        "singleton_writer invoke admitted by HRW lease routing"
    );
    Ok(())
}

fn enforce_live_deployment_tier(request: &InvokeRequest, tier: SafetyTier) -> HostResult<()> {
    let classification = current_deployment_classification();
    match admit_safety_tier(&classification, tier) {
        Ok(()) => Ok(()),
        Err(refusal) => {
            if matches!(
                refusal,
                DeploymentTierRefusal::TierRequiresMeshActive { .. }
            ) {
                let raw = read_optional_trimmed_env_string(OWNER_SINGLE_HOST_ADMISSION_ENV)?;
                if owner_single_host_admission_allows(request, tier, raw.as_deref())? {
                    emit_owner_single_host_admission_audit_event(request, tier);
                    return Ok(());
                }
            }
            emit_deployment_tier_denial_audit_event(request, tier, &classification, &refusal);
            Err(HostError::PreflightFailed(deployment_tier_refusal_message(
                &refusal,
            )))
        }
    }
}

const HOST_STATE_MISSING_VERIFYING_KEY_REASON_PREFIX: &str =
    "No verifying key found for token key ID ";

fn authoritative_persisted_capability_rejection_reason(
    verify: &fcp_host::CapabilityTokenVerifyResponse,
    fallback: &'static str,
) -> Option<String> {
    verify
        .rejection_reasons
        .iter()
        .find(|reason| !reason.starts_with(HOST_STATE_MISSING_VERIFYING_KEY_REASON_PREFIX))
        .cloned()
        .or_else(|| (!verify.temporally_valid || !verify.scope_valid).then(|| fallback.to_string()))
}

const CANCEL_SELF_CONNECTOR_ID: &str = "fcp.host.cancel-self:test:1.0.0";
const CANCEL_SELF_CAPABILITY_ID: &str = "host.cancel-self";
const CANCEL_SELF_OPERATION_ID: &str = "host.cancel-self";

fn enforce_operation_network_constraint_dispatch(
    snapshot: &AllowListSnapshot,
    request: &InvokeRequest,
) -> HostResult<()> {
    if !snapshot.enforce_operation_network_constraints {
        return Ok(());
    }

    let Some(source) = snapshot.manifest_constraints.source.as_deref() else {
        return Err(HostError::PreflightFailed(format!(
            "connector `{}` has enforce_operation_network_constraints=true but no `manifest_path` was configured; deny-all",
            request.connector_id
        )));
    };
    let operation = request.operation.as_str();
    if !snapshot
        .manifest_constraints
        .declared_operations
        .contains(operation)
    {
        return Err(HostError::PreflightFailed(format!(
            "connector `{}` manifest `{source}` does not declare operation `{operation}`; deny-all",
            request.connector_id
        )));
    }
    let Some(constraints) = snapshot
        .manifest_constraints
        .network_constraints
        .get(operation)
    else {
        return Err(HostError::PreflightFailed(format!(
            "connector `{}` operation `{operation}` has no manifest `network_constraints` in `{source}`; deny-all",
            request.connector_id
        )));
    };

    let correlation_id = request
        .correlation_id
        .as_ref()
        .map(std::string::ToString::to_string);
    tracing::warn!(
        connector_id = %request.connector_id,
        operation,
        zone_id = %request.zone_id,
        correlation_id = correlation_id.as_deref().unwrap_or(""),
        constraint_source = source,
        allowed_host_count = constraints.host_allow.len(),
        allowed_port_count = constraints.port_allow.len(),
        connect_timeout_ms = constraints.connect_timeout_ms,
        total_timeout_ms = constraints.total_timeout_ms,
        max_response_bytes = constraints.max_response_bytes,
        "refusing native subprocess invoke because no host-mediated egress guard is wired for selected operation network constraints"
    );
    Err(HostError::PreflightFailed(format!(
        "connector `{}` operation `{operation}` selected manifest network_constraints from `{source}`, but native subprocess dispatch has no host-mediated egress guard; refusing direct egress",
        request.connector_id
    )))
}

async fn verify_live_request(
    state: &AppState,
    request: &InvokeRequest,
    principal_override: Option<&str>,
) -> HostResult<VerifiedLiveRequest> {
    verify_live_request_with_resource(state, request, principal_override, None).await
}

async fn verify_live_request_with_resource(
    state: &AppState,
    request: &InvokeRequest,
    principal_override: Option<&str>,
    trusted_resource: Option<&TrustedResourceBinding>,
) -> HostResult<VerifiedLiveRequest> {
    // Connector home-zone binding (br-flywheel_connectors-by4vu).
    //
    // Without this gate, a structurally-valid capability token signed for
    // zone Z lets the holder invoke ANY connector whose operations match
    // the token's `capability` claim — even connectors whose manifest pins
    // them to a different zone (e.g. a `home = z:work` connector reachable
    // from a `z:secure` request). The gateway never consulted any
    // connector-side zone declaration before this check.
    //
    // Enforcement is mandatory: an empty `allowed_zones` list means the
    // connector has no explicit zone envelope, so host-facing RPC rejects
    // before consulting connector self-report. The error path emits a
    // distinct rejection message so receipts and logs distinguish missing
    // zone-envelope inventory from generic preflight failures.
    //
    // Capture allow-list, runtime policy, manifest metadata, and the opaque
    // per-invocation plan under one registry read lock. The generation is
    // copied into the plan and revalidated immediately before spawn.
    let live_snapshot = state
        .registry
        .live_request_registry_snapshot(request)
        .await?;
    let allow_snapshot = &live_snapshot.allow_list;
    let allowed = &allow_snapshot.allowed_zones;
    require_allowed_zones_configured(&request.connector_id, allowed)?;
    if !allowed.iter().any(|zone| zone == request.zone_id.as_str()) {
        return Err(HostError::PreflightFailed(format!(
            "connector `{}` is not bound to zone `{}` (allowed: [{}])",
            request.connector_id,
            request.zone_id.as_str(),
            allowed.join(", ")
        )));
    }

    // br-ike8x: operator-pinned operation gate. The pre-existing
    // operation check (against `introspection.tools` further down)
    // trusts the connector's runtime self-report — a malicious or
    // drifted connector binary that adds new operations under a
    // permissive `tool.capability` would pass that gate even if the
    // operator never approved those ops in the manifest. The
    // ConnectorManifestCheck in `crates/fcp-host/src/enforcement.rs`
    // was designed for exactly this purpose but was never wired
    // into the production invoke path. Mirror the `allowed_zones`
    // shape directly here: when the operator pins a non-empty
    // `allowed_operations` set on the ManagedConnectorConfig, the
    // host gateway rejects requests whose `operation` is not in it.
    // Empty preserves pre-pinning behavior for back-compat.
    // br-v2kt4: same explicit fail-closed shape for empty allowed_operations.
    // br-l9tt6: re-uses the snapshot captured above so both gates
    // decide against the same atomic read.
    let allowed_ops = &allow_snapshot.allowed_operations;
    if allowed_ops.is_empty() {
        if allow_snapshot.enforce_empty_allow_lists {
            return Err(HostError::PreflightFailed(format!(
                "connector `{}` has no `allowed_operations` and is configured \
                 enforce_empty_allow_lists=true; deny-all (br-v2kt4)",
                request.connector_id
            )));
        }
        // Empty allowed_operations with the legacy flag disabled falls
        // through to the connector introspection operation check.
    } else if !allowed_ops
        .iter()
        .any(|op| op == request.operation.as_str())
    {
        return Err(HostError::PreflightFailed(format!(
            "connector `{}` does not allow operation `{}` (allowed: [{}])",
            request.connector_id,
            request.operation.as_str(),
            allowed_ops.join(", ")
        )));
    }

    if live_snapshot.per_invocation_plan.is_none() {
        enforce_operation_network_constraint_dispatch(allow_snapshot, request)?;
        state
            .registry
            .enforce_runtime_network_policy_snapshot(request, &live_snapshot.runtime_network)?;
    }

    let introspection = state.discovery.introspect(&request.connector_id).await?;
    let tool = introspection
        .tools
        .iter()
        .find(|tool| tool.name == request.operation.as_str())
        .ok_or_else(|| {
            HostError::InvalidFilter(format!(
                "connector `{}` does not expose operation `{}`",
                request.connector_id, request.operation
            ))
        })?;

    let capability_key = state.capability_verifying_key.as_ref().ok_or_else(|| {
        HostError::PreflightFailed(
            "FCP_HOST_CAPABILITY_PUBLIC_KEY[_FILE] is not configured, so live auth checks cannot be verified"
                .to_string(),
        )
    })?;
    let constraint_resource_uri = verified_live_constraint_resource_uri(request, trusted_resource)?;
    let constraint_resource_uris = constraint_resource_uri
        .iter()
        .cloned()
        .collect::<Vec<String>>();
    // The gateway verifies from the zone vantage and deliberately does not
    // claim instance binding. A SubprocessConnector can pin an explicit
    // requested instance ID during handshake, but the connector process is
    // still the enforcement point that compares that ID with the signed
    // token. Use `without_instance_binding` here and defer the fifth check to
    // that connector-side verifier.
    // (br-flywheel_connectors-5qp7o).
    let verifier = CapabilityVerifier::without_instance_binding(
        capability_key.to_bytes(),
        request.zone_id.clone(),
    );
    // br-jkcka.8: gateway vantage produces UnboundVerified. The connector
    // process (which knows its real InstanceId) is expected to re-verify
    // with CapabilityVerifier::new or promote_with_instance before
    // executing the operation. See docs/architecture/adr/jkcka-typestate-split.md.
    let verified_token = verifier
        .verify_unbound(
            request.capability_token.clone(),
            &tool.capability,
            &request.operation,
            &constraint_resource_uris,
        )
        .map_err(|error| {
            HostError::PreflightFailed(format!("capability token rejected: {error}"))
        })?;
    let verified_claims = verified_token.claims();

    // m8j0q.A.9 / br-yowdy: reject directly-revoked tokens and revoked
    // issuer-chain hops through the bounded fcp-evidence cascade walker before
    // the live request can proceed into holder proof or persisted token-state
    // validation.
    verify_live_revocation_cascade(state, &request.capability_token, verified_claims)?;
    verify_live_hybrid_owner_capability(state, request)?;

    enforce_live_deployment_tier(request, tool.safety_tier)?;

    let connector_declares_singleton_writer = state
        .registry
        .connector_requires_singleton_writer(&request.connector_id)
        .await;
    if operation_requires_hrw_lease(tool, connector_declares_singleton_writer) {
        let routing = current_hrw_lease_routing_config()?;
        enforce_hrw_lease_route(
            state,
            request,
            routing.as_ref(),
            connector_declares_singleton_writer,
        )
        .await?;
    }

    // SECURITY: holder-bound tokens (`holder_node` claim present) must never
    // silently degrade to bearer tokens. Until fcp-host wires live holder-proof
    // signature verification against node attestations, fail closed here.
    if let Some(expected_holder) = verified_claims.get_holder_node() {
        let Some(holder_proof) = request.holder_proof.as_ref() else {
            return Err(HostError::PreflightFailed(format!(
                "capability token is holder-bound to `{expected_holder}`, but the request did not include holder_proof"
            )));
        };
        if holder_proof.holder_node.as_str() != expected_holder {
            return Err(HostError::PreflightFailed(format!(
                "holder_proof node `{}` does not match capability token holder_node `{expected_holder}`",
                holder_proof.holder_node.as_str()
            )));
        }
        return Err(HostError::PreflightFailed(format!(
            "capability token is holder-bound to `{expected_holder}`, but fcp-host does not yet verify holder_proof signatures for live requests"
        )));
    }

    let persisted_verify = state
        .lifecycle
        .verify_capability_token(&CapabilityTokenVerifyRequest {
            token_cbor_b64: capability_token_b64(&request.capability_token)?,
            operation_id: Some(request.operation.to_string()),
            connector_id: Some(request.connector_id.to_string()),
        })
        .await
        .map_err(|error| {
            HostError::PreflightFailed(format!("persisted capability verification failed: {error}"))
        })?;
    if !persisted_verify.valid
        && let Some(reason) = authoritative_persisted_capability_rejection_reason(
            &persisted_verify,
            "persisted capability verification rejected the live request",
        )
    {
        return Err(HostError::PreflightFailed(format!(
            "capability token rejected by host state: {reason}"
        )));
    }

    let principal = claims_principal(verified_claims).ok_or_else(|| {
        HostError::PreflightFailed(
            "capability token is missing the subject or principal_id claim required for live execution".to_string(),
        )
    })?;
    if let Some(expected) = principal_override
        && expected != principal
    {
        return Err(HostError::PreflightFailed(format!(
            "request principal `{expected}` does not match capability token subject/principal_id `{principal}`"
        )));
    }

    verify_approval_tokens(
        &request.approval_tokens,
        state.approval_verifying_key.as_ref(),
    )?;

    let approval_required = tool
        .approval_mode
        .is_some_and(|mode| !matches!(mode, ApprovalMode::None));
    let mcp_access_dry_run = request.operation.as_str() == "n8n.mcp_access.reconcile"
        && request.input.get("dryRun").and_then(Value::as_bool) == Some(true);
    let (policy_request, policy_input_hash) = n8n_official_mcp_policy_request(
        request,
        trusted_resource,
        constraint_resource_uri.as_deref(),
    )?;
    let zone_policy = state.lookup_zone_policy(&request.zone_id).await?;
    let receipt = simulate_policy_decision(&PolicySimulationInput {
        zone_policy,
        invoke_request: policy_request,
        transport: TransportMode::Lan,
        checkpoint_fresh: true,
        revocation_fresh: true,
        execution_approval_required: approval_required && !mcp_access_dry_run,
        sanitizer_receipts: Vec::new(),
        related_object_ids: Vec::new(),
        request_object_id: None,
        request_input_hash: Some(policy_input_hash),
        safety_tier: tool.safety_tier,
        principal: Some(principal.to_owned()),
        capability_id: Some(tool.capability.to_string()),
        provenance_record: None,
        now_ms: None,
        posture_attestation: None,
    })
    .map_err(|error| HostError::PreflightFailed(format!("policy evaluation failed: {error}")))?;

    if receipt.decision == Decision::Deny {
        return Err(HostError::PreflightFailed(format!(
            "policy denied live request: {}",
            receipt.reason_code
        )));
    }

    enforce_live_capability_constraints(
        request,
        verified_claims,
        principal,
        constraint_resource_uri.as_deref(),
    )?;
    state
        .registry
        .enforce_invoke_rate_limits(request, &introspection, principal)
        .await?;

    Ok(VerifiedLiveRequest {
        principal: principal.to_owned(),
        approval_required,
        safety_tier: tool.safety_tier,
        per_invocation_plan: live_snapshot.per_invocation_plan,
    })
}

fn n8n_official_mcp_policy_request(
    request: &InvokeRequest,
    trusted_resource: Option<&TrustedResourceBinding>,
    resource_uri: Option<&str>,
) -> HostResult<(InvokeRequest, [u8; 32])> {
    if request.connector_id.as_str() == "fcp.n8n"
        && trusted_resource.is_some()
        && N8N_WRITE_OPERATIONS.contains(&request.operation.as_str())
        && !(request.operation.as_str() == "n8n.mcp_access.reconcile"
            && request.input.get("dryRun").and_then(Value::as_bool) == Some(true))
    {
        let binding = trusted_resource.expect("checked above");
        let resource_uri = resource_uri.ok_or_else(|| {
            HostError::PreflightFailed("n8n approval requires a verified resource URI".to_string())
        })?;
        return Ok((
            request.clone(),
            n8n_run_once_binding_hash(
                binding.server_id,
                resource_uri,
                request.operation.as_str(),
                &request.input,
            )?,
        ));
    }
    if request.connector_id.as_str() != "fcp.mcp-bridge"
        || request.operation.as_str() != N8N_OFFICIAL_MCP_CALL_OPERATION
    {
        return Ok((request.clone(), request_input_hash(&request.input)?));
    }

    let binding = trusted_resource.ok_or_else(|| {
        HostError::PreflightFailed(
            "official MCP approval requires a trusted resource binding".to_string(),
        )
    })?;
    let resource_uri = resource_uri.ok_or_else(|| {
        HostError::PreflightFailed(
            "official MCP approval requires a verified resource URI".to_string(),
        )
    })?;
    let payload_digest = mcp_tools_call_payload_digest(&request.input)?;
    let tool_name = request.input.get("name").cloned().unwrap_or(Value::Null);
    let normalized = json!({
        "server_id": binding.server_id.as_str(),
        "resource_uri": resource_uri,
        "operation": request.operation.as_str(),
        "provider": "mcp",
        "payload_sha256": hex::encode(payload_digest),
        "tool_name": tool_name,
    });
    let mut policy_request = request.clone();
    policy_request.input = normalized;
    Ok((policy_request, payload_digest))
}

fn preflight_response_from_error(error: HostError) -> PreflightResponse {
    let reason = error.to_string();
    let mut response = PreflightResponse::denied(&reason);
    response.reason = Some(reason);
    response
}

fn track_verified_cancellation_owner(
    cancellation: &CancellationController,
    operation_id: &str,
    request: &InvokeRequest,
) -> HostResult<()> {
    let verified_claims = request
        .capability_token
        .raw()
        .claims_unverified()
        .map_err(|error| {
            HostError::Internal(format!(
                "verified live request lost readable capability claims before cancellation tracking: {error}"
            ))
        })?;
    let cancellation_owner = claims_principal(&verified_claims).ok_or_else(|| {
        HostError::Internal(
            "verified live request lost the subject/principal_id claim before cancellation tracking"
                .to_string(),
        )
    })?;
    cancellation.track_with_owner(operation_id, Some(cancellation_owner));
    Ok(())
}

async fn verified_cancellation_principal(
    state: &AppState,
    request: &CancellationRequest,
) -> HostResult<String> {
    let capability_token = request.capability_token.as_ref().ok_or_else(|| {
        HostError::PreflightFailed("capability token is required for /rpc/cancel-self".to_string())
    })?;
    let persisted_verify = state
        .lifecycle
        .verify_capability_token(&CapabilityTokenVerifyRequest {
            token_cbor_b64: capability_token_b64(capability_token)?,
            operation_id: Some(CANCEL_SELF_OPERATION_ID.to_string()),
            connector_id: Some(CANCEL_SELF_CONNECTOR_ID.to_string()),
        })
        .await
        .map_err(|error| {
            HostError::PreflightFailed(format!("persisted capability verification failed: {error}"))
        })?;
    if !persisted_verify.valid {
        let reason = persisted_verify
            .rejection_reasons
            .first()
            .cloned()
            .unwrap_or_else(|| {
                "persisted capability verification rejected the cancel-self request".to_string()
            });
        return Err(HostError::PreflightFailed(format!(
            "capability token rejected by host state: {reason}"
        )));
    }

    let verified_claims = capability_token
        .raw()
        .claims_unverified()
        .map_err(|error| {
            HostError::PreflightFailed(format!(
                "verified cancellation token lost readable capability claims: {error}"
            ))
        })?;
    if verified_claims.get_capability_id() != Some(CANCEL_SELF_CAPABILITY_ID) {
        return Err(HostError::PreflightFailed(format!(
            "/rpc/cancel-self requires `{CANCEL_SELF_CAPABILITY_ID}` capability token"
        )));
    }
    if let Some(expected_holder) = verified_claims.get_holder_node() {
        return Err(HostError::PreflightFailed(format!(
            "capability token is holder-bound to `{expected_holder}`, but /rpc/cancel-self does not accept holder-bound tokens"
        )));
    }

    let principal = claims_principal(&verified_claims)
        .map(str::trim)
        .filter(|principal| !principal.is_empty())
        .ok_or_else(|| {
            HostError::PreflightFailed(
                "capability token missing subject/principal_id claim".to_string(),
            )
        })?;
    Ok(principal.to_string())
}

async fn evaluate_verified_live_preflight(
    state: &AppState,
    request: &InvokeRequest,
    principal_override: Option<&str>,
) -> HostResult<VerifiedLiveRequest> {
    evaluate_verified_live_preflight_with_resource(state, request, principal_override, None).await
}

async fn evaluate_verified_live_preflight_with_resource(
    state: &AppState,
    request: &InvokeRequest,
    principal_override: Option<&str>,
    trusted_resource: Option<&TrustedResourceBinding>,
) -> HostResult<VerifiedLiveRequest> {
    let response = state
        .discovery
        .preflight(PreflightRequest {
            connector_id: request.connector_id.clone(),
            operation: request.operation.to_string(),
            params: Some(request.input.clone()),
            principal: principal_override.map(ToOwned::to_owned),
            zone_id: Some(request.zone_id.clone()),
        })
        .await;
    if !response.allowed {
        return Err(HostError::PreflightFailed(
            response
                .reason
                .unwrap_or_else(|| "live preflight denied request".to_string()),
        ));
    }
    verify_live_request_with_resource(state, request, principal_override, trusted_resource).await
}

async fn evaluate_live_preflight(
    state: &AppState,
    request: &InvokeRequest,
    principal_override: Option<&str>,
) -> PreflightResponse {
    let mut response = state
        .discovery
        .preflight(PreflightRequest {
            connector_id: request.connector_id.clone(),
            operation: request.operation.to_string(),
            params: Some(request.input.clone()),
            principal: principal_override.map(ToOwned::to_owned),
            zone_id: Some(request.zone_id.clone()),
        })
        .await;

    match if response.allowed {
        verify_live_request(state, request, principal_override).await
    } else {
        Err(HostError::PreflightFailed(
            response
                .reason
                .clone()
                .unwrap_or_else(|| "live preflight denied request".to_string()),
        ))
    } {
        Ok(verified) => {
            tracing::debug!(
                event = "live_request_verified",
                connector_id = %request.connector_id,
                operation = %request.operation,
                principal = %verified.principal,
                approval_required = verified.approval_required,
                safety_tier = ?verified.safety_tier,
                "live request auth verified"
            );
            response
        }
        Err(error) => {
            response.allowed = false;
            response.reason = Some(error.to_string());
            response
        }
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct DiscoveryRequestBody {
    #[serde(default)]
    filter: Option<DiscoveryFilter>,
    #[serde(rename = "_cache", default)]
    cache: Option<CacheValidator>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
struct HttpBatchInvokeRequest {
    operations: Vec<HttpBatchOperation>,
    #[serde(default)]
    options: BatchOptions,
}

impl HttpBatchInvokeRequest {
    fn planning_request(&self) -> BatchInvokeRequest {
        BatchInvokeRequest {
            operations: self
                .operations
                .iter()
                .map(|operation| BatchOperation {
                    id: operation.id.clone(),
                    tool: format!(
                        "{}#{}",
                        operation.request.connector_id, operation.request.operation
                    ),
                    input: serde_json::Value::Null,
                    depends_on: operation.depends_on.clone(),
                    zone: Some(operation.request.zone_id.clone()),
                    scheduler: operation.scheduler.clone(),
                })
                .collect(),
            options: self.options.clone(),
        }
    }
}

