fn select_run_once_connector_config(
    loaded_configs: LoadedConnectorConfigs,
    connector_id: &ConnectorId,
) -> HostResult<LoadedConnectorConfigs> {
    let target_id = connector_id.to_string();
    let mut selected = loaded_configs
        .configs
        .into_iter()
        .filter(|config| config.id == target_id);
    let Some(config) = selected.next() else {
        return Err(HostError::ConnectorNotFound(
            "run-once connector is not configured".to_string(),
        ));
    };
    if selected.next().is_some() {
        return Err(HostError::InvalidFilter(
            "run-once connector inventory contains duplicate entries".to_string(),
        ));
    }
    if config.lifecycle_mode != ConnectorLifecycleMode::PerInvocation {
        return Err(HostError::InvalidFilter(
            "run-once requires a per-invocation connector configuration".to_string(),
        ));
    }
    Ok(LoadedConnectorConfigs {
        configs: vec![config],
        connectors_file: loaded_configs.connectors_file,
    })
}

fn bind_n8n_run_once_connector_instance(
    loaded_configs: &mut LoadedConnectorConfigs,
    instance_id: &InstanceId,
) -> HostResult<()> {
    let config = loaded_configs.configs.first_mut().ok_or_else(|| {
        HostError::ConnectorNotFound(
            "n8n read-only run-once connector is not configured".to_string(),
        )
    })?;
    if config.id != "fcp.n8n" || config.lifecycle_mode != ConnectorLifecycleMode::PerInvocation {
        return Err(HostError::PreflightFailed(
            "n8n read-only run-once instance binding was denied".to_string(),
        ));
    }
    config.env.insert(
        REQUESTED_INSTANCE_ID_ENV.to_string(),
        instance_id.to_string(),
    );
    Ok(())
}

fn bind_n8n_official_mcp_run_once_connector_instance(
    loaded_configs: &mut LoadedConnectorConfigs,
    instance_id: &InstanceId,
) -> HostResult<()> {
    let config = loaded_configs.configs.first_mut().ok_or_else(|| {
        HostError::ConnectorNotFound(
            "n8n official MCP run-once connector is not configured".to_string(),
        )
    })?;
    if config.id != "fcp.mcp-bridge"
        || config.lifecycle_mode != ConnectorLifecycleMode::PerInvocation
    {
        return Err(HostError::PreflightFailed(
            "n8n official MCP run-once instance binding was denied".to_string(),
        ));
    }
    config.env.insert(
        REQUESTED_INSTANCE_ID_ENV.to_string(),
        instance_id.to_string(),
    );
    Ok(())
}

fn run_once_invoke_error(status: StatusCode) -> HostError {
    if status == StatusCode::BAD_REQUEST {
        HostError::InvalidFilter("run-once request was rejected".to_string())
    } else if status == StatusCode::FORBIDDEN {
        HostError::PreflightFailed("run-once request was denied".to_string())
    } else if status == StatusCode::NOT_FOUND {
        HostError::ConnectorNotFound("run-once connector was not found".to_string())
    } else if status == StatusCode::SERVICE_UNAVAILABLE {
        HostError::Unavailable("run-once connector was unavailable".to_string())
    } else {
        HostError::Internal("run-once invocation failed".to_string())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum N8nRunOnceFailureStage {
    Input,
    Config,
    Plan,
    Credential,
    Policy,
    RuntimeState,
    Manifest,
    Capability,
    Invoke,
}

impl N8nRunOnceFailureStage {
    const fn marker(self) -> &'static str {
        match self {
            Self::Input => "n8n-run-once-stage:input",
            Self::Config => "n8n-run-once-stage:config",
            Self::Plan => "n8n-run-once-stage:plan",
            Self::Credential => "n8n-run-once-stage:credential",
            Self::Policy => "n8n-run-once-stage:policy",
            Self::RuntimeState => "n8n-run-once-stage:runtime-state",
            Self::Manifest => "n8n-run-once-stage:manifest",
            Self::Capability => "n8n-run-once-stage:capability",
            Self::Invoke => "n8n-run-once-stage:invoke",
        }
    }

    const fn wire_code(self) -> &'static str {
        match self {
            Self::Input => "n8n_input_failed",
            Self::Config => "n8n_config_failed",
            Self::Plan => "n8n_plan_failed",
            Self::Credential => "n8n_credential_failed",
            Self::Policy => "n8n_policy_failed",
            Self::RuntimeState => "n8n_runtime_state_failed",
            Self::Manifest => "n8n_manifest_failed",
            Self::Capability => "n8n_capability_failed",
            Self::Invoke => "n8n_invoke_failed",
        }
    }

    fn from_marker(marker: &str) -> Option<Self> {
        [
            Self::Input,
            Self::Config,
            Self::Plan,
            Self::Credential,
            Self::Policy,
            Self::RuntimeState,
            Self::Manifest,
            Self::Capability,
            Self::Invoke,
        ]
        .into_iter()
        .find(|stage| stage.marker() == marker)
    }
}

fn n8n_run_once_stage_error(stage: N8nRunOnceFailureStage) -> HostError {
    HostError::Internal(stage.marker().to_string())
}

