async fn connector_config_rollback_handler(
    State(state): State<Arc<AppState>>,
    Path(connector_id): Path<String>,
    Json(request): Json<ConnectorConfigRollbackRequest>,
) -> Result<Json<ConnectorConfigApplyResponse>, (StatusCode, String)> {
    let connector_id = parse_connector_id(&connector_id)?;
    let started_at = Instant::now();
    tracing::debug!(
        event = "connector_config_rollback_request",
        connector_id = %connector_id,
        revision_id = request.revision_id,
        "processing connector config rollback request"
    );
    let context = load_connector_config_context(&state, &connector_id)
        .await
        .map_err(map_host_error)?;
    let revision = find_config_revision(&context, &connector_id, request.revision_id)
        .map_err(map_host_error)?;
    if !revision.is_replayable() {
        return Err(map_host_error(HostError::InvalidFilter(format!(
            "config revision '{}' for connector '{}' contains redacted inline secrets and cannot be replayed safely",
            request.revision_id, connector_id
        ))));
    }
    let response = apply_connector_config_payload(
        &state,
        &connector_id,
        revision.payload.clone(),
        request.expected_active_revision_id,
        request.created_by,
        request.change_reason.or_else(|| {
            Some(format!(
                "rollback to config revision {}",
                request.revision_id
            ))
        }),
    )
    .await
    .map_err(map_host_error)?;
    tracing::info!(
        event = "connector_config_rollback_response",
        connector_id = %connector_id,
        revision_id = request.revision_id,
        current_active_revision_id = ?response.current_active_revision_id,
        duration_ms = started_at.elapsed().as_millis() as u64,
        "connector config rollback request complete"
    );
    Ok(Json(response))
}

async fn preflight_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<HostPreflightRequest>,
) -> Json<PreflightResponse> {
    let connector_id = request.connector_id.clone();
    let operation = request.operation.clone();
    let asserted_principal =
        extract_principal_header(&headers).or_else(|| request.principal.clone());
    let started_at = Instant::now();
    let response = match invoke_request_from_preflight(&request) {
        Ok(invoke_request) => {
            evaluate_live_preflight(&state, &invoke_request, asserted_principal.as_deref()).await
        }
        Err(error) => preflight_response_from_error(error),
    };
    tracing::info!(
        event = "preflight_check",
        connector_id = %connector_id,
        operation = %operation,
        asserted_principal = asserted_principal.as_deref(),
        allowed = response.allowed,
        reason = ?response.reason,
        duration_ms = started_at.elapsed().as_millis() as u64,
        "preflight request complete"
    );
    Json(response)
}

async fn simulate_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<HostSimulateRequest>,
) -> Result<Json<HostSimulateResponse>, (StatusCode, String)> {
    let connector_id = request.connector_id.clone();
    let operation = request.operation.clone();
    let request_id = request.request_id.clone();
    let asserted_principal =
        extract_principal_header(&headers).or_else(|| request.principal.clone());
    let started_at = Instant::now();

    tracing::debug!(
        event = "simulate_request",
        connector_id = %connector_id,
        operation = %operation,
        request_id = %request_id,
        asserted_principal = asserted_principal.as_deref(),
        estimate_cost = request.estimate_cost,
        check_availability = request.check_availability,
        deadline_ms = request.deadline_ms,
        "processing simulate request"
    );

    let preflight_request = match invoke_request_from_simulate(&request) {
        Ok(preflight_request) => preflight_request,
        Err(error) => {
            let input = request.input.clone().unwrap_or(serde_json::Value::Null);
            let duration_ms = elapsed_millis(started_at);
            let response = HostSimulateResponse {
                request_id: request_id.clone(),
                would_succeed: false,
                phase: SimulatePhase::PreflightOnly,
                preflight_allowed: false,
                failure_reason: Some(error.to_string()),
                denial_code: None,
                missing_capabilities: Vec::new(),
                cost_estimate: None,
                availability: None,
                duration_ms,
                receipt: simulate_receipt_for_request(
                    &request,
                    &input,
                    SimulatePhase::PreflightOnly,
                    false,
                    duration_ms,
                )
                .map_err(map_host_error)?,
            };
            record_simulate_receipt_summary(state.lifecycle.as_ref(), &response.receipt).await;
            tracing::info!(
                event = "simulate_response",
                connector_id = %connector_id,
                operation = %operation,
                request_id = %request_id,
                phase = ?response.phase,
                preflight_allowed = response.preflight_allowed,
                would_succeed = response.would_succeed,
                receipt_id = %response.receipt.receipt_id,
                duration_ms = response.duration_ms,
                "simulate request complete"
            );
            return Ok(Json(response));
        }
    };

    let preflight =
        evaluate_live_preflight(&state, &preflight_request, asserted_principal.as_deref()).await;
    if !preflight.allowed {
        let input = request.input.clone().unwrap_or(serde_json::Value::Null);
        let duration_ms = elapsed_millis(started_at);
        let response = HostSimulateResponse {
            request_id: request_id.clone(),
            would_succeed: false,
            phase: SimulatePhase::PreflightOnly,
            preflight_allowed: false,
            failure_reason: Some(
                preflight
                    .reason
                    .unwrap_or_else(|| "preflight denied live simulate request".to_string()),
            ),
            denial_code: None,
            missing_capabilities: Vec::new(),
            cost_estimate: None,
            availability: None,
            duration_ms,
            receipt: simulate_receipt_for_request(
                &request,
                &input,
                SimulatePhase::PreflightOnly,
                false,
                duration_ms,
            )
            .map_err(map_host_error)?,
        };
        record_simulate_receipt_summary(state.lifecycle.as_ref(), &response.receipt).await;
        tracing::info!(
            event = "simulate_response",
            connector_id = %connector_id,
            operation = %operation,
            request_id = %request_id,
            phase = ?response.phase,
            preflight_allowed = response.preflight_allowed,
            would_succeed = response.would_succeed,
            receipt_id = %response.receipt.receipt_id,
            duration_ms = response.duration_ms,
            "simulate request complete"
        );
        return Ok(Json(response));
    }

    let simulate_request = simulate_request_from_host(&request).map_err(map_host_error)?;
    let simulate_input = simulate_request.input.clone();
    let simulate_result = fcp_async_core::time::timeout(
        Duration::from_millis(request.deadline_ms),
        state.registry.simulate(simulate_request),
    )
    .await;
    let duration_ms = elapsed_millis(started_at);

    let response = match simulate_result {
        Ok(Ok(simulate_response)) => HostSimulateResponse {
            request_id: request_id.clone(),
            would_succeed: simulate_response.would_succeed,
            phase: SimulatePhase::ConnectorReached,
            preflight_allowed: true,
            failure_reason: simulate_response.failure_reason,
            denial_code: simulate_response.denial_code,
            missing_capabilities: simulate_response.missing_capabilities,
            cost_estimate: simulate_response
                .estimated_cost
                .map(map_simulate_cost_estimate),
            availability: simulate_response
                .availability
                .map(map_simulate_resource_availability),
            duration_ms,
            receipt: simulate_receipt_for_request(
                &request,
                &simulate_input,
                SimulatePhase::ConnectorReached,
                simulate_response.would_succeed,
                duration_ms,
            )
            .map_err(map_host_error)?,
        },
        Ok(Err(error)) if is_simulate_unsupported(&error) => HostSimulateResponse {
            request_id: request_id.clone(),
            would_succeed: false,
            phase: SimulatePhase::ConnectorUnsupported,
            preflight_allowed: true,
            failure_reason: Some(
                "connector does not support simulation for this operation".to_string(),
            ),
            denial_code: None,
            missing_capabilities: Vec::new(),
            cost_estimate: None,
            availability: None,
            duration_ms,
            receipt: simulate_receipt_for_request(
                &request,
                &simulate_input,
                SimulatePhase::ConnectorUnsupported,
                false,
                duration_ms,
            )
            .map_err(map_host_error)?,
        },
        Ok(Err(error)) => {
            tracing::warn!(
                event = "simulate_error",
                connector_id = %connector_id,
                operation = %operation,
                request_id = %request_id,
                error = %error,
                duration_ms,
                "simulate request failed"
            );
            return Err(map_host_error(error));
        }
        Err(_) => HostSimulateResponse {
            request_id: request_id.clone(),
            would_succeed: false,
            phase: SimulatePhase::TimedOut,
            preflight_allowed: true,
            failure_reason: Some("simulation deadline exceeded".to_string()),
            denial_code: None,
            missing_capabilities: Vec::new(),
            cost_estimate: None,
            availability: None,
            duration_ms,
            receipt: simulate_receipt_for_request(
                &request,
                &simulate_input,
                SimulatePhase::TimedOut,
                false,
                duration_ms,
            )
            .map_err(map_host_error)?,
        },
    };

    record_simulate_receipt_summary(state.lifecycle.as_ref(), &response.receipt).await;
    tracing::info!(
        event = "simulate_response",
        connector_id = %connector_id,
        operation = %operation,
        request_id = %request_id,
        phase = ?response.phase,
        preflight_allowed = response.preflight_allowed,
        would_succeed = response.would_succeed,
        receipt_id = %response.receipt.receipt_id,
        duration_ms = response.duration_ms,
        "simulate request complete"
    );

    Ok(Json(response))
}

const MCP_SAMPLING_HANDLE_OPERATION: &str = "mcp.sampling.handle";
const MCP_SAMPLING_EVENT: &str = "mcp_sampling_request_received";
const MCP_SAMPLING_HOST_DISPATCH_FIELD: &str = "host_dispatch";
const MCP_SAMPLING_HOST_DISPATCH_ALT_FIELD: &str = "host_sampling_dispatch";

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
struct McpSamplingHostDispatch {
    #[serde(default)]
    connector_id: Option<ConnectorId>,
    #[serde(default)]
    operation: Option<OperationId>,
    capability_token: fcp_core::CapabilityToken,
    #[serde(default)]
    input: Option<Value>,
    #[serde(default)]
    deadline_ms: Option<u64>,
    #[serde(default)]
    idempotency_key: Option<String>,
    #[serde(default)]
    approval_tokens: Vec<ApprovalToken>,
}

fn mcp_sampling_event_result(response: &InvokeResponse) -> Option<&Value> {
    let result = response.result.as_ref()?;
    (result.get("event").and_then(Value::as_str) == Some(MCP_SAMPLING_EVENT)).then_some(result)
}

fn mcp_sampling_host_dispatch(
    source: &InvokeRequest,
) -> HostResult<Option<McpSamplingHostDispatch>> {
    let raw = source
        .input
        .get(MCP_SAMPLING_HOST_DISPATCH_FIELD)
        .or_else(|| source.input.get(MCP_SAMPLING_HOST_DISPATCH_ALT_FIELD));
    let Some(raw) = raw else {
        return Ok(None);
    };
    serde_json::from_value(raw.clone())
        .map(Some)
        .map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid MCP sampling host dispatch configuration: {error}"
            ))
        })
}

fn mcp_sampling_configured_llm_connector(event: &Value) -> Option<&str> {
    event
        .get("llm_connector")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn mcp_sampling_default_llm_operation(connector_id: &ConnectorId) -> HostResult<OperationId> {
    format!("{}.chat.completions", connector_id.as_str())
        .parse()
        .map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid default MCP sampling LLM operation for connector `{}`: {error}",
                connector_id.as_str()
            ))
        })
}

fn mcp_sampling_event_to_chat_input(event: &Value) -> HostResult<Value> {
    let params = event
        .pointer("/request/params")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            HostError::InvalidFilter(
                "MCP sampling event is missing request.params for host dispatch".to_string(),
            )
        })?;
    let messages = params.get("messages").cloned().ok_or_else(|| {
        HostError::InvalidFilter(
            "MCP sampling event is missing request.params.messages for host dispatch".to_string(),
        )
    })?;

    let mut input = serde_json::Map::new();
    input.insert("messages".to_string(), messages);
    if let Some(max_tokens) = params.get("maxTokens").and_then(Value::as_u64) {
        input.insert("max_tokens".to_string(), json!(max_tokens));
    }
    if let Some(model) = event
        .pointer("/limits/model_override")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        input.insert("model".to_string(), json!(model));
    }
    if let Some(stop) = params.get("stopSequences").cloned() {
        input.insert("stop".to_string(), stop);
    }
    Ok(Value::Object(input))
}

fn mcp_sampling_downstream_request(
    source: &InvokeRequest,
    event: &Value,
    dispatch: McpSamplingHostDispatch,
) -> HostResult<InvokeRequest> {
    let configured_connector = mcp_sampling_configured_llm_connector(event);
    let connector_id = match (dispatch.connector_id, configured_connector) {
        (Some(connector_id), Some(configured)) if connector_id.as_str() != configured => {
            return Err(HostError::InvalidFilter(format!(
                "MCP sampling host dispatch connector `{}` does not match configured llm_connector `{configured}`",
                connector_id.as_str()
            )));
        }
        (Some(connector_id), _) => connector_id,
        (None, Some(configured)) => configured.parse().map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid MCP sampling llm_connector `{configured}`: {error}"
            ))
        })?,
        (None, None) => {
            return Err(HostError::InvalidFilter(
                "MCP sampling host dispatch requires connector_id or configured llm_connector"
                    .to_string(),
            ));
        }
    };

    let operation = match dispatch.operation {
        Some(operation) => operation,
        None => mcp_sampling_default_llm_operation(&connector_id)?,
    };
    let input = match dispatch.input {
        Some(input) => input,
        None => mcp_sampling_event_to_chat_input(event)?,
    };

    let mut context = source.context.clone().unwrap_or_default();
    context
        .request_tags
        .insert("fcp.host.dispatch".to_string(), "mcp_sampling".to_string());
    context.request_tags.insert(
        "fcp.host.parent_request_id".to_string(),
        source.id.to_string(),
    );

    Ok(InvokeRequest {
        r#type: "invoke".to_string(),
        id: RequestId::random(),
        connector_id,
        operation,
        zone_id: source.zone_id.clone(),
        input,
        capability_token: dispatch.capability_token,
        holder_proof: None,
        context: Some(context),
        idempotency_key: dispatch.idempotency_key,
        lease_seq: None,
        deadline_ms: dispatch.deadline_ms.or(source.deadline_ms),
        correlation_id: source.correlation_id.clone(),
        provenance: source.provenance.clone(),
        approval_tokens: dispatch.approval_tokens,
    })
}

fn mcp_sampling_downstream_error(id: RequestId, response: InvokeResponse) -> InvokeResponse {
    let error = response
        .error
        .unwrap_or_else(|| fcp_core::FcpError::External {
            service: "mcp_sampling_host_dispatch".to_string(),
            message: "downstream LLM connector returned an error without details".to_string(),
            status_code: None,
            retryable: false,
            retry_after: None,
        });
    InvokeResponse::error(id, error)
}

fn mcp_sampling_host_response(
    parent_id: RequestId,
    mut bridge_response: InvokeResponse,
    downstream_request: &InvokeRequest,
    downstream_response: InvokeResponse,
) -> InvokeResponse {
    if !matches!(downstream_response.status, InvokeStatus::Ok) {
        return mcp_sampling_downstream_error(parent_id, downstream_response);
    }
    let InvokeResponse {
        id: downstream_response_id,
        status: downstream_status,
        result: downstream_result,
        receipt_id,
        audit_event_id,
        decision_receipt_id,
        resource_uris,
        next_cursor,
        usage_metrics,
        response_metadata,
        ..
    } = downstream_response;

    let mut result = bridge_response
        .result
        .take()
        .and_then(|value| value.as_object().cloned())
        .unwrap_or_default();
    result.insert("dispatch".to_string(), json!("host_orchestrated"));
    result.insert("host_orchestrated".to_string(), json!(true));
    result.insert(
        "host_dispatch".to_string(),
        json!({
            "connector_id": downstream_request.connector_id.as_str(),
            "operation": downstream_request.operation.as_str(),
            "request_id": downstream_response_id,
            "status": downstream_status,
            "result": downstream_result,
            "receipt_id": receipt_id,
            "audit_event_id": audit_event_id,
            "decision_receipt_id": decision_receipt_id,
            "redaction": {
                "prompt_logged": false,
                "response_logged": false,
                "metadata_logged": false
            }
        }),
    );
    bridge_response.result = Some(Value::Object(result));
    bridge_response.usage_metrics = usage_metrics;
    bridge_response.resource_uris = resource_uris;
    bridge_response.next_cursor = next_cursor;
    bridge_response.response_metadata = response_metadata;
    bridge_response
}

async fn maybe_orchestrate_mcp_sampling(
    state: &Arc<AppState>,
    asserted_principal: Option<&str>,
    source: &InvokeRequest,
    response: InvokeResponse,
) -> HostResult<InvokeResponse> {
    if source.operation.as_str() != MCP_SAMPLING_HANDLE_OPERATION {
        return Ok(response);
    }
    let Some(event) = mcp_sampling_event_result(&response) else {
        return Ok(response);
    };
    let Some(dispatch) = mcp_sampling_host_dispatch(source)? else {
        return Ok(response);
    };
    let downstream_request = mcp_sampling_downstream_request(source, event, dispatch)?;
    let verified = evaluate_verified_live_preflight(state, &downstream_request, asserted_principal)
        .await
        .map_err(|error| {
            HostError::PreflightFailed(format!(
                "MCP sampling host dispatch denied for connector `{}` operation `{}`: {error}",
                downstream_request.connector_id, downstream_request.operation
            ))
        })?;

    tracing::info!(
        event = "mcp_sampling_host_dispatch",
        source_connector_id = %source.connector_id,
        source_operation = %source.operation,
        target_connector_id = %downstream_request.connector_id,
        target_operation = %downstream_request.operation,
        source_request_id = %source.id,
        downstream_request_id = %downstream_request.id,
        prompt_logged = false,
        response_logged = false,
        "dispatching MCP sampling request through configured LLM connector"
    );
    let downstream_response = state
        .registry
        .invoke_with_execution_plan(
            state,
            downstream_request.clone(),
            verified.per_invocation_plan,
        )
        .await?;
    Ok(mcp_sampling_host_response(
        source.id.clone(),
        response,
        &downstream_request,
        downstream_response,
    ))
}

async fn cancel_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<CancellationRequest>,
) -> Result<Json<CancellationResponse>, (StatusCode, String)> {
    let operation_id = request.operation_id.clone();
    // br-jdaro: extract the asserted principal from the same header
    // invoke_handler accepts (`X-Principal`). When the tracked operation
    // has an owner, CancellationController::cancel enforces match and
    // returns HostError::PreflightFailed (→ 403) on mismatch. Operations
    // tracked without an owner stay permissive only for legacy/manual
    // controller callers that intentionally opted into ownerless tracking.
    let asserted_principal = extract_principal_header(&headers);
    let started_at = Instant::now();
    tracing::debug!(
        event = "cancel_request",
        operation_id = %operation_id,
        asserted_principal = asserted_principal.as_deref(),
        reason = %request.reason.label(),
        cleanup = ?request.cleanup,
        return_partial = request.return_partial,
        "processing cancellation request"
    );

    let response = state
        .cancellation
        .cancel(&request, asserted_principal.as_deref(), Utc::now())
        .map_err(map_host_error)?;

    tracing::info!(
        event = "cancel_response",
        operation_id = %operation_id,
        outcome = ?response.outcome,
        duration_ms = started_at.elapsed().as_millis() as u64,
        "cancellation request complete"
    );
    Ok(Json(response))
}

async fn cancel_self_handler(
    State(state): State<Arc<AppState>>,
    Json(request): Json<CancellationRequest>,
) -> Result<Json<CancellationResponse>, (StatusCode, String)> {
    let operation_id = request.operation_id.clone();
    let verified_principal = verified_cancellation_principal(state.as_ref(), &request)
        .await
        .map_err(map_host_error)?;
    let started_at = Instant::now();
    tracing::debug!(
        event = "cancel_self_request",
        operation_id = %operation_id,
        principal = %verified_principal,
        reason = %request.reason.label(),
        cleanup = ?request.cleanup,
        return_partial = request.return_partial,
        "processing owner-scoped cancellation request"
    );

    let response = state
        .cancellation
        .cancel(&request, Some(verified_principal.as_str()), Utc::now())
        .map_err(map_host_error)?;

    tracing::info!(
        event = "cancel_self_response",
        operation_id = %operation_id,
        principal = %verified_principal,
        outcome = ?response.outcome,
        duration_ms = started_at.elapsed().as_millis() as u64,
        "owner-scoped cancellation request complete"
    );
    Ok(Json(response))
}

#[derive(Debug, Clone)]
struct BlueBubblesIngressConfig {
    connector_id: ConnectorId,
    zone_id: ZoneId,
    capability_token: fcp_core::CapabilityToken,
    max_body_bytes: usize,
    timeout_ms: u64,
    concurrency_limit: u64,
    rate_limit_max: u64,
    rate_limit_window_ms: u64,
    load_shed: bool,
}

#[allow(clippy::too_many_lines)]
async fn bluebubbles_webhook_ingress_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    uri: Uri,
    body: Bytes,
) -> Result<(StatusCode, Json<Value>), (StatusCode, String)> {
    let config = resolve_bluebubbles_ingress_config().map_err(map_host_error)?;
    if body.len() > config.max_body_bytes {
        return Ok(bluebubbles_ingress_admission_response(
            StatusCode::PAYLOAD_TOO_LARGE,
            "payload_too_large",
            "BlueBubbles webhook body exceeds configured host ingress maximum",
            body.len(),
        ));
    }

    let body_value = match serde_json::from_slice::<Value>(&body) {
        Ok(value) => value,
        Err(error) => {
            return Ok(bluebubbles_ingress_admission_response(
                StatusCode::BAD_REQUEST,
                "malformed_payload",
                &format!("BlueBubbles webhook body must be valid JSON: {error}"),
                body.len(),
            ));
        }
    };

    let request =
        bluebubbles_ingress_invoke_request(&config, &headers, &uri, body_value, body.len())
            .map_err(map_host_error)?;

    // External webhook headers are intentionally not forwarded to invoke_handler.
    // The public provider authenticates with BlueBubbles callback auth; FCP
    // authorization comes from the host-provisioned capability token above.
    let Json(response) = invoke_handler(State(state), HeaderMap::new(), Json(request)).await?;
    let fallback_status = if matches!(response.status, InvokeStatus::Ok) {
        StatusCode::OK
    } else {
        StatusCode::INTERNAL_SERVER_ERROR
    };
    let output = response.result.unwrap_or_else(|| {
        json!({
            "accepted": false,
            "status_code": fallback_status.as_u16(),
            "reason_code": "invoke_error",
            "reason": response
                .error
                .map_or_else(|| "BlueBubbles ingress invoke failed".to_string(), |error| error.to_string()),
            "body_bytes": body.len(),
            "tainted": true,
            "clean_shutdown": true,
        })
    });
    let status = bluebubbles_ingress_status_from_output(&output, fallback_status);
    Ok((status, Json(output)))
}

fn resolve_bluebubbles_ingress_config() -> HostResult<BlueBubblesIngressConfig> {
    let connector_id = read_optional_trimmed_env_string(BLUEBUBBLES_INGRESS_CONNECTOR_ID_ENV)?
        .unwrap_or_else(|| DEFAULT_BLUEBUBBLES_INGRESS_CONNECTOR_ID.to_string())
        .parse()
        .map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid {BLUEBUBBLES_INGRESS_CONNECTOR_ID_ENV}: {error}"
            ))
        })?;
    let zone_id = read_optional_trimmed_env_string(BLUEBUBBLES_INGRESS_ZONE_ID_ENV)?
        .unwrap_or_else(|| DEFAULT_BLUEBUBBLES_INGRESS_ZONE_ID.to_string())
        .parse()
        .map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid {BLUEBUBBLES_INGRESS_ZONE_ID_ENV}: {error}"
            ))
        })?;
    let token_b64 = read_bluebubbles_ingress_token_b64()?;
    let capability_token =
        capability_token_from_cbor_b64(&token_b64, BLUEBUBBLES_INGRESS_TOKEN_B64_ENV)?;
    Ok(BlueBubblesIngressConfig {
        connector_id,
        zone_id,
        capability_token,
        max_body_bytes: read_env_usize(BLUEBUBBLES_INGRESS_MAX_BODY_BYTES_ENV)?
            .unwrap_or(DEFAULT_BLUEBUBBLES_INGRESS_MAX_BODY_BYTES),
        timeout_ms: read_env_u64(BLUEBUBBLES_INGRESS_TIMEOUT_MS_ENV)?
            .unwrap_or(DEFAULT_BLUEBUBBLES_INGRESS_TIMEOUT_MS),
        concurrency_limit: read_env_u64(BLUEBUBBLES_INGRESS_CONCURRENCY_LIMIT_ENV)?
            .unwrap_or(DEFAULT_BLUEBUBBLES_INGRESS_CONCURRENCY_LIMIT),
        rate_limit_max: read_env_u64(BLUEBUBBLES_INGRESS_RATE_LIMIT_MAX_ENV)?
            .unwrap_or(DEFAULT_BLUEBUBBLES_INGRESS_RATE_LIMIT_MAX),
        rate_limit_window_ms: read_env_u64(BLUEBUBBLES_INGRESS_RATE_LIMIT_WINDOW_MS_ENV)?
            .unwrap_or(DEFAULT_BLUEBUBBLES_INGRESS_RATE_LIMIT_WINDOW_MS),
        load_shed: read_env_bool(BLUEBUBBLES_INGRESS_LOAD_SHED_ENV)?.unwrap_or(true),
    })
}

fn read_bluebubbles_ingress_token_b64() -> HostResult<String> {
    if let Some(path) = read_optional_trimmed_env_string(BLUEBUBBLES_INGRESS_TOKEN_FILE_ENV)? {
        let token = std::fs::read_to_string(&path).map_err(|error| {
            HostError::Unavailable(format!(
                "failed to read {BLUEBUBBLES_INGRESS_TOKEN_FILE_ENV} '{}': {error}",
                path
            ))
        })?;
        let token = token.trim();
        if token.is_empty() {
            return Err(HostError::Unavailable(format!(
                "{BLUEBUBBLES_INGRESS_TOKEN_FILE_ENV} '{}' is empty",
                path
            )));
        }
        return Ok(token.to_string());
    }

    read_optional_trimmed_env_string(BLUEBUBBLES_INGRESS_TOKEN_B64_ENV)?.ok_or_else(|| {
        HostError::Unavailable(format!(
            "BlueBubbles host ingress requires {BLUEBUBBLES_INGRESS_TOKEN_FILE_ENV} or {BLUEBUBBLES_INGRESS_TOKEN_B64_ENV}"
        ))
    })
}

fn capability_token_from_cbor_b64(
    token_cbor_b64: &str,
    source_name: &str,
) -> HostResult<fcp_core::CapabilityToken> {
    let token_bytes = base64::engine::general_purpose::STANDARD
        .decode(token_cbor_b64.trim())
        .map_err(|error| {
            HostError::InvalidFilter(format!("invalid base64 in {source_name}: {error}"))
        })?;
    let raw = fcp_crypto::cose::CoseToken::from_cbor(&token_bytes).map_err(|error| {
        HostError::InvalidFilter(format!("invalid COSE token in {source_name}: {error}"))
    })?;
    Ok(fcp_core::CapabilityToken::from_raw(raw))
}

fn bluebubbles_ingress_invoke_request(
    config: &BlueBubblesIngressConfig,
    headers: &HeaderMap,
    uri: &Uri,
    body: Value,
    body_size_bytes: usize,
) -> HostResult<InvokeRequest> {
    let input = bluebubbles_ingress_input(config, headers, uri, body, body_size_bytes)?;
    Ok(InvokeRequest {
        r#type: "invoke".to_string(),
        id: RequestId::random(),
        connector_id: config.connector_id.clone(),
        operation: OperationId::from_static(BLUEBUBBLES_INGRESS_OPERATION),
        zone_id: config.zone_id.clone(),
        input,
        capability_token: config.capability_token.clone(),
        holder_proof: None,
        context: None,
        idempotency_key: Some(format!("bluebubbles-webhook-{}", RequestId::random())),
        lease_seq: None,
        deadline_ms: Some(config.timeout_ms),
        correlation_id: Some(CorrelationId::new()),
        provenance: None,
        approval_tokens: Vec::new(),
    })
}

fn bluebubbles_ingress_input(
    config: &BlueBubblesIngressConfig,
    headers: &HeaderMap,
    uri: &Uri,
    body: Value,
    body_size_bytes: usize,
) -> HostResult<Value> {
    Ok(json!({
        "method": "POST",
        "url": bluebubbles_ingress_observed_url(headers, uri)?,
        "headers": bluebubbles_ingress_forwarded_headers(headers),
        "body": body,
        "body_size_bytes": body_size_bytes,
        "max_body_bytes": config.max_body_bytes,
        "timeout_ms": config.timeout_ms,
        "concurrency_limit": config.concurrency_limit,
        "rate_limit_max": config.rate_limit_max,
        "rate_limit_window_ms": config.rate_limit_window_ms,
        "load_shed": config.load_shed,
        "source": "fcp_host_native_bluebubbles_ingress",
        "cancelled": false,
        "deadline_exceeded": false,
    }))
}

fn bluebubbles_ingress_observed_url(headers: &HeaderMap, uri: &Uri) -> HostResult<String> {
    let scheme = header_value(headers, "x-forwarded-proto").unwrap_or("http");
    let scheme = first_forwarded_value(scheme);
    if !matches!(scheme, "http" | "https") {
        return Err(HostError::InvalidFilter(format!(
            "invalid x-forwarded-proto for BlueBubbles webhook ingress: {scheme}"
        )));
    }

    let host = header_value(headers, "x-forwarded-host")
        .or_else(|| header_value(headers, "host"))
        .unwrap_or("localhost");
    let host = first_forwarded_value(host);
    if host.is_empty() || host.contains('/') {
        return Err(HostError::InvalidFilter(format!(
            "invalid host header for BlueBubbles webhook ingress: {host}"
        )));
    }

    let path_and_query = uri.path_and_query().map_or_else(
        || BLUEBUBBLES_INGRESS_ROUTE.to_string(),
        ToString::to_string,
    );
    Ok(format!("{scheme}://{host}{path_and_query}"))
}

fn bluebubbles_ingress_forwarded_headers(headers: &HeaderMap) -> Value {
    let mut forwarded = serde_json::Map::new();
    for name in ["x-bluebubbles-auth", "x-bluebubbles-event"] {
        if let Some(value) = header_value(headers, name) {
            forwarded.insert(name.to_string(), Value::String(value.to_string()));
        }
    }
    Value::Object(forwarded)
}

fn header_value<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    headers
        .get(name)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn first_forwarded_value(value: &str) -> &str {
    value.split(',').next().unwrap_or(value).trim()
}

fn bluebubbles_ingress_status_from_output(output: &Value, fallback: StatusCode) -> StatusCode {
    output
        .get("status_code")
        .and_then(Value::as_u64)
        .and_then(|status| u16::try_from(status).ok())
        .filter(|status| (100..=599).contains(status))
        .and_then(|status| StatusCode::from_u16(status).ok())
        .unwrap_or(fallback)
}

fn bluebubbles_ingress_admission_response(
    status: StatusCode,
    reason_code: &str,
    reason: &str,
    body_bytes: usize,
) -> (StatusCode, Json<Value>) {
    (
        status,
        Json(json!({
            "accepted": false,
            "status_code": status.as_u16(),
            "reason_code": reason_code,
            "reason": reason,
            "ingest": null,
            "body_bytes": body_bytes,
            "tainted": true,
            "clean_shutdown": true,
        })),
    )
}

#[derive(Debug, Clone)]
struct TelegramWebhookIngressConfig {
    connector_id: ConnectorId,
    zone_id: ZoneId,
    capability_token: fcp_core::CapabilityToken,
    max_body_bytes: usize,
    timeout_ms: u64,
}

async fn telegram_webhook_ingress_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    body: Bytes,
) -> Result<(StatusCode, Json<Value>), (StatusCode, String)> {
    let config = resolve_telegram_webhook_ingress_config().map_err(map_host_error)?;
    telegram_webhook_ingress_handler_with_config(state, headers, body, config).await
}

async fn telegram_webhook_ingress_handler_with_config(
    state: Arc<AppState>,
    headers: HeaderMap,
    body: Bytes,
    config: TelegramWebhookIngressConfig,
) -> Result<(StatusCode, Json<Value>), (StatusCode, String)> {
    if body.len() > config.max_body_bytes {
        return Ok(telegram_webhook_ingress_admission_response(
            StatusCode::PAYLOAD_TOO_LARGE,
            "payload_too_large",
            "Telegram webhook body exceeds configured host ingress maximum",
            body.len(),
        ));
    }

    let payload = match std::str::from_utf8(body.as_ref()) {
        Ok(payload) => payload,
        Err(error) => {
            return Ok(telegram_webhook_ingress_admission_response(
                StatusCode::BAD_REQUEST,
                "malformed_payload",
                &format!("Telegram webhook body must be UTF-8 JSON: {error}"),
                body.len(),
            ));
        }
    };
    if let Err(error) = serde_json::from_str::<Value>(payload) {
        return Ok(telegram_webhook_ingress_admission_response(
            StatusCode::BAD_REQUEST,
            "malformed_payload",
            &format!("Telegram webhook body must be valid JSON: {error}"),
            body.len(),
        ));
    }

    let delivery_id = telegram_webhook_ingress_delivery_id(&headers);
    let received_at = Utc::now().timestamp();
    let request = telegram_webhook_ingress_invoke_request(
        &config,
        &headers,
        payload.to_string(),
        delivery_id,
        received_at,
    )
    .map_err(map_host_error)?;

    // External Telegram headers are not forwarded wholesale. The connector sees
    // only the raw Update payload plus the optional Telegram secret-token header
    // it knows how to verify; FCP authorization stays host-provisioned.
    let Json(response) = invoke_handler(State(state), HeaderMap::new(), Json(request)).await?;
    let fallback_status = if matches!(response.status, InvokeStatus::Ok) {
        StatusCode::OK
    } else {
        StatusCode::INTERNAL_SERVER_ERROR
    };
    let output = response.result.unwrap_or_else(|| {
        json!({
            "accepted": false,
            "event_emitted": false,
            "status_code": fallback_status.as_u16(),
            "reason_code": "invoke_error",
            "reason": response
                .error
                .map_or_else(|| "Telegram webhook ingress invoke failed".to_string(), |error| error.to_string()),
            "body_bytes": body.len(),
        })
    });
    let status = telegram_webhook_ingress_status_from_output(&output, fallback_status);
    Ok((status, Json(output)))
}

fn resolve_telegram_webhook_ingress_config() -> HostResult<TelegramWebhookIngressConfig> {
    let connector_id = read_optional_trimmed_env_string(TELEGRAM_WEBHOOK_INGRESS_CONNECTOR_ID_ENV)?
        .unwrap_or_else(|| DEFAULT_TELEGRAM_WEBHOOK_INGRESS_CONNECTOR_ID.to_string())
        .parse()
        .map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid {TELEGRAM_WEBHOOK_INGRESS_CONNECTOR_ID_ENV}: {error}"
            ))
        })?;
    let zone_id = read_optional_trimmed_env_string(TELEGRAM_WEBHOOK_INGRESS_ZONE_ID_ENV)?
        .unwrap_or_else(|| DEFAULT_TELEGRAM_WEBHOOK_INGRESS_ZONE_ID.to_string())
        .parse()
        .map_err(|error| {
            HostError::InvalidFilter(format!(
                "invalid {TELEGRAM_WEBHOOK_INGRESS_ZONE_ID_ENV}: {error}"
            ))
        })?;
    let token_b64 = read_telegram_webhook_ingress_token_b64()?;
    let capability_token =
        capability_token_from_cbor_b64(&token_b64, TELEGRAM_WEBHOOK_INGRESS_TOKEN_B64_ENV)?;
    Ok(TelegramWebhookIngressConfig {
        connector_id,
        zone_id,
        capability_token,
        max_body_bytes: read_env_usize(TELEGRAM_WEBHOOK_INGRESS_MAX_BODY_BYTES_ENV)?
            .unwrap_or(DEFAULT_TELEGRAM_WEBHOOK_INGRESS_MAX_BODY_BYTES),
        timeout_ms: read_env_u64(TELEGRAM_WEBHOOK_INGRESS_TIMEOUT_MS_ENV)?
            .unwrap_or(DEFAULT_TELEGRAM_WEBHOOK_INGRESS_TIMEOUT_MS),
    })
}

fn read_telegram_webhook_ingress_token_b64() -> HostResult<String> {
    if let Some(path) = read_optional_trimmed_env_string(TELEGRAM_WEBHOOK_INGRESS_TOKEN_FILE_ENV)? {
        let token = std::fs::read_to_string(&path).map_err(|error| {
            HostError::Unavailable(format!(
                "failed to read {TELEGRAM_WEBHOOK_INGRESS_TOKEN_FILE_ENV} '{}': {error}",
                path
            ))
        })?;
        let token = token.trim();
        if token.is_empty() {
            return Err(HostError::Unavailable(format!(
                "{TELEGRAM_WEBHOOK_INGRESS_TOKEN_FILE_ENV} '{}' is empty",
                path
            )));
        }
        return Ok(token.to_string());
    }

    read_optional_trimmed_env_string(TELEGRAM_WEBHOOK_INGRESS_TOKEN_B64_ENV)?.ok_or_else(|| {
        HostError::Unavailable(format!(
            "Telegram webhook host ingress requires {TELEGRAM_WEBHOOK_INGRESS_TOKEN_FILE_ENV} or {TELEGRAM_WEBHOOK_INGRESS_TOKEN_B64_ENV}"
        ))
    })
}

fn telegram_webhook_ingress_invoke_request(
    config: &TelegramWebhookIngressConfig,
    headers: &HeaderMap,
    payload: String,
    delivery_id: String,
    received_at: i64,
) -> HostResult<InvokeRequest> {
    let input = telegram_webhook_ingress_input(headers, payload, &delivery_id, received_at);
    Ok(InvokeRequest {
        r#type: "invoke".to_string(),
        id: RequestId::random(),
        connector_id: config.connector_id.clone(),
        operation: OperationId::from_static(TELEGRAM_WEBHOOK_INGRESS_OPERATION),
        zone_id: config.zone_id.clone(),
        input,
        capability_token: config.capability_token.clone(),
        holder_proof: None,
        context: None,
        idempotency_key: Some(delivery_id),
        lease_seq: None,
        deadline_ms: Some(config.timeout_ms),
        correlation_id: Some(CorrelationId::new()),
        provenance: None,
        approval_tokens: Vec::new(),
    })
}

fn telegram_webhook_ingress_input(
    headers: &HeaderMap,
    payload: String,
    delivery_id: &str,
    received_at: i64,
) -> Value {
    let mut input = serde_json::Map::new();
    input.insert("payload".to_string(), Value::String(payload));
    input.insert(
        "delivery_id".to_string(),
        Value::String(delivery_id.to_string()),
    );
    input.insert(
        "received_at".to_string(),
        Value::Number(serde_json::Number::from(received_at)),
    );
    if let Some(secret_token) = header_value(headers, TELEGRAM_WEBHOOK_SECRET_HEADER) {
        input.insert(
            "secret_token".to_string(),
            Value::String(secret_token.to_string()),
        );
    }
    Value::Object(input)
}

fn telegram_webhook_ingress_delivery_id(headers: &HeaderMap) -> String {
    header_value(headers, TELEGRAM_WEBHOOK_DELIVERY_ID_HEADER)
        .map(str::to_string)
        .unwrap_or_else(|| format!("telegram-webhook-{}", RequestId::random()))
}

fn telegram_webhook_ingress_status_from_output(output: &Value, fallback: StatusCode) -> StatusCode {
    output
        .get("status_code")
        .and_then(Value::as_u64)
        .and_then(|status| u16::try_from(status).ok())
        .filter(|status| (100..=599).contains(status))
        .and_then(|status| StatusCode::from_u16(status).ok())
        .unwrap_or(fallback)
}

fn telegram_webhook_ingress_admission_response(
    status: StatusCode,
    reason_code: &str,
    reason: &str,
    body_bytes: usize,
) -> (StatusCode, Json<Value>) {
    (
        status,
        Json(json!({
            "accepted": false,
            "event_emitted": false,
            "status_code": status.as_u16(),
            "reason_code": reason_code,
            "reason": reason,
            "body_bytes": body_bytes,
        })),
    )
}

#[derive(Debug)]
struct AuthorizedHostEgress {
    connector_id: ConnectorId,
    operation: OperationId,
    zone_id: ZoneId,
    request_id: String,
    correlation_id: Option<String>,
    idempotency: IdempotencyClass,
    constraints: NetworkConstraints,
    credential_allow: Vec<String>,
}

impl AuthorizedHostEgress {
    fn decision_context(&self) -> fcp_host::RuntimeEgressDecisionContext<'_> {
        fcp_host::RuntimeEgressDecisionContext {
            connector_id: self.connector_id.as_str(),
            operation: self.operation.as_str(),
            zone_id: self.zone_id.as_str(),
            request_id: &self.request_id,
            correlation_id: self.correlation_id.as_deref(),
            execution_mode: RuntimeNetworkEnforcement::HostEgressProxy,
            constraint_source: "managed_connector_config.operation_network_constraints",
            credential_allow: &self.credential_allow,
        }
    }

    fn metadata(
        &self,
        decision: &fcp_sandbox::EgressDecision,
        elapsed_ms: u128,
    ) -> HostEgressDecisionMetadata {
        HostEgressDecisionMetadata {
            connector_id: self.connector_id.to_string(),
            operation_id: self.operation.to_string(),
            zone_id: self.zone_id.to_string(),
            request_id: self.request_id.clone(),
            correlation_id: self.correlation_id.clone(),
            execution_mode: RuntimeNetworkEnforcement::HostEgressProxy
                .as_str()
                .to_string(),
            constraint_source: "managed_connector_config.operation_network_constraints".to_string(),
            decision: "allow".to_string(),
            resolved_host: decision.canonical_host.clone(),
            resolved_port: decision.port,
            credential_injected: decision.credential_injected,
            elapsed_ms,
        }
    }
}

fn parse_host_egress_context(
    context: &HostEgressContext,
) -> HostResult<(ConnectorId, OperationId, ZoneId)> {
    let connector_id = context.connector_id.parse().map_err(|err| {
        HostError::InvalidFilter(format!(
            "invalid host-egress connector_id `{}`: {err}",
            context.connector_id
        ))
    })?;
    let operation = context.operation_id.parse().map_err(|err| {
        HostError::InvalidFilter(format!(
            "invalid host-egress operation_id `{}`: {err}",
            context.operation_id
        ))
    })?;
    let zone_id = context.zone_id.parse().map_err(|err| {
        HostError::InvalidFilter(format!(
            "invalid host-egress zone_id `{}`: {err}",
            context.zone_id
        ))
    })?;
    Ok((connector_id, operation, zone_id))
}

async fn authorize_host_egress_context(
    state: &AppState,
    context: &HostEgressContext,
    resource_uri: &str,
) -> HostResult<AuthorizedHostEgress> {
    if resource_uri.is_empty()
        || resource_uri != resource_uri.trim()
        || resource_uri.chars().any(char::is_control)
    {
        return Err(HostError::InvalidFilter(
            "invalid host-egress canonical resource_uri".to_string(),
        ));
    }
    let (connector_id, operation, zone_id) = parse_host_egress_context(context)?;
    let snapshot = state
        .registry
        .runtime_network_policy_snapshot(&connector_id, &operation)
        .await
        .ok_or_else(|| HostError::ConnectorNotFound(connector_id.to_string()))?;
    if snapshot.enforcement != RuntimeNetworkEnforcement::HostEgressProxy {
        return Err(HostError::PreflightFailed(format!(
            "host-egress proxy rejected connector `{connector_id}` operation `{operation}`: \
             runtime_network_enforcement is `{}`, not `host_egress_proxy`",
            snapshot.enforcement.as_str()
        )));
    }
    let managed_constraints = snapshot.operation_constraints.ok_or_else(|| {
        HostError::PreflightFailed(format!(
            "host-egress proxy for connector `{connector_id}` operation `{operation}` requires \
             operation_network_constraints, but none were configured for that operation"
        ))
    })?;
    let constraints = managed_constraints
        .resolve(snapshot.connector_config.as_ref())
        .map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress proxy rejected connector `{connector_id}` operation `{operation}`: {err}"
            ))
        })?;

    let capability_token = capability_token_from_cbor_b64(
        &context.capability_token_cbor_b64,
        "host-egress capability_token_cbor_b64",
    )?;
    let introspection = state.discovery.introspect(&connector_id).await?;
    let tool = introspection
        .tools
        .iter()
        .find(|tool| tool.name == operation.as_str())
        .ok_or_else(|| {
            HostError::InvalidFilter(format!(
                "connector `{connector_id}` does not expose operation `{operation}`"
            ))
        })?;
    let capability_key = state.capability_verifying_key.as_ref().ok_or_else(|| {
        HostError::PreflightFailed(
            "FCP_HOST_CAPABILITY_PUBLIC_KEY[_FILE] is not configured, so host-egress auth checks cannot be verified"
                .to_string(),
        )
    })?;
    let verifier =
        CapabilityVerifier::without_instance_binding(capability_key.to_bytes(), zone_id.clone());
    let verified_token = verifier
        .verify_unbound(
            capability_token.clone(),
            &tool.capability,
            &operation,
            &[resource_uri.to_string()],
        )
        .map_err(|error| {
            HostError::PreflightFailed(format!("host-egress capability token rejected: {error}"))
        })?;
    let verified_claims = verified_token.claims();
    verify_live_revocation_cascade(state, &capability_token, verified_claims)?;
    if let Some(expected_holder) = verified_claims.get_holder_node() {
        return Err(HostError::PreflightFailed(format!(
            "host-egress capability token is holder-bound to `{expected_holder}`, but host-egress requests do not carry holder_proof"
        )));
    }
    let persisted_verify = state
        .lifecycle
        .verify_capability_token(&CapabilityTokenVerifyRequest {
            token_cbor_b64: capability_token_b64(&capability_token)?,
            operation_id: Some(operation.to_string()),
            connector_id: Some(connector_id.to_string()),
        })
        .await
        .map_err(|error| {
            HostError::PreflightFailed(format!(
                "persisted host-egress capability verification failed: {error}"
            ))
        })?;
    if !persisted_verify.valid
        && let Some(reason) = authoritative_persisted_capability_rejection_reason(
            &persisted_verify,
            "persisted capability verification rejected the host-egress request",
        )
    {
        return Err(HostError::PreflightFailed(format!(
            "host-egress capability token rejected by host state: {reason}"
        )));
    }

    let capability_constraints = capability_constraints_from_claims(verified_claims)?;
    let credential_allow = capability_constraints
        .credential_allow
        .iter()
        .map(ToString::to_string)
        .collect::<Vec<_>>();

    Ok(AuthorizedHostEgress {
        connector_id,
        operation,
        zone_id,
        request_id: context.request_id.clone(),
        correlation_id: context.correlation_id.clone(),
        idempotency: tool.idempotency,
        constraints,
        credential_allow,
    })
}

fn capability_allows_credential(credential_id: &str, credential_allow: &[String]) -> bool {
    credential_allow
        .iter()
        .any(|allowed| allowed == credential_id)
}

async fn acquire_host_egress_credential_lease(
    state: &AppState,
    zone_id: &ZoneId,
    credential_id: Option<&str>,
    credential_allow: &[String],
) -> HostResult<Option<CredentialLease>> {
    let Some(raw_credential_id) = credential_id else {
        return Ok(None);
    };
    if !capability_allows_credential(raw_credential_id, credential_allow) {
        return Ok(None);
    }
    let credential_id = CredentialId::parse(raw_credential_id).map_err(|err| {
        HostError::PreflightFailed(format!(
            "invalid host-egress credential_id `{raw_credential_id}`: {err}"
        ))
    })?;
    let lease = state
        .credential_pools
        .lock()
        .await
        .acquire_specific_in_zone(zone_id, credential_id, Utc::now())
        .map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress credential lease denied for `{raw_credential_id}`: {err}"
            ))
        })?;
    Ok(Some(lease))
}

fn validate_n8n_specific_host_egress_credential(
    connector_id: &ConnectorId,
    resource_uri: &str,
    lease: &CredentialLease,
) -> HostResult<()> {
    let expected = match connector_id.as_str() {
        "fcp.n8n" => ("n8n", "X-N8N-API-KEY", None),
        "fcp.mcp-bridge"
            if matches!(
                resource_uri,
                "fwc-mcp-bridge://eec" | "fwc-mcp-bridge://hetzner"
            ) =>
        {
            ("mcp-bridge", "Authorization", Some("Bearer"))
        }
        _ => return Ok(()),
    };
    let profile = lease.payload.as_auth_profile().ok_or_else(|| {
        HostError::PreflightFailed(
            "n8n host-egress credential profile binding was denied".to_string(),
        )
    })?;
    let AuthMethodKind::ApiKey(method) = &profile.method else {
        return Err(HostError::PreflightFailed(
            "n8n host-egress credential profile binding was denied".to_string(),
        ));
    };
    if lease.pool_key.provider.as_str() != expected.0
        || profile.provider != expected.0
        || !method.header_name.eq_ignore_ascii_case(expected.1)
        || method.value_prefix.as_deref() != expected.2
    {
        return Err(HostError::PreflightFailed(
            "n8n host-egress credential profile binding was denied".to_string(),
        ));
    }
    Ok(())
}

async fn release_host_egress_credential_lease(state: &AppState, lease: CredentialLease) {
    if let Err(err) = state
        .credential_pools
        .lock()
        .await
        .release(&lease.pool_key, lease.token)
    {
        tracing::warn!(
            event = "host_egress_credential_release_error",
            provider = %lease.pool_key.provider,
            zone_id = %lease.pool_key.zone_id.as_str(),
            credential_id = %lease.credential_id,
            error = %err,
            "failed to release host-egress credential lease"
        );
    }
}

#[derive(Debug, Clone)]
struct HostCredentialInjector {
    lease: Option<CredentialLease>,
}

impl HostCredentialInjector {
    const fn new(lease: Option<CredentialLease>) -> Self {
        Self { lease }
    }

    fn lease_payload(&self, credential_id: &str) -> Result<&CredentialPayload, EgressError> {
        let lease = self.lease.as_ref().ok_or_else(|| {
            EgressError::CredentialError(format!("credential `{credential_id}` was not leased"))
        })?;
        if lease.credential_id.to_string() != credential_id {
            return Err(EgressError::CredentialError(format!(
                "credential `{credential_id}` does not match leased credential"
            )));
        }
        Ok(&lease.payload)
    }

    fn lease_raw_json_payload(&self, credential_id: &str) -> Result<&Value, EgressError> {
        self.lease_payload(credential_id)?
            .as_raw_json()
            .ok_or_else(|| {
                EgressError::CredentialError(format!(
                    "credential `{credential_id}` does not expose legacy host-egress JSON material"
                ))
            })
    }

    fn remove_connector_credential_headers(headers: &mut Vec<HttpHeader>) {
        headers.retain(|header| {
            !header.name.eq_ignore_ascii_case("x-fcp-credential-id")
                && !header.name.eq_ignore_ascii_case("authorization")
        });
    }

    fn auth_profile_host_allow(payload: &CredentialPayload) -> Result<Vec<String>, EgressError> {
        let Some(host_allow) = payload.auth_profile_host_allow() else {
            return Err(EgressError::CredentialError(
                "credential payload is not an auth profile".to_string(),
            ));
        };
        Ok(host_allow.to_vec())
    }

    fn auth_profile_http_headers(profile: &AuthProfile) -> Result<Vec<HttpHeader>, EgressError> {
        match &profile.method {
            AuthMethodKind::ApiKey(method) => {
                let value = method.value_prefix.as_deref().map_or_else(
                    || method.key.expose_secret().to_string(),
                    |prefix| format!("{prefix} {}", method.key.expose_secret()),
                );
                Ok(vec![HttpHeader {
                    name: method.header_name.clone(),
                    value,
                }])
            }
            AuthMethodKind::OAuthDeviceCode(method) => {
                if let Some(expires_at) = method.expires_at
                    && Utc::now() >= expires_at
                {
                    return Err(EgressError::CredentialError(
                        "oauth_device access token is expired".to_string(),
                    ));
                }
                let token = method.access_token.as_ref().ok_or_else(|| {
                    EgressError::CredentialError("oauth_device access token is missing".to_string())
                })?;
                Ok(vec![HttpHeader {
                    name: "Authorization".to_string(),
                    value: format!("Bearer {}", token.expose_secret()),
                }])
            }
            AuthMethodKind::OAuthAuthCode(method) => {
                if let Some(expires_at) = method.expires_at
                    && Utc::now() >= expires_at
                {
                    return Err(EgressError::CredentialError(
                        "oauth_auth_code access token is expired".to_string(),
                    ));
                }
                let token = method.access_token.as_ref().ok_or_else(|| {
                    EgressError::CredentialError(
                        "oauth_auth_code access token is missing".to_string(),
                    )
                })?;
                Ok(vec![HttpHeader {
                    name: "Authorization".to_string(),
                    value: format!("Bearer {}", token.expose_secret()),
                }])
            }
            other => Err(EgressError::CredentialError(format!(
                "auth profile method `{}` is not supported for host-egress HTTP injection",
                other.id()
            ))),
        }
    }

    fn auth_profile_is_refreshable(payload: &CredentialPayload) -> bool {
        payload.as_auth_profile().is_some_and(|profile| {
            matches!(
                profile.method,
                AuthMethodKind::OAuthDeviceCode(_) | AuthMethodKind::OAuthAuthCode(_)
            )
        })
    }

    fn raw_json_host_allow(payload: &Value) -> Vec<String> {
        [
            "/host_allow",
            "/allowed_hosts",
            "/http/host_allow",
            "/tcp/host_allow",
        ]
        .into_iter()
        .filter_map(|pointer| payload.pointer(pointer).and_then(Value::as_array))
        .flat_map(|values| values.iter().filter_map(Value::as_str))
        .map(ToOwned::to_owned)
        .collect()
    }

    fn raw_json_http_headers(payload: &Value) -> Result<Vec<HttpHeader>, EgressError> {
        let mut headers = Vec::new();
        if let Some(values) = payload.pointer("/http/headers").and_then(Value::as_array) {
            for value in values {
                let name = value.get("name").and_then(Value::as_str).ok_or_else(|| {
                    EgressError::CredentialError(
                        "HTTP credential header is missing `name`".to_string(),
                    )
                })?;
                let header_value = value.get("value").and_then(Value::as_str).ok_or_else(|| {
                    EgressError::CredentialError(
                        "HTTP credential header is missing `value`".to_string(),
                    )
                })?;
                headers.push(HttpHeader {
                    name: name.to_string(),
                    value: header_value.to_string(),
                });
            }
        }
        if let Some(token) = payload
            .pointer("/http/bearer_token")
            .or_else(|| payload.get("bearer_token"))
            .and_then(Value::as_str)
        {
            headers.push(HttpHeader {
                name: "Authorization".to_string(),
                value: format!("Bearer {token}"),
            });
        }
        if let (Some(name), Some(value)) = (
            payload
                .pointer("/http/api_key_header")
                .and_then(Value::as_str),
            payload.pointer("/http/api_key").and_then(Value::as_str),
        ) {
            headers.push(HttpHeader {
                name: name.to_string(),
                value: value.to_string(),
            });
        }
        if headers.is_empty() {
            return Err(EgressError::CredentialError(
                "HTTP credential payload did not contain injectable headers".to_string(),
            ));
        }
        Ok(headers)
    }

    fn raw_json_tcp_auth(payload: &Value) -> Result<Option<Vec<u8>>, EgressError> {
        let Some(raw) = payload
            .pointer("/tcp/auth")
            .or_else(|| payload.pointer("/tcp/auth_b64"))
            .or_else(|| payload.get("tcp_auth"))
            .and_then(Value::as_str)
        else {
            return Ok(None);
        };
        if let Some(encoded) = raw.strip_prefix("base64:") {
            return base64::engine::general_purpose::STANDARD
                .decode(encoded)
                .map(Some)
                .map_err(|err| {
                    EgressError::CredentialError(format!("invalid TCP credential base64: {err}"))
                });
        }
        Ok(Some(raw.as_bytes().to_vec()))
    }
}

impl CredentialInjector for HostCredentialInjector {
    fn is_authorized(
        &self,
        credential_id: &str,
        _operation_id: &str,
        credential_allow: &[String],
    ) -> Result<bool, EgressError> {
        Ok(self
            .lease
            .as_ref()
            .is_some_and(|lease| lease.credential_id.to_string() == credential_id)
            && capability_allows_credential(credential_id, credential_allow))
    }

    fn is_host_allowed(&self, credential_id: &str, host: &str) -> Result<bool, EgressError> {
        let payload = self.lease_payload(credential_id)?;
        let host_allow = if let Some(raw) = payload.as_raw_json() {
            Self::raw_json_host_allow(raw)
        } else {
            Self::auth_profile_host_allow(payload)?
        };
        Ok(!host_allow.is_empty() && host_matches_allow_list(host, &host_allow))
    }

    fn inject_http(
        &self,
        credential_id: &str,
        headers: &mut Vec<HttpHeader>,
    ) -> Result<(), EgressError> {
        let payload = self.lease_payload(credential_id)?;
        Self::remove_connector_credential_headers(headers);
        if let Some(raw) = payload.as_raw_json() {
            headers.extend(Self::raw_json_http_headers(raw)?);
        } else if let Some(profile) = payload.as_auth_profile() {
            headers.extend(Self::auth_profile_http_headers(profile)?);
        } else {
            return Err(EgressError::CredentialError(format!(
                "credential `{credential_id}` did not contain injectable host-egress material"
            )));
        }
        Ok(())
    }

    fn get_tcp_auth(&self, credential_id: &str) -> Result<Option<Vec<u8>>, EgressError> {
        let payload = self.lease_raw_json_payload(credential_id)?;
        Self::raw_json_tcp_auth(payload)
    }
}

async fn host_egress_http_handler(
    State(state): State<Arc<AppState>>,
    Json(request): Json<HostEgressHttpRequest>,
) -> Result<Json<HostEgressHttpResponse>, (StatusCode, String)> {
    let started_at = Instant::now();
    let authorized =
        authorize_host_egress_context(&state, &request.context, &request.context.resource_uri)
            .await
            .map_err(map_host_error)?;
    let lease = acquire_host_egress_credential_lease(
        &state,
        &authorized.zone_id,
        request.credential_id.as_deref(),
        &authorized.credential_allow,
    )
    .await
    .map_err(map_host_error)?;
    if let Some(lease_ref) = lease.as_ref()
        && let Err(error) = validate_n8n_specific_host_egress_credential(
            &authorized.connector_id,
            &request.context.resource_uri,
            lease_ref,
        )
    {
        if let Some(lease) = lease {
            release_host_egress_credential_lease(&state, lease).await;
        }
        return Err(map_host_error(error));
    }
    let result = authorize_and_perform_host_http_egress(
        &state,
        &authorized,
        request,
        lease.as_ref(),
        started_at,
    )
    .await;
    if let Some(lease) = lease {
        release_host_egress_credential_lease(&state, lease).await;
    }
    result.map(Json).map_err(map_host_error)
}

async fn authorize_and_perform_host_http_egress(
    state: &Arc<AppState>,
    authorized: &AuthorizedHostEgress,
    request: HostEgressHttpRequest,
    lease: Option<&CredentialLease>,
    started_at: Instant,
) -> HostResult<HostEgressHttpResponse> {
    let leased_injector = HostCredentialInjector::new(lease.cloned());
    let noop = NoOpCredentialInjector;
    let injector_ref: &dyn CredentialInjector = if request.credential_id.is_some() {
        &leased_injector
    } else {
        &noop
    };
    let response =
        perform_authorized_host_http_egress_once(authorized, &request, injector_ref, started_at)
            .await?;
    if response.status != 401 {
        return Ok(response);
    }

    if !host_egress_allows_unauthorized_refresh_replay(authorized.idempotency, &request) {
        return Ok(response);
    }

    let Some(lease) = lease else {
        return Ok(response);
    };
    let Some(credential_id) = request.credential_id.as_deref() else {
        return Ok(response);
    };
    if !HostCredentialInjector::auth_profile_is_refreshable(&lease.payload) {
        return Ok(response);
    }

    let refreshed_lease = refresh_host_egress_credential_after_unauthorized(
        state,
        authorized,
        credential_id,
        lease,
        started_at,
    )
    .await?;
    let refreshed_injector = HostCredentialInjector::new(Some(refreshed_lease));
    perform_authorized_host_http_egress_once(authorized, &request, &refreshed_injector, started_at)
        .await
}

fn host_egress_allows_unauthorized_refresh_replay(
    idempotency: IdempotencyClass,
    request: &HostEgressHttpRequest,
) -> bool {
    idempotency == IdempotencyClass::Strict
        && matches!(request.method.as_str(), "GET" | "HEAD" | "OPTIONS")
        && request.body.is_none()
}

fn host_egress_remaining_timeout(
    authorized: &AuthorizedHostEgress,
    started_at: Instant,
) -> Option<Duration> {
    Duration::from_millis(u64::from(authorized.constraints.total_timeout_ms))
        .checked_sub(started_at.elapsed())
        .filter(|remaining| !remaining.is_zero())
}

async fn perform_authorized_host_http_egress_once(
    authorized: &AuthorizedHostEgress,
    request: &HostEgressHttpRequest,
    injector: &dyn CredentialInjector,
    started_at: Instant,
) -> HostResult<HostEgressHttpResponse> {
    let mut guard_request = EgressHttpRequest {
        url: request.url.clone(),
        method: request.method.clone(),
        headers: request
            .headers
            .iter()
            .map(|header| HttpHeader {
                name: header.name.clone(),
                value: header.value.clone(),
            })
            .collect(),
        body: request.body.as_ref().map(|body| body.as_bytes().to_vec()),
        credential_id: request.credential_id.clone(),
    };
    let mut decision = fcp_host::authorize_runtime_http_egress(
        &authorized.decision_context(),
        &authorized.constraints,
        &mut guard_request,
        injector,
    )?;
    let remaining_timeout =
        host_egress_remaining_timeout(authorized, started_at).ok_or_else(|| {
            HostError::PreflightFailed(format!(
                "host-egress HTTP request to `{}` timed out after {}ms",
                decision.canonical_host, authorized.constraints.total_timeout_ms
            ))
        })?;
    let response = fcp_async_core::time::timeout(
        remaining_timeout,
        perform_host_http_egress(&guard_request, &mut decision, &authorized.constraints),
    )
    .await
    .map_err(|_| {
        HostError::PreflightFailed(format!(
            "host-egress HTTP request to `{}` timed out after {}ms",
            decision.canonical_host, authorized.constraints.total_timeout_ms
        ))
    })??;
    Ok(HostEgressHttpResponse {
        status: response.status,
        headers: response.headers,
        body: response.body,
        egress: authorized.metadata(&decision, started_at.elapsed().as_millis()),
    })
}

async fn refresh_host_egress_credential_after_unauthorized(
    state: &Arc<AppState>,
    authorized: &AuthorizedHostEgress,
    credential_id: &str,
    lease: &CredentialLease,
    started_at: Instant,
) -> HostResult<CredentialLease> {
    let requested = CredentialId::parse(credential_id).map_err(|err| {
        HostError::PreflightFailed(format!(
            "host-egress credential id `{credential_id}` is invalid during refresh: {err}"
        ))
    })?;
    if requested != lease.credential_id {
        return Err(HostError::PreflightFailed(format!(
            "host-egress credential id `{credential_id}` does not match leased credential during refresh"
        )));
    }

    let host_allow = lease
        .payload
        .auth_profile_host_allow()
        .map(<[String]>::to_vec)
        .unwrap_or_default();
    let mut profile = lease.payload.as_auth_profile().cloned().ok_or_else(|| {
        HostError::PreflightFailed(
            "host-egress credential refresh requires an auth-profile payload".to_string(),
        )
    })?;
    let remaining_timeout =
        host_egress_remaining_timeout(authorized, started_at).ok_or_else(|| {
            HostError::PreflightFailed(
                "host-egress operation deadline exhausted before OAuth credential refresh"
                    .to_string(),
            )
        })?;
    let transport = BlockingOAuthTransport::with_timeout(remaining_timeout).map_err(|err| {
        HostError::PreflightFailed(format!("host-egress OAuth refresh transport failed: {err}"))
    })?;
    let cx = fcp_async_core::compatibility_cx();
    let refresh_result = fcp_async_core::time::timeout(remaining_timeout, async {
        match &mut profile.method {
            AuthMethodKind::OAuthDeviceCode(method) => {
                method.refresh_with_transport(&cx, &transport).await
            }
            AuthMethodKind::OAuthAuthCode(method) => {
                method.refresh_with_transport(&cx, &transport).await
            }
            other => Err(AuthError::UnsupportedMethod {
                method: other.id(),
                operation: "host_egress_credential_refresh",
            }),
        }
    })
    .await
    .map_err(|_| {
        HostError::PreflightFailed(
            "host-egress OAuth credential refresh exceeded the operation deadline".to_string(),
        )
    })?;
    refresh_result.map_err(|err| {
        HostError::PreflightFailed(format!(
            "host-egress OAuth credential refresh failed: {err}"
        ))
    })?;

    let refreshed_payload = CredentialPayload::auth_profile_with_allowed_hosts(profile, host_allow);
    let remaining_timeout =
        host_egress_remaining_timeout(authorized, started_at).ok_or_else(|| {
            HostError::PreflightFailed(
                "host-egress operation deadline exhausted before refreshed credential persistence"
                    .to_string(),
            )
        })?;
    let persist_result = fcp_async_core::time::timeout(remaining_timeout, async {
        state.credential_pools.lock().await.replace_payload_in_zone(
            &authorized.zone_id,
            lease.credential_id,
            refreshed_payload.clone(),
        )
    })
    .await
    .map_err(|_| {
        HostError::PreflightFailed(
            "host-egress refreshed credential persistence exceeded the operation deadline"
                .to_string(),
        )
    })?;
    persist_result.map_err(|err| {
        HostError::PreflightFailed(format!(
            "host-egress refreshed credential could not be persisted: {err}"
        ))
    })?;

    Ok(CredentialLease {
        token: lease.token,
        credential_id: lease.credential_id,
        payload: refreshed_payload,
        pool_key: lease.pool_key.clone(),
    })
}

struct RawHttpEgressResponse {
    status: u16,
    headers: Vec<HostEgressHttpHeader>,
    body: fcp_manifest::Base64Bytes,
}

const HOST_EGRESS_EXTRA_CA_PEM_ENV: &str = "FCP_HOST_EGRESS_EXTRA_CA_PEM";
const HOST_EGRESS_EXTRA_CA_PEM_FILE_ENV: &str = "FCP_HOST_EGRESS_EXTRA_CA_PEM_FILE";

#[cfg(test)]
static HOST_EGRESS_TEST_EXTRA_CA_PEMS: std::sync::OnceLock<StdMutex<Vec<Vec<u8>>>> =
    std::sync::OnceLock::new();

#[cfg(test)]
fn register_host_egress_test_extra_ca_pem(pem: impl Into<Vec<u8>>) {
    HOST_EGRESS_TEST_EXTRA_CA_PEMS
        .get_or_init(|| StdMutex::new(Vec::new()))
        .lock()
        .expect("host-egress test CA lock")
        .push(pem.into());
}

fn host_egress_extra_ca_pem_blobs() -> HostResult<Vec<Vec<u8>>> {
    let mut blobs = Vec::new();
    if let Some(pem) = read_optional_trimmed_env_string(HOST_EGRESS_EXTRA_CA_PEM_ENV)? {
        blobs.push(pem.into_bytes());
    }
    if let Some(path) = read_optional_trimmed_env_string(HOST_EGRESS_EXTRA_CA_PEM_FILE_ENV)? {
        let bytes = std::fs::read(&path).map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress extra CA bundle `{path}` could not be read: {err}"
            ))
        })?;
        if bytes.iter().any(|byte| !byte.is_ascii_whitespace()) {
            blobs.push(bytes);
        }
    }
    #[cfg(test)]
    if let Some(lock) = HOST_EGRESS_TEST_EXTRA_CA_PEMS.get() {
        blobs.extend(
            lock.lock()
                .expect("host-egress test CA lock")
                .iter()
                .cloned(),
        );
    }
    Ok(blobs)
}

fn host_egress_extra_ca_roots_for_rustls(
    protocol: &str,
    host: &str,
) -> HostResult<Vec<rustls::pki_types::CertificateDer<'static>>> {
    let mut roots = Vec::new();
    for pem in host_egress_extra_ca_pem_blobs()? {
        let mut reader = Cursor::new(pem.as_slice());
        let certs = rustls_pemfile::certs(&mut reader)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|err| {
                HostError::PreflightFailed(format!(
                    "host-egress {protocol} extra CA bundle for `{host}` is invalid: {err}"
                ))
            })?;
        if certs.is_empty() {
            return Err(HostError::PreflightFailed(format!(
                "host-egress {protocol} extra CA bundle for `{host}` did not contain any certificates"
            )));
        }
        roots.extend(certs);
    }
    Ok(roots)
}

fn validate_host_egress_spki_pins(pins: &[Vec<u8>], protocol: &str, host: &str) -> HostResult<()> {
    if pins.iter().any(Vec::is_empty) {
        return Err(HostError::PreflightFailed(format!(
            "host-egress {protocol} SPKI pin set for `{host}` contains an empty raw DER SubjectPublicKeyInfo pin"
        )));
    }
    Ok(())
}

fn host_egress_leaf_spki_der(cert_der: &[u8], protocol: &str, host: &str) -> HostResult<Vec<u8>> {
    let (_, cert) = x509_parser::parse_x509_certificate(cert_der).map_err(|err| {
        HostError::PreflightFailed(format!(
            "host-egress {protocol} peer certificate for `{host}` could not be parsed for SPKI extraction: {err}"
        ))
    })?;
    Ok(cert.public_key().raw.to_vec())
}

fn host_egress_rustls_certificate_error(message: impl Into<String>) -> rustls::Error {
    rustls::Error::InvalidCertificate(rustls::CertificateError::Other(rustls::OtherError(
        Arc::new(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            message.into(),
        )),
    )))
}

struct HostEgressSpkiVerifier {
    inner: Arc<dyn rustls::client::danger::ServerCertVerifier>,
    spki_pins: Vec<Vec<u8>>,
    protocol: &'static str,
    host: String,
}

impl fmt::Debug for HostEgressSpkiVerifier {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("HostEgressSpkiVerifier")
            .field("protocol", &self.protocol)
            .field("host", &self.host)
            .field("pin_count", &self.spki_pins.len())
            .finish_non_exhaustive()
    }
}

impl rustls::client::danger::ServerCertVerifier for HostEgressSpkiVerifier {
    fn verify_server_cert(
        &self,
        end_entity: &rustls::pki_types::CertificateDer<'_>,
        intermediates: &[rustls::pki_types::CertificateDer<'_>],
        server_name: &rustls::pki_types::ServerName<'_>,
        ocsp_response: &[u8],
        now: rustls::pki_types::UnixTime,
    ) -> Result<rustls::client::danger::ServerCertVerified, rustls::Error> {
        let verified = self.inner.verify_server_cert(
            end_entity,
            intermediates,
            server_name,
            ocsp_response,
            now,
        )?;
        if !self.spki_pins.is_empty() {
            let spki = host_egress_leaf_spki_der(end_entity.as_ref(), self.protocol, &self.host)
                .map_err(|err| host_egress_rustls_certificate_error(err.to_string()))?;
            DefaultTlsVerifier
                .verify_spki(&spki, &self.spki_pins)
                .map_err(|err| {
                    host_egress_rustls_certificate_error(format!(
                        "host-egress {} SPKI pin verification for `{}` failed: {err}",
                        self.protocol, self.host
                    ))
                })?;
        }
        Ok(verified)
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &rustls::pki_types::CertificateDer<'_>,
        dss: &rustls::DigitallySignedStruct,
    ) -> Result<rustls::client::danger::HandshakeSignatureValid, rustls::Error> {
        self.inner.verify_tls12_signature(message, cert, dss)
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &rustls::pki_types::CertificateDer<'_>,
        dss: &rustls::DigitallySignedStruct,
    ) -> Result<rustls::client::danger::HandshakeSignatureValid, rustls::Error> {
        self.inner.verify_tls13_signature(message, cert, dss)
    }

    fn supported_verify_schemes(&self) -> Vec<rustls::SignatureScheme> {
        self.inner.supported_verify_schemes()
    }

    fn requires_raw_public_keys(&self) -> bool {
        self.inner.requires_raw_public_keys()
    }

    fn root_hint_subjects(&self) -> Option<&[rustls::DistinguishedName]> {
        self.inner.root_hint_subjects()
    }
}

fn host_egress_rustls_client_config(
    protocol: &'static str,
    host: &str,
    spki_pins: &[Vec<u8>],
    alpn_protocols: Vec<Vec<u8>>,
) -> HostResult<rustls::ClientConfig> {
    validate_host_egress_spki_pins(spki_pins, protocol, host)?;
    let crypto_provider = Arc::new(rustls::crypto::ring::default_provider());
    let extra_roots = host_egress_extra_ca_roots_for_rustls(protocol, host)?;
    let platform_verifier = rustls_platform_verifier::Verifier::new_with_extra_roots(
        extra_roots,
        Arc::clone(&crypto_provider),
    )
    .map_err(|err| {
        HostError::PreflightFailed(format!(
            "host-egress {protocol} TLS verifier for `{host}` could not be built: {err}"
        ))
    })?;
    let verifier = Arc::new(HostEgressSpkiVerifier {
        inner: Arc::new(platform_verifier),
        spki_pins: spki_pins.to_vec(),
        protocol,
        host: host.to_string(),
    });
    let builder = rustls::ClientConfig::builder_with_provider(crypto_provider)
        .with_safe_default_protocol_versions()
        .map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress {protocol} TLS protocol versions for `{host}` could not be configured: {err}"
            ))
        })?;
    let mut config = builder
        .dangerous()
        .with_custom_certificate_verifier(verifier)
        .with_no_client_auth();
    config.alpn_protocols = alpn_protocols;
    Ok(config)
}

async fn perform_host_http_egress(
    request: &EgressHttpRequest,
    decision: &mut fcp_sandbox::EgressDecision,
    constraints: &NetworkConstraints,
) -> HostResult<RawHttpEgressResponse> {
    let url = url::Url::parse(&request.url).map_err(|err| {
        HostError::PreflightFailed(format!("host-egress HTTP URL rejected after policy: {err}"))
    })?;
    if !matches!(url.scheme(), "http" | "https") {
        return Err(HostError::PreflightFailed(format!(
            "host-egress HTTP transport only supports `http` and `https`; `{}` was policy-checked but cannot be transported",
            url.scheme()
        )));
    }
    verify_host_egress_tls_requirements(decision, url.host_str(), "HTTP")?;
    let is_https = url.scheme() == "https";
    if !is_https && !decision.spki_pins.is_empty() {
        return Err(HostError::PreflightFailed(format!(
            "host-egress HTTP SPKI pin verification for `{}` requires HTTPS; cleartext HTTP has no peer certificate chain",
            decision.canonical_host
        )));
    }
    let socket_addrs = resolve_host_egress_decision(decision, constraints, "HTTP").await?;
    let mut builder = reqwest::Client::builder()
        .use_rustls_tls()
        .connect_timeout(Duration::from_millis(u64::from(
            constraints.connect_timeout_ms,
        )))
        .timeout(Duration::from_millis(u64::from(
            constraints.total_timeout_ms,
        )))
        .redirect(host_http_redirect_policy(&url, constraints)?);
    if is_https {
        builder = builder.tls_backend_preconfigured(host_egress_rustls_client_config(
            "HTTP",
            &decision.canonical_host,
            &decision.spki_pins,
            vec![b"h2".to_vec(), b"http/1.1".to_vec()],
        )?);
    }
    builder = builder.resolve_to_addrs(&decision.canonical_host, &socket_addrs);
    let client = builder.build().map_err(|err| {
        HostError::PreflightFailed(format!(
            "host-egress HTTP client for `{}` could not be built: {err}",
            decision.canonical_host
        ))
    })?;
    let method = reqwest::Method::from_bytes(request.method.as_bytes()).map_err(|err| {
        HostError::PreflightFailed(format!(
            "host-egress HTTP method `{}` rejected after policy: {err}",
            request.method
        ))
    })?;
    let mut outbound = client.request(method, url);
    for header in &request.headers {
        if forbidden_egress_request_header(&header.name) {
            continue;
        }
        validate_wire_header(&header.name, &header.value)?;
        let name =
            reqwest::header::HeaderName::from_bytes(header.name.as_bytes()).map_err(|err| {
                HostError::PreflightFailed(format!(
                    "host-egress HTTP header name `{}` rejected after policy: {err}",
                    header.name
                ))
            })?;
        let value = reqwest::header::HeaderValue::from_str(&header.value).map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress HTTP header `{}` value rejected after policy: {err}",
                header.name
            ))
        })?;
        outbound = outbound.header(name, value);
    }
    if let Some(body) = request.body.as_ref() {
        outbound = outbound.body(body.to_vec());
    }
    let request_error_label = format!(
        "host-egress HTTP request (max_redirects={})",
        constraints.max_redirects
    );
    let response = outbound.send().await.map_err(|err| {
        map_reqwest_host_egress_error(err, &request_error_label, &decision.canonical_host)
    })?;
    let status = response.status().as_u16();
    let headers = response
        .headers()
        .iter()
        .filter_map(|(name, value)| {
            value.to_str().ok().map(|value| HostEgressHttpHeader {
                name: name.as_str().to_string(),
                value: value.to_string(),
            })
        })
        .collect::<Vec<_>>();
    let body = read_bounded_reqwest_body(
        response,
        constraints.max_response_bytes,
        "host-egress HTTP response",
    )
    .await?;
    Ok(RawHttpEgressResponse {
        status,
        headers,
        body: fcp_manifest::Base64Bytes::from_vec(body),
    })
}

fn host_http_redirect_policy(
    url: &url::Url,
    constraints: &NetworkConstraints,
) -> HostResult<reqwest::redirect::Policy> {
    let origin_scheme = url.scheme().to_string();
    let origin_host = url.host_str().ok_or_else(|| {
        HostError::PreflightFailed("host-egress HTTP URL missing host".to_string())
    })?;
    let origin_host = origin_host.to_ascii_lowercase();
    let origin_port = url.port_or_known_default().ok_or_else(|| {
        HostError::PreflightFailed(format!(
            "host-egress HTTP URL `{url}` has no explicit or default port"
        ))
    })?;
    let max_redirects = usize::from(constraints.max_redirects);
    Ok(reqwest::redirect::Policy::custom(move |attempt| {
        if attempt.previous().len() > max_redirects {
            return attempt.error(std::io::Error::new(
                std::io::ErrorKind::PermissionDenied,
                format!("host-egress HTTP redirect limit exceeded: max_redirects={max_redirects}"),
            ));
        }
        let next = attempt.url();
        let next_display = next.to_string();
        let next_host = next.host_str().map(str::to_ascii_lowercase);
        let next_port = next.port_or_known_default();
        if next.scheme() != origin_scheme
            || next_host.as_deref() != Some(origin_host.as_str())
            || next_port != Some(origin_port)
        {
            return attempt.error(std::io::Error::new(
                std::io::ErrorKind::PermissionDenied,
                format!(
                    "host-egress HTTP redirect denied: `{next_display}` leaves authorized origin {origin_scheme}://{origin_host}:{origin_port}"
                ),
            ));
        }
        attempt.follow()
    }))
}

async fn read_bounded_reqwest_body(
    mut response: reqwest::Response,
    max_response_bytes: u64,
    label: &str,
) -> HostResult<Vec<u8>> {
    let max = usize::try_from(max_response_bytes).unwrap_or(usize::MAX);
    let mut body = Vec::new();
    while let Some(chunk) = response
        .chunk()
        .await
        .map_err(|err| map_reqwest_host_egress_error(err, label, "streaming response body"))?
    {
        if body.len().saturating_add(chunk.len()) > max {
            return Err(HostError::PreflightFailed(format!(
                "{label} exceeded max_response_bytes={max_response_bytes}"
            )));
        }
        body.extend_from_slice(&chunk);
    }
    Ok(body)
}

fn map_reqwest_host_egress_error(err: reqwest::Error, label: &str, host: &str) -> HostError {
    let category = if err.is_redirect() {
        "redirect denied"
    } else if err.is_timeout() {
        "timed out"
    } else if err.is_connect() {
        "connect failed"
    } else if err.is_body() {
        "body read failed"
    } else {
        "failed"
    };
    let diagnostics = format!("{err:?}");
    HostError::PreflightFailed(format!(
        "{label} to `{host}` {category}: {err}; diagnostics: {diagnostics}"
    ))
}

async fn resolve_host_egress_decision(
    decision: &mut fcp_sandbox::EgressDecision,
    constraints: &NetworkConstraints,
    protocol: &'static str,
) -> HostResult<Vec<SocketAddr>> {
    if !decision.resolved_ips.is_empty() {
        return Ok(decision
            .resolved_ips
            .iter()
            .copied()
            .map(|ip| SocketAddr::new(ip, decision.port))
            .collect());
    }
    let ips = resolve_host_egress_ips(
        decision.canonical_host.clone(),
        decision.port,
        constraints.connect_timeout_ms,
        protocol,
    )
    .await?;
    validate_host_egress_resolved_ips(decision, constraints, ips, protocol)
}

async fn resolve_host_egress_ips(
    host: String,
    port: u16,
    connect_timeout_ms: u32,
    protocol: &'static str,
) -> HostResult<Vec<IpAddr>> {
    if let Ok(ip) = host.parse::<IpAddr>() {
        return Ok(vec![ip]);
    }
    let host_for_error = host.clone();
    let resolver = task::spawn(async move {
        (host.as_str(), port)
            .to_socket_addrs()
            .map(|addrs| addrs.map(|addr| addr.ip()).collect::<Vec<_>>())
    });
    let ips = fcp_async_core::time::timeout(Duration::from_millis(u64::from(connect_timeout_ms)), resolver)
        .await
        .map_err(|_| {
            HostError::PreflightFailed(format!(
                "host-egress {protocol} DNS resolution for `{host_for_error}` timed out after {connect_timeout_ms}ms"
            ))
        })?
        .map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress {protocol} DNS resolution task for `{host_for_error}` failed: {err}"
            ))
        })?
        .map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress {protocol} DNS resolution for `{host_for_error}` failed: {err}"
            ))
        })?;
    if ips.is_empty() {
        return Err(HostError::PreflightFailed(format!(
            "host-egress {protocol} DNS resolution for `{host_for_error}` returned no addresses"
        )));
    }
    Ok(ips)
}

fn validate_host_egress_resolved_ips(
    decision: &mut fcp_sandbox::EgressDecision,
    constraints: &NetworkConstraints,
    ips: Vec<IpAddr>,
    protocol: &str,
) -> HostResult<Vec<SocketAddr>> {
    let guard = EgressGuard::new();
    let allowed = guard
        .validate_dns_resolution(&ips, constraints)
        .map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress {protocol} DNS policy rejected `{}`: {err}",
                decision.canonical_host
            ))
        })?;
    if allowed.is_empty() {
        return Err(HostError::PreflightFailed(format!(
            "host-egress {protocol} DNS resolution for `{}` returned no usable addresses",
            decision.canonical_host
        )));
    }
    decision.resolved_ips = allowed.clone();
    Ok(allowed
        .into_iter()
        .map(|ip| SocketAddr::new(ip, decision.port))
        .collect())
}

fn verify_host_egress_tls_requirements(
    decision: &fcp_sandbox::EgressDecision,
    actual_sni: Option<&str>,
    protocol: &str,
) -> HostResult<()> {
    if let Some(expected_sni) = decision.expected_sni.as_deref() {
        let actual_sni = actual_sni.unwrap_or_default();
        DefaultTlsVerifier
            .verify_sni(actual_sni, expected_sni)
            .map_err(|err| {
                HostError::PreflightFailed(format!(
                    "host-egress {protocol} SNI policy rejected `{}`: {err}",
                    decision.canonical_host
                ))
            })?;
    }
    Ok(())
}

async fn connect_host_egress_tcp_socket(
    decision: &mut fcp_sandbox::EgressDecision,
    constraints: &NetworkConstraints,
    protocol: &'static str,
) -> HostResult<fcp_async_core::net::TcpStream> {
    let addrs = resolve_host_egress_decision(decision, constraints, protocol).await?;
    let timeout = Duration::from_millis(u64::from(constraints.connect_timeout_ms));
    let mut last_error = None;
    for addr in addrs {
        match fcp_async_core::time::timeout(timeout, fcp_async_core::net::TcpStream::connect(addr))
            .await
        {
            Ok(Ok(stream)) => return Ok(stream),
            Ok(Err(err)) => last_error = Some(format!("{addr}: {err}")),
            Err(_) => last_error = Some(format!("{addr}: timed out after {timeout:?}")),
        }
    }
    Err(HostError::PreflightFailed(format!(
        "host-egress {protocol} connect to `{}` failed for all resolved addresses: {}",
        decision.canonical_host,
        last_error.unwrap_or_else(|| "no attempts were made".to_string())
    )))
}

fn forbidden_egress_request_header(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "host" | "connection" | "content-length" | "transfer-encoding"
    )
}

fn validate_wire_header(name: &str, value: &str) -> HostResult<()> {
    if name.is_empty()
        || name
            .bytes()
            .any(|byte| matches!(byte, b'\r' | b'\n' | b':' | 0) || byte.is_ascii_control())
        || value.bytes().any(|byte| matches!(byte, b'\r' | b'\n' | 0))
    {
        return Err(HostError::PreflightFailed(
            "host-egress HTTP header contains invalid wire characters".to_string(),
        ));
    }
    Ok(())
}

async fn read_bounded_response<T>(
    stream: &mut T,
    max_response_bytes: u64,
    label: &str,
) -> HostResult<Vec<u8>>
where
    T: AsyncRead + Unpin + ?Sized,
{
    let max = usize::try_from(max_response_bytes).unwrap_or(usize::MAX);
    let mut raw = Vec::new();
    let mut buf = [0_u8; 8192];
    loop {
        let read = stream
            .read(&mut buf)
            .await
            .map_err(|err| HostError::PreflightFailed(format!("{label} read failed: {err}")))?;
        if read == 0 {
            break;
        }
        if raw.len().saturating_add(read) > max {
            return Err(HostError::PreflightFailed(format!(
                "{label} exceeded max_response_bytes={max_response_bytes}"
            )));
        }
        raw.extend_from_slice(&buf[..read]);
    }
    Ok(raw)
}

async fn read_at_most_response<T>(
    stream: &mut T,
    max_response_bytes: u64,
    label: &str,
) -> HostResult<Vec<u8>>
where
    T: AsyncRead + Unpin + ?Sized,
{
    let max = usize::try_from(max_response_bytes).unwrap_or(usize::MAX);
    let mut raw = Vec::new();
    let mut buf = [0_u8; 8192];
    while raw.len() < max {
        let remaining = max - raw.len();
        let read_len = remaining.min(buf.len());
        let read = stream
            .read(&mut buf[..read_len])
            .await
            .map_err(|err| HostError::PreflightFailed(format!("{label} read failed: {err}")))?;
        if read == 0 {
            break;
        }
        raw.extend_from_slice(&buf[..read]);
    }
    Ok(raw)
}

trait HostEgressIo: AsyncRead + AsyncWrite + Unpin + Send {}

impl<T> HostEgressIo for T where T: AsyncRead + AsyncWrite + Unpin + Send {}

async fn host_egress_tcp_io(
    request: &HostEgressTcpRequest,
    decision: &mut fcp_sandbox::EgressDecision,
    constraints: &NetworkConstraints,
) -> HostResult<Box<dyn HostEgressIo>> {
    if !request.tls {
        if !decision.spki_pins.is_empty() {
            return Err(HostError::PreflightFailed(format!(
                "host-egress TCP SPKI pin verification for `{}` requires TLS; raw TCP has no peer certificate chain",
                decision.canonical_host
            )));
        }
        let tcp = connect_host_egress_tcp_socket(decision, constraints, "TCP").await?;
        return Ok(Box::new(tcp));
    }
    let actual_sni = request
        .sni_override
        .as_deref()
        .unwrap_or(decision.canonical_host.as_str())
        .to_string();
    verify_host_egress_tls_requirements(decision, Some(&actual_sni), "TCP")?;
    if request
        .sni_override
        .as_deref()
        .is_some_and(|override_sni| override_sni != decision.canonical_host)
    {
        return Err(HostError::PreflightFailed(format!(
            "host-egress TCP SNI override `{}` does not match authorized host `{}`",
            request.sni_override.as_deref().unwrap_or_default(),
            decision.canonical_host
        )));
    }
    let tcp = connect_host_egress_tcp_socket(decision, constraints, "TCP").await?;
    let connector = asupersync::tls::TlsConnector::new(host_egress_rustls_client_config(
        "TCP",
        &decision.canonical_host,
        &decision.spki_pins,
        Vec::new(),
    )?);
    let timeout = Duration::from_millis(u64::from(constraints.connect_timeout_ms));
    let tls = fcp_async_core::time::timeout(timeout, connector.connect(&actual_sni, tcp))
        .await
        .map_err(|_| {
            HostError::PreflightFailed(format!(
                "host-egress TCP TLS handshake with `{}` timed out after {}ms",
                decision.canonical_host, constraints.connect_timeout_ms
            ))
        })?
        .map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress TCP TLS handshake with `{}` failed: {err}",
                decision.canonical_host
            ))
        })?;
    Ok(Box::new(tls))
}

async fn host_egress_tcp_handler(
    State(state): State<Arc<AppState>>,
    Json(request): Json<HostEgressTcpRequest>,
) -> Result<Json<HostEgressTcpResponse>, (StatusCode, String)> {
    let started_at = Instant::now();
    let authorized =
        authorize_host_egress_context(&state, &request.context, &request.context.resource_uri)
            .await
            .map_err(map_host_error)?;
    let lease = acquire_host_egress_credential_lease(
        &state,
        &authorized.zone_id,
        request.credential_id.as_deref(),
        &authorized.credential_allow,
    )
    .await
    .map_err(map_host_error)?;
    let injector = HostCredentialInjector::new(lease.clone());
    let noop = NoOpCredentialInjector;
    let injector_ref: &dyn CredentialInjector = if request.credential_id.is_some() {
        &injector
    } else {
        &noop
    };
    let result =
        authorize_and_perform_host_tcp_egress(&authorized, request, injector_ref, started_at).await;
    if let Some(lease) = lease {
        release_host_egress_credential_lease(&state, lease).await;
    }
    result.map(Json).map_err(map_host_error)
}

async fn authorize_and_perform_host_tcp_egress(
    authorized: &AuthorizedHostEgress,
    request: HostEgressTcpRequest,
    injector: &dyn CredentialInjector,
    started_at: Instant,
) -> HostResult<HostEgressTcpResponse> {
    let guard_request = EgressTcpConnectRequest {
        host: request.host.clone(),
        port: request.port,
        tls: request.tls,
        sni_override: request.sni_override.clone(),
        credential_id: request.credential_id.clone(),
    };
    let mut decision = fcp_host::authorize_runtime_tcp_egress(
        &authorized.decision_context(),
        &authorized.constraints,
        &guard_request,
        injector,
    )?;
    let response = fcp_async_core::time::timeout(
        Duration::from_millis(u64::from(authorized.constraints.total_timeout_ms)),
        perform_host_tcp_egress(&request, &mut decision, &authorized.constraints),
    )
    .await
    .map_err(|_| {
        HostError::PreflightFailed(format!(
            "host-egress TCP request to `{}` timed out after {}ms",
            decision.decision.canonical_host, authorized.constraints.total_timeout_ms
        ))
    })??;
    Ok(HostEgressTcpResponse {
        bytes_written: response.bytes_written,
        bytes_read: response.bytes_read,
        read: response.read,
        egress: authorized.metadata(&decision.decision, started_at.elapsed().as_millis()),
    })
}

struct RawTcpEgressResponse {
    bytes_written: u64,
    bytes_read: u64,
    read: fcp_manifest::Base64Bytes,
}

async fn perform_host_tcp_egress(
    request: &HostEgressTcpRequest,
    decision: &mut fcp_sandbox::EgressTcpDecision,
    constraints: &NetworkConstraints,
) -> HostResult<RawTcpEgressResponse> {
    let mut stream = host_egress_tcp_io(request, &mut decision.decision, constraints).await?;
    let mut bytes_written = 0_u64;
    if let Some(auth) = decision.tcp_auth.as_deref() {
        stream.write_all(auth).await.map_err(|err| {
            HostError::PreflightFailed(format!(
                "host-egress TCP credential auth write failed: {err}"
            ))
        })?;
        bytes_written = bytes_written.saturating_add(auth.len().try_into().unwrap_or(u64::MAX));
    }
    if let Some(write) = request.write.as_ref() {
        stream.write_all(write.as_bytes()).await.map_err(|err| {
            HostError::PreflightFailed(format!("host-egress TCP write failed: {err}"))
        })?;
        bytes_written =
            bytes_written.saturating_add(write.as_bytes().len().try_into().unwrap_or(u64::MAX));
    }
    stream.flush().await.map_err(|err| {
        HostError::PreflightFailed(format!("host-egress TCP flush failed: {err}"))
    })?;
    let read_limit = request
        .read_limit_bytes
        .unwrap_or(constraints.max_response_bytes)
        .min(constraints.max_response_bytes);
    let read = if request.read_limit_bytes.is_some() {
        read_at_most_response(stream.as_mut(), read_limit, "host-egress TCP response").await?
    } else {
        read_bounded_response(stream.as_mut(), read_limit, "host-egress TCP response").await?
    };
    Ok(RawTcpEgressResponse {
        bytes_written,
        bytes_read: read.len().try_into().unwrap_or(u64::MAX),
        read: fcp_manifest::Base64Bytes::from_vec(read),
    })
}

/// Handle POST /invoke.
///
/// Identity binding:
///   - The default capability-based identity model treats the
///     `capability_token` claim set as the request's authoritative
///     principal. Callers that want defense-in-depth — e.g. an
///     upstream proxy that has already authenticated the caller —
///     can set the `X-Principal` header; its value is forwarded as
///     `principal_override` and `verify_live_request` rejects the
///     request if the header does not match the token's subject/
///     principal_id claim.
///   - Absent the header, behavior is unchanged: the token's claim
///     set drives the principal (br-flywheel_connectors-t623k).
fn normalized_invalid_filter_class(message: &str) -> &'static str {
    if message.starts_with("invalid manifest") {
        "local.validation.manifest"
    } else if message.starts_with("runtime network enforcement claim") {
        "local.validation.network_claim"
    } else if message.starts_with("invalid prewarm policy")
        || message.starts_with("connector '") && message.contains("per_invocation lifecycle")
    {
        "local.validation.lifecycle"
    } else if message.starts_with("invalid connector id")
        || message.starts_with("duplicate connector id")
        || message.starts_with("invalid version for connector")
    {
        "local.validation.inventory"
    } else if message.contains("HRW") || message.contains("hrw") {
        "local.validation.hrw"
    } else {
        "local.validation"
    }
}

fn normalized_host_error_class(error: &HostError) -> &'static str {
    match error {
        HostError::ConnectorNotFound(_) => "local.capability_denied",
        HostError::InvalidFilter(message) => normalized_invalid_filter_class(message),
        HostError::PreflightFailed(_) | HostError::ZoneEnvelopeRequired(_) => "local.policy_denied",
        HostError::Unavailable(_) => "transport.host_connector",
        HostError::ConnectorFrameLimit { .. } => "transport.frame_limit",
        HostError::RegistryError(_) => "internal.registry",
        HostError::CacheError(_) => "internal.cache",
        HostError::Internal(_) => "internal.runtime",
    }
}

async fn invoke_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<InvokeRequest>,
) -> Result<Json<InvokeResponse>, (StatusCode, String)> {
    invoke_handler_inner(state, headers, request, None).await
}

async fn invoke_handler_inner(
    state: Arc<AppState>,
    headers: HeaderMap,
    request: InvokeRequest,
    trusted_resource: Option<TrustedResourceBinding>,
) -> Result<Json<InvokeResponse>, (StatusCode, String)> {
    request.validate_idempotency_key().map_err(|err| {
        map_host_error(HostError::InvalidFilter(format!(
            "invalid invoke request: {err}"
        )))
    })?;

    let connector_id = request.connector_id.clone();
    let operation = request.operation.clone();
    let operation_name = operation.to_string();
    let correlation_id = request
        .correlation_id
        .as_ref()
        .map(std::string::ToString::to_string);
    let operation_id = request.id.to_string();
    let idempotency_key = request.idempotency_key.clone();
    let zone_id = request.zone_id.clone();
    let asserted_principal = extract_principal_header(&headers);
    let started_at = Instant::now();
    let host_request_bytes = serde_json::to_vec(&request)
        .map(|encoded| u64::try_from(encoded.len()).unwrap_or(u64::MAX))
        .unwrap_or(0);

    tracing::debug!(
        event = "invoke_request",
        schema_version = "fwc.google_workspace.telemetry.v1",
        event_type = "workspace.phase.host",
        producer_layer = "host",
        host_phase = "request",
        connector_id = %connector_id,
        operation = %operation,
        operation_id = %operation_id,
        correlation_id,
        host_request_bytes,
        "processing invoke request"
    );

    // br-mvax3: build an audit context once so every phase append for
    // this request shares zone/actor/connector/operation/correlation.
    let audit_ctx = fcp_host::InvokeAuditContext {
        zone_id: zone_id.to_string(),
        actor: asserted_principal
            .clone()
            .unwrap_or_else(|| "anonymous".to_string()),
        connector_id: connector_id.to_string(),
        operation: operation_name.clone(),
        operation_id: operation_id.clone(),
        correlation_id: correlation_id.clone(),
        occurred_at: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0),
    };

    let verified = match evaluate_verified_live_preflight_with_resource(
        &state,
        &request,
        asserted_principal.as_deref(),
        trusted_resource.as_ref(),
    )
    .await
    {
        Ok(verified) => verified,
        Err(error) => {
            emit_n8n_run_once_host_error_diagnostic(&error);
            let reason = error.to_string();
            // br-mvax3: deny path MUST append a hash-linked audit event so
            // the README "every operation produces an audit event" claim is
            // literally true even for denied requests.
            if let Err(err) = state.invoke_audit.append(
                &audit_ctx,
                fcp_host::InvokePhase::PreflightDeny {
                    reason: reason.clone(),
                },
            ) {
                tracing::warn!(
                    event = "invoke_audit_append_error",
                    phase = "deny",
                    error = %err,
                    "failed to append invoke deny audit event"
                );
            }
            tracing::warn!(
                event = "invoke_error",
                schema_version = "fwc.google_workspace.telemetry.v1",
                event_type = "workspace.phase.host",
                producer_layer = "host",
                host_phase = "preflight_denied",
                connector_id = %connector_id,
                operation = %operation,
                operation_id = %operation_id,
                correlation_id,
                error_class = "local.policy_denied",
                duration_ms = started_at.elapsed().as_millis() as u64,
                host_total_us =
                    u64::try_from(started_at.elapsed().as_micros()).unwrap_or(u64::MAX),
                "invoke request failed preflight"
            );
            return Err(map_host_error(HostError::PreflightFailed(reason)));
        }
    };
    let per_invocation_plan = verified.per_invocation_plan;

    // br-mvax3: preflight allow → append hash-linked audit event before
    // dispatch (matches README's End-to-End Request Flow §11).
    if let Err(err) = state
        .invoke_audit
        .append(&audit_ctx, fcp_host::InvokePhase::PreflightAllow)
    {
        tracing::warn!(
            event = "invoke_audit_append_error",
            phase = "allow",
            error = %err,
            "failed to append invoke allow audit event"
        );
    }

    // br-ug5fk: cancellation ownership must follow the verified token
    // principal, not the optional X-Principal override header. The
    // header is only an equality check against the authenticated token
    // subject/principal_id claim; absent it, the request is still
    // authenticated and must not fall back to ownerless cancellation.
    track_verified_cancellation_owner(state.cancellation.as_ref(), &operation_id, &request)
        .map_err(map_host_error)?;
    let source_request = request.clone();
    let invoke_result = state
        .registry
        .invoke_with_execution_plan(&state, request, per_invocation_plan)
        .await;
    state.cancellation.complete(&operation_id);

    match invoke_result {
        Ok(response) => {
            let response = maybe_orchestrate_mcp_sampling(
                &state,
                asserted_principal.as_deref(),
                &source_request,
                response,
            )
            .await
            .map_err(map_host_error)?;
            let duration_ms = elapsed_millis(started_at);
            record_invoke_budget_usage(
                state.budget.as_ref(),
                Some(&zone_id),
                &connector_id,
                &operation_name,
                Some(&response),
            )
            .await;
            record_invoke_receipt_summary(
                state.lifecycle.as_ref(),
                connector_id.as_str(),
                &operation_name,
                idempotency_key,
                &response,
                duration_ms,
            )
            .await;
            // br-mvax3: append hash-linked audit event AFTER dispatch.
            // Fires whether or not the connector returned a receipt_id —
            // this is the failure mode the bead called out (the old
            // ReceiptSummary path silently produced zero events for
            // receipt-less connector returns).
            if let Err(err) = state.invoke_audit.append(
                &audit_ctx,
                fcp_host::InvokePhase::DispatchResult {
                    receipt_id: response.receipt_id.as_ref().map(ToString::to_string),
                    success: matches!(response.status, InvokeStatus::Ok),
                    duration_ms,
                },
            ) {
                tracing::warn!(
                    event = "invoke_audit_append_error",
                    phase = "result",
                    error = %err,
                    "failed to append invoke result audit event"
                );
            }
            tracing::info!(
                event = "invoke_response",
                schema_version = "fwc.google_workspace.telemetry.v1",
                event_type = "workspace.phase.host",
                producer_layer = "host",
                host_phase = "response",
                connector_id = %connector_id,
                operation = %operation,
                operation_id = %operation_id,
                correlation_id,
                status = ?response.status,
                duration_ms,
                host_total_us = u64::try_from(started_at.elapsed().as_micros()).unwrap_or(u64::MAX),
                host_response_bytes = serde_json::to_vec(&response)
                    .map(|encoded| u64::try_from(encoded.len()).unwrap_or(u64::MAX))
                    .unwrap_or(0),
                "invoke request complete"
            );
            Ok(Json(response))
        }
        Err(err) => {
            emit_n8n_run_once_host_error_diagnostic(&err);
            let duration_ms = started_at.elapsed().as_millis() as u64;
            record_invoke_budget_usage(
                state.budget.as_ref(),
                Some(&zone_id),
                &connector_id,
                &operation_name,
                None,
            )
            .await;
            // br-mvax3: dispatch error path also appends — the invoke
            // chain is exhaustive across all four phases.
            if let Err(audit_err) = state.invoke_audit.append(
                &audit_ctx,
                fcp_host::InvokePhase::DispatchError {
                    error: err.to_string(),
                    duration_ms,
                },
            ) {
                tracing::warn!(
                    event = "invoke_audit_append_error",
                    phase = "error",
                    error = %audit_err,
                    "failed to append invoke error audit event"
                );
            }
            tracing::warn!(
                event = "invoke_error",
                schema_version = "fwc.google_workspace.telemetry.v1",
                event_type = "workspace.phase.host",
                producer_layer = "host",
                host_phase = "dispatch_error",
                connector_id = %connector_id,
                operation = %operation,
                operation_id = %operation_id,
                correlation_id,
                error_class = normalized_host_error_class(&err),
                duration_ms,
                host_total_us = u64::try_from(started_at.elapsed().as_micros()).unwrap_or(u64::MAX),
                "invoke request failed"
            );
            Err(map_host_error(err))
        }
    }
}

async fn record_invoke_receipt_summary(
    lifecycle: &HostAdminStateStore,
    connector_id: &str,
    operation: &str,
    idempotency_key: Option<String>,
    response: &InvokeResponse,
    duration_ms: u64,
) {
    let Some(receipt_id) = response.receipt_id.as_ref() else {
        return;
    };

    let summary = ReceiptSummary {
        receipt_id: receipt_id.to_string(),
        connector_id: connector_id.to_owned(),
        operation: operation.to_owned(),
        success: matches!(response.status, InvokeStatus::Ok),
        duration_ms,
        idempotency_key,
        executed_at: Utc::now(),
    };

    if let Err(err) = lifecycle.record_receipt(summary).await {
        tracing::warn!(
            event = "invoke_receipt_persist_error",
            connector_id,
            operation,
            receipt_id = %receipt_id,
            error = %err,
            "failed to persist invoke receipt summary"
        );
    }
}

async fn record_invoke_budget_usage(
    budget: &BudgetPolicyEngine,
    zone_id: Option<&ZoneId>,
    connector_id: &ConnectorId,
    operation: &str,
    response: Option<&InvokeResponse>,
) {
    let Some(zone_id) = zone_id else {
        return;
    };
    let mut metrics = response
        .and_then(|response| response.usage_metrics.clone())
        .unwrap_or_default();
    if !metrics
        .iter()
        .any(|metric| metric.kind == UsageMetricKind::Requests)
    {
        metrics.push(UsageMetric::requests(1));
    }
    let Some(evaluation) = budget.record_usage(zone_id, metrics.as_slice()).await else {
        return;
    };
    match evaluation.action {
        BudgetAction::Allow => {}
        BudgetAction::Warn | BudgetAction::Deny => {
            tracing::warn!(
                event = "invoke_budget_usage_recorded",
                connector_id = %connector_id,
                operation,
                zone_id = %zone_id,
                action = ?evaluation.action,
                "connector invocation usage exceeded configured budget after execution"
            );
        }
    }
}

fn batch_timeout_error() -> BatchOperationError {
    BatchOperationError {
        code: "BATCH_TIMEOUT".to_string(),
        message: "batch timeout exceeded".to_string(),
        retry_after_ms: None,
    }
}

fn dependency_failed_error() -> BatchOperationError {
    BatchOperationError {
        code: "DEP_FAILED".to_string(),
        message: "dependency failed".to_string(),
        retry_after_ms: None,
    }
}

fn batch_error_from_host_error(err: HostError) -> BatchOperationError {
    let code = match err {
        HostError::ConnectorNotFound(_) => "CONNECTOR_NOT_FOUND",
        HostError::InvalidFilter(_) => "INVALID_REQUEST",
        HostError::RegistryError(_) => "CONNECTOR_ERROR",
        HostError::PreflightFailed(_) => "PREFLIGHT_DENIED",
        HostError::ZoneEnvelopeRequired(_) => "ZONE_ENVELOPE_REQUIRED",
        HostError::CacheError(_) => "CACHE_ERROR",
        HostError::Unavailable(_) => "UNAVAILABLE",
        HostError::ConnectorFrameLimit { .. } => "CONNECTOR_FRAME_LIMIT",
        HostError::Internal(_) => "INTERNAL_ERROR",
    };

    BatchOperationError {
        code: code.to_string(),
        message: err.to_string(),
        retry_after_ms: None,
    }
}

fn skipped_batch_result(id: String, error: Option<BatchOperationError>) -> OperationResult {
    OperationResult {
        id,
        status: OperationResultStatus::Skipped,
        output: None,
        error,
        duration_ms: 0,
    }
}

fn elapsed_millis(started_at: Instant) -> u64 {
    u64::try_from(started_at.elapsed().as_millis()).unwrap_or(u64::MAX)
}

fn dependency_failed_in_batch(
    operation: &HttpBatchOperation,
    results_map: &HashMap<String, OperationResult>,
) -> bool {
    operation.depends_on.iter().any(|dependency_id| {
        results_map
            .get(dependency_id.as_str())
            .is_some_and(|result| result.status != OperationResultStatus::Success)
    })
}

fn batch_status(aborted: bool, completed: usize, failed: usize) -> BatchStatus {
    if aborted && failed > 0 {
        BatchStatus::Aborted
    } else if failed == 0 {
        BatchStatus::Success
    } else if completed == 0 {
        BatchStatus::AllFailed
    } else {
        BatchStatus::PartialSuccess
    }
}

fn build_batch_response(
    request: &HttpBatchInvokeRequest,
    mut results_map: HashMap<String, OperationResult>,
    aborted: bool,
    started_at: Instant,
    schedule_report: Option<BatchScheduleReport>,
) -> BatchInvokeResponse {
    let results: Vec<OperationResult> = request
        .operations
        .iter()
        .map(|operation| {
            results_map
                .remove(operation.id.as_str())
                .unwrap_or_else(|| skipped_batch_result(operation.id.clone(), None))
        })
        .collect();

    let completed = results
        .iter()
        .filter(|result| result.status == OperationResultStatus::Success)
        .count();
    let failed = results
        .iter()
        .filter(|result| result.status == OperationResultStatus::Error)
        .count();
    let skipped = results
        .iter()
        .filter(|result| result.status == OperationResultStatus::Skipped)
        .count();

    BatchInvokeResponse {
        status: batch_status(aborted, completed, failed),
        completed,
        failed,
        skipped,
        results,
        total_duration_ms: elapsed_millis(started_at),
        schedule_report,
    }
}

async fn execute_batch_operation(
    state: Arc<AppState>,
    operation: HttpBatchOperation,
    principal_override: Option<Arc<str>>,
) -> OperationResult {
    let started_at = Instant::now();
    let request = operation.request;
    let connector_id = request.connector_id.clone();
    let operation_name = request.operation.to_string();
    let idempotency_key = request.idempotency_key.clone();
    let zone_id = request.zone_id.clone();

    if let Err(err) = request.validate_idempotency_key() {
        return OperationResult {
            id: operation.id,
            status: OperationResultStatus::Error,
            output: None,
            error: Some(batch_error_from_host_error(HostError::InvalidFilter(
                format!("invalid invoke request: {err}"),
            ))),
            duration_ms: elapsed_millis(started_at),
        };
    }

    let verified =
        match evaluate_verified_live_preflight(&state, &request, principal_override.as_deref())
            .await
        {
            Ok(verified) => verified,
            Err(error) => {
                return OperationResult {
                    id: operation.id,
                    status: OperationResultStatus::Error,
                    output: None,
                    error: Some(batch_error_from_host_error(error)),
                    duration_ms: elapsed_millis(started_at),
                };
            }
        };

    match state
        .registry
        .invoke_with_execution_plan(&state, request, verified.per_invocation_plan)
        .await
    {
        Ok(response) => {
            let duration_ms = elapsed_millis(started_at);
            record_invoke_budget_usage(
                state.budget.as_ref(),
                Some(&zone_id),
                &connector_id,
                &operation_name,
                Some(&response),
            )
            .await;
            record_invoke_receipt_summary(
                state.lifecycle.as_ref(),
                connector_id.as_str(),
                &operation_name,
                idempotency_key,
                &response,
                duration_ms,
            )
            .await;
            OperationResult {
                id: operation.id,
                status: OperationResultStatus::Success,
                output: Some(
                    serde_json::to_value(&response)
                        .unwrap_or_else(|_| json!({ "status": "serialization_error" })),
                ),
                error: None,
                duration_ms,
            }
        }
        Err(err) => {
            record_invoke_budget_usage(
                state.budget.as_ref(),
                Some(&zone_id),
                &connector_id,
                &operation_name,
                None,
            )
            .await;
            OperationResult {
                id: operation.id,
                status: OperationResultStatus::Error,
                output: None,
                error: Some(batch_error_from_host_error(err)),
                duration_ms: elapsed_millis(started_at),
            }
        }
    }
}

async fn batch_invoke_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<HttpBatchInvokeRequest>,
) -> Result<Json<BatchInvokeResponse>, (StatusCode, String)> {
    let started_at = Instant::now();
    let asserted_principal = extract_principal_header(&headers).map(Arc::<str>::from);
    tracing::debug!(
        event = "batch_invoke_request",
        operation_count = request.operations.len(),
        max_parallelism = request.options.max_parallelism,
        stop_on_first_error = request.options.stop_on_first_error,
        timeout_ms = request.options.timeout_ms,
        asserted_principal = asserted_principal.as_deref(),
        "processing batch invoke request"
    );

    let executor = BatchExecutor::new();
    let planning_request = request.planning_request();
    let (plan, schedule_report) = executor
        .plan_with_schedule_report(&planning_request)
        .map_err(map_host_error)?;
    let schedule_report = matches!(request.options.scheduler.mode, BatchSchedulerMode::Adaptive)
        .then_some(schedule_report);
    let timeout = Duration::from_millis(request.options.timeout_ms);
    let max_parallelism = usize::try_from(request.options.max_parallelism)
        .unwrap_or(usize::MAX)
        .max(1);

    let operation_map: HashMap<String, HttpBatchOperation> = request
        .operations
        .iter()
        .cloned()
        .map(|operation| (operation.id.clone(), operation))
        .collect();
    let mut results_map: HashMap<String, OperationResult> =
        HashMap::with_capacity(request.operations.len());
    let mut aborted = false;

    for tier in &plan.tiers {
        if aborted {
            for operation_id in &tier.operation_ids {
                results_map.insert(
                    operation_id.clone(),
                    skipped_batch_result(operation_id.clone(), None),
                );
            }
            continue;
        }

        for chunk in tier.operation_ids.chunks(max_parallelism) {
            if started_at.elapsed() >= timeout {
                aborted = true;
                let timeout_error = batch_timeout_error();
                for operation_id in chunk {
                    results_map.insert(
                        operation_id.clone(),
                        skipped_batch_result(operation_id.clone(), Some(timeout_error.clone())),
                    );
                }
                continue;
            }

            // stop_on_first_error tripped in an earlier chunk of this tier:
            // short-circuit the remaining chunks instead of executing them
            // (the tier-level check above only catches subsequent tiers).
            if aborted {
                for operation_id in chunk {
                    results_map.insert(
                        operation_id.clone(),
                        skipped_batch_result(operation_id.clone(), None),
                    );
                }
                continue;
            }

            let mut ready = Vec::new();
            for operation_id in chunk {
                let operation = operation_map
                    .get(operation_id.as_str())
                    .expect("planned batch operation must exist");
                if dependency_failed_in_batch(operation, &results_map) {
                    results_map.insert(
                        operation_id.clone(),
                        skipped_batch_result(operation_id.clone(), Some(dependency_failed_error())),
                    );
                } else {
                    ready.push(operation.clone());
                }
            }

            if ready.is_empty() {
                continue;
            }

            let chunk_results = join_all(ready.into_iter().map(|operation| {
                execute_batch_operation(Arc::clone(&state), operation, asserted_principal.clone())
            }))
            .await;

            let chunk_failed = chunk_results
                .iter()
                .any(|result| result.status == OperationResultStatus::Error);
            for result in chunk_results {
                results_map.insert(result.id.clone(), result);
            }
            if request.options.stop_on_first_error && chunk_failed {
                aborted = true;
            }
        }
    }

    let response =
        build_batch_response(&request, results_map, aborted, started_at, schedule_report);
    tracing::info!(
        event = "batch_invoke_response",
        operation_count = request.operations.len(),
        completed = response.completed,
        failed = response.failed,
        skipped = response.skipped,
        status = ?response.status,
        duration_ms = started_at.elapsed().as_millis() as u64,
        "batch invoke request complete"
    );
    Ok(Json(response))
}

async fn supply_chain_verify_handler(
    State(state): State<Arc<AppState>>,
    Json(request): Json<SupplyChainVerifyRequest>,
) -> Result<Json<GateOutcome>, (StatusCode, String)> {
    let SupplyChainVerifyRequest {
        connector_id,
        version,
        artifact_digest,
        attestation,
        sbom,
    } = request;
    let connector_id = parse_connector_id(&connector_id)?;
    let version = version.to_string();
    let attestation_present = attestation.is_some();
    let sbom_present = sbom.is_some();
    let started_at = Instant::now();

    tracing::debug!(
        event = "supply_chain_verify_request",
        connector_id = %connector_id,
        version = %version,
        artifact_digest = %artifact_digest,
        attestation_present,
        sbom_present,
        "processing supply-chain verification request"
    );

    match state.supply_chain.verify(
        &connector_id,
        &version,
        &artifact_digest,
        attestation.as_ref(),
        sbom.as_ref(),
    ) {
        Ok(outcome) => {
            tracing::info!(
                event = "supply_chain_verify_response",
                connector_id = %connector_id,
                version = %version,
                allowed = outcome.allowed,
                cached = outcome.cached,
                reason_code = %outcome.audit_event.reason_code,
                evidence_digest = %outcome.audit_event.evidence_digest,
                duration_ms = started_at.elapsed().as_millis() as u64,
                "supply-chain verification request complete"
            );
            Ok(Json(outcome))
        }
        Err(err) => {
            tracing::warn!(
                event = "supply_chain_verify_error",
                connector_id = %connector_id,
                version = %version,
                error = %err,
                duration_ms = started_at.elapsed().as_millis() as u64,
                "supply-chain verification request failed"
            );
            Err(map_host_error(err))
        }
    }
}

async fn health_handler(
    State(state): State<Arc<AppState>>,
) -> Result<Json<HostHealthResponse>, (StatusCode, String)> {
    let started_at = Instant::now();
    if let Some(error) = state.registry.first_zone_envelope_error().await {
        tracing::warn!(
            event = "health_zone_envelope_required",
            error = %error,
            "rejecting host health before connector health RPC"
        );
        return Err(map_host_error(error));
    }
    let summaries = state.registry.list().await;
    let mut connectors = HashMap::with_capacity(summaries.len());
    let mut status = HostHealthStatus::Healthy;

    for summary in summaries {
        let connector_id = summary.id;
        let connector_health = summary.health;
        match &connector_health {
            ConnectorHealth::Healthy => {}
            ConnectorHealth::Degraded { .. } => {
                if !matches!(status, HostHealthStatus::Unhealthy) {
                    status = HostHealthStatus::Degraded;
                }
            }
            ConnectorHealth::Unavailable { .. } => {
                status = HostHealthStatus::Unhealthy;
            }
        }
        connectors.insert(connector_id, connector_health);
    }

    let response = HostHealthResponse {
        status,
        connectors,
        uptime_seconds: state.started_at.elapsed().as_secs(),
        active_connections: 0,
        timestamp: chrono::Utc::now(),
    };
    tracing::debug!(
        event = "health_response",
        status = ?response.status,
        connector_count = response.connectors.len(),
        duration_ms = started_at.elapsed().as_millis() as u64,
        "health request complete"
    );
    Ok(Json(response))
}

fn host_telemetry_otlp_readiness_message(status: &str) -> &'static str {
    match status {
        "ready" => "OTLP export is configured and supported by this host build",
        "unavailable" => "OTLP export is configured but this host build lacks exporter support",
        "fail" => "OTLP export configuration is invalid or incomplete",
        "disabled" => "OTLP export is disabled by configuration",
        _ => "OTLP readiness status is unknown",
    }
}

async fn host_telemetry_otlp_readiness_handler(State(state): State<Arc<AppState>>) -> Json<Value> {
    let readiness = otlp_readiness(&state.telemetry_config);
    let status = readiness.status;
    Json(json!({
        "status": status,
        "source": "host-admin-api",
        "message": host_telemetry_otlp_readiness_message(status),
        "readiness": readiness,
    }))
}

async fn ensure_registered_connector(
    state: &AppState,
    connector_id: &ConnectorId,
) -> Result<(), (StatusCode, String)> {
    if state.registry.get(connector_id).await.is_some() {
        Ok(())
    } else {
        Err(map_host_error(HostError::ConnectorNotFound(
            connector_id.to_string(),
        )))
    }
}

async fn rollout_pin_handler(
    State(state): State<Arc<AppState>>,
    Path(connector_id): Path<String>,
    Json(request): Json<PinRequest>,
) -> Result<Json<PinStateResponse>, (StatusCode, String)> {
    let connector_id = parse_connector_id(&connector_id)?;
    ensure_registered_connector(&state, &connector_id).await?;
    let started_at = Instant::now();
    tracing::debug!(
        event = "rollout_pin_request",
        connector_id = %connector_id,
        version = %request.version,
        "processing rollout pin request"
    );
    state
        .lifecycle
        .pin(&connector_id, request.version.clone())
        .await
        .map_err(|e| map_host_error(map_lifecycle_host_error(e)))?;
    let response = pin_state_response(&state.lifecycle, &connector_id).await;
    tracing::info!(
        event = "rollout_pin_response",
        connector_id = %connector_id,
        pinned = response.pinned,
        version = ?response.version,
        duration_ms = started_at.elapsed().as_millis() as u64,
        "rollout pin request complete"
    );
    Ok(Json(response))
}

