    #[cfg(target_os = "linux")]
    #[test]
    fn n8n_child_external_provenance_accepts_only_canonical_fixed_messages() {
        let cases = [
            (
                json!({
                    "message": "External service error: n8n - n8n provider returned HTTP 503",
                    "details": {"service": "n8n", "status_code": 503}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::Provider5xx),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy rejected mediated request",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::HostProxyRejected),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel failed",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedChannel),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel request id exhausted",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedRequestId),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel was unavailable or poisoned",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedPoisoned),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel write failed",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedWrite),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel read failed",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedRead),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel reached EOF",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedReadEof),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel returned an invalid frame",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedFrame),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel returned invalid JSON",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedJson),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel returned an invalid response",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedValidation),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy inherited channel timed out",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressInheritedTimeout),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy transport failed",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressTransport),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy request exceeded the configured limit",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressRequestTooLarge),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy request envelope was malformed",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressRequestMalformed),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy response exceeded the configured limit",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressResponseTooLarge),
            ),
            (
                json!({
                    "message": "External service error: n8n - host egress proxy returned a malformed response envelope",
                    "details": {"service": "n8n", "status_code": 502}
                }),
                Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorEgressResponseMalformed),
            ),
        ];
        for (error, expected) in cases {
            let diagnostic = child_external_provenance_diagnostic(&error);
            assert_eq!(diagnostic, expected);
            assert!(
                !diagnostic
                    .expect("canonical message should have a diagnostic")
                    .label()
                    .contains("PRIVATE-CONTENT-CANARY")
            );
        }

        let mcp_bridge = json!({
            "message": "External service error: mcp-bridge - MCP initialize response was malformed",
            "details": {"service": "mcp-bridge", "status_code": 502}
        });
        assert_eq!(
            child_external_provenance_diagnostic(&mcp_bridge),
            Some(N8nRunOnceExternalProvenanceDiagnostic::ConnectorMcpInitialize)
        );

        for error in [
            json!({
                "message": "External service error: n8n - n8n provider returned HTTP 503 PRIVATE-CONTENT-CANARY",
                "details": {"service": "n8n", "status_code": 503}
            }),
            json!({
                "message": "External service error: n8n - n8n provider returned HTTP 502",
                "details": {"service": "other", "status_code": 502}
            }),
            json!({
                "message": "External service error: n8n - n8n provider returned HTTP 503",
                "details": {"service": "n8n", "status_code": 502}
            }),
            json!({
                "message": "External service error: n8n - host egress proxy inherited channel failed",
                "details": {"service": "n8n", "status_code": 499}
            }),
        ] {
            assert_eq!(child_external_provenance_diagnostic(&error), None);
        }
    }

    #[test]
    fn connector_stderr_metadata_retains_only_size_and_flags() {
        let canary = b"OAUTH-TOKEN-AND-PRIVATE-CONTENT-CANARY";
        let metadata = connector_stderr_metadata(canary, true);
        assert_eq!(metadata, (true, canary.len() as u64, true));
        assert_eq!(connector_stderr_metadata(b"", false), (false, 0, false));

        let exact = vec![b'x'; CONNECTOR_RPC_MAX_STDERR_LINE_BYTES];
        assert_eq!(
            connector_stderr_metadata(&exact, false),
            (
                true,
                u64::try_from(CONNECTOR_RPC_MAX_STDERR_LINE_BYTES).unwrap_or(u64::MAX),
                false,
            )
        );
        // The stderr reader retains exactly the bounded prefix and marks the
        // first additional byte as truncated without buffering its content.
        assert_eq!(
            connector_stderr_metadata(&exact, true),
            (
                true,
                u64::try_from(CONNECTOR_RPC_MAX_STDERR_LINE_BYTES).unwrap_or(u64::MAX),
                true,
            )
        );
    }

