    fn dispatcher_registry_with_connector(
        connector_id: &'static str,
        connector: Arc<SubprocessConnector>,
        config: ConnectorConfig,
    ) -> Arc<SubprocessRegistry> {
        let connector_key = ConnectorId::from_static(connector_id);
        let mut connectors = HashMap::new();
        connectors.insert(
            connector_key,
            RegistryEntry {
                config,
                connector: ConnectorRuntime::Native(connector),
                manifest_constraints: ManifestOperationConstraintCatalog::default(),
            },
        );
        Arc::new(SubprocessRegistry {
            state: Arc::new(RwLock::new(RegistryState {
                connectors,
                generation: 1,
            })),
            resilience: Arc::new(ResilienceLayer::default()),
            version: Arc::new(AtomicU64::new(1)),
            capability_verifying_key: None,
            rate_limiters: Arc::new(HostRateLimiterStore::default()),
        })
    }

    fn dispatcher_registry_with_connectors(
        entries: Vec<(&'static str, Arc<SubprocessConnector>, ConnectorConfig)>,
    ) -> Arc<SubprocessRegistry> {
        let mut connectors = HashMap::new();
        for (connector_id, connector, config) in entries {
            connectors.insert(
                ConnectorId::from_static(connector_id),
                RegistryEntry {
                    config,
                    connector: ConnectorRuntime::Native(connector),
                    manifest_constraints: ManifestOperationConstraintCatalog::default(),
                },
            );
        }
        Arc::new(SubprocessRegistry {
            state: Arc::new(RwLock::new(RegistryState {
                connectors,
                generation: 1,
            })),
            resilience: Arc::new(ResilienceLayer::default()),
            version: Arc::new(AtomicU64::new(1)),
            capability_verifying_key: None,
            rate_limiters: Arc::new(HostRateLimiterStore::default()),
        })
    }

