    async fn e99o6_gmail_refresh_server(
        responses: Vec<(&'static str, &'static str)>,
    ) -> (SocketAddr, JoinHandle<Vec<String>>) {
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind e99o6 Gmail loopback");
        let addr = listener.local_addr().expect("listener local addr");
        let task = task::spawn(async move {
            let mut observed = Vec::new();

            for (status, body) in responses {
                let (mut stream, _) = listener.accept().await.expect("accept Gmail egress");
                let mut request_bytes = Vec::new();
                let mut buf = [0_u8; 1024];
                loop {
                    let read = stream.read(&mut buf).await.expect("read Gmail request");
                    if read == 0 {
                        break;
                    }
                    request_bytes.extend_from_slice(&buf[..read]);
                    if request_bytes.windows(4).any(|window| window == b"\r\n\r\n") {
                        break;
                    }
                }
                observed.push(String::from_utf8_lossy(&request_bytes).into_owned());
                let response = format!(
                    "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                stream
                    .write_all(response.as_bytes())
                    .await
                    .expect("write Gmail response");
                stream.flush().await.expect("flush Gmail response");
            }

            observed
        });
        (addr, task)
    }

    async fn d9us6_one_shot_tcp_server(
        observed_bytes: Arc<StdMutex<Vec<u8>>>,
    ) -> (SocketAddr, JoinHandle<()>) {
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind d9us6 TCP loopback");
        let addr = listener.local_addr().expect("listener local addr");
        let task = task::spawn(async move {
            let (mut stream, _) = listener.accept().await.expect("accept TCP egress");
            let mut buf = [0_u8; 64];
            let read = stream.read(&mut buf).await.expect("read TCP request");
            observed_bytes
                .lock()
                .expect("observed bytes lock")
                .extend_from_slice(&buf[..read]);
            stream.write_all(b"PONG").await.expect("write TCP response");
            stream.flush().await.expect("flush TCP response");
        });
        (addr, task)
    }

