        let response = b"HTTP/1.1 302 Found\r\nLocation: /after\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".to_vec();
        let (addr, server_task) = br_4kw5f_9_6_1_one_shot_http_response(response).await;
