    #[test]
    fn run_once_response_encoder_marks_success_and_redacts_failure() {
        let success: HostResult<InvokeResponse> = Ok(invoke_response_with_metrics(Vec::new()));
        let (encoded, failed) = encode_run_once_response(&success);
        assert!(!failed);
        assert!(encoded.contains("\"type\":\"response\""));

        let failure: HostResult<InvokeResponse> =
            Err(HostError::Internal("PRIVATE-RUN-ONCE-CANARY".to_string()));
        let (encoded, failed) = encode_run_once_response(&failure);
        assert!(failed);
        assert!(encoded.contains("\"code\":\"internal\""));
        assert!(!encoded.contains("PRIVATE-RUN-ONCE-CANARY"));
    }

    #[test]
    fn run_once_response_encoder_exposes_only_allowlisted_n8n_failure_stage() {
        let cases = [
            (N8nRunOnceFailureStage::Input, "n8n_input_failed"),
            (N8nRunOnceFailureStage::Config, "n8n_config_failed"),
            (N8nRunOnceFailureStage::Plan, "n8n_plan_failed"),
            (N8nRunOnceFailureStage::Credential, "n8n_credential_failed"),
            (N8nRunOnceFailureStage::Policy, "n8n_policy_failed"),
            (
                N8nRunOnceFailureStage::RuntimeState,
                "n8n_runtime_state_failed",
            ),
            (N8nRunOnceFailureStage::Manifest, "n8n_manifest_failed"),
            (N8nRunOnceFailureStage::Capability, "n8n_capability_failed"),
            (N8nRunOnceFailureStage::Invoke, "n8n_invoke_failed"),
        ];
        for (stage, code) in cases {
            let failure: HostResult<InvokeResponse> = Err(n8n_run_once_stage_error(stage));
            let (encoded, failed) = encode_run_once_response(&failure);
            assert!(failed);
            assert_eq!(
                serde_json::from_str::<Value>(&encoded).expect("stage failure JSON"),
                json!({"type":"error","error":{"code":code}})
            );
            assert!(!encoded.contains("n8n-run-once-stage"));
        }
    }

    #[test]
    fn n8n_run_once_redacts_connector_error_responses_on_the_success_exit_path() {
        let private_message = "PRIVATE-N8N-PROVIDER-ERROR-CANARY";
        let provider_failure = InvokeResponse::error(
            RequestId::random(),
            fcp_core::FcpError::External {
                service: "PRIVATE-N8N-PROVIDER".to_string(),
                message: private_message.to_string(),
                status_code: Some(500),
                retryable: false,
                retry_after: None,
            },
        );
        let failure = accept_n8n_run_once_invoke_response(provider_failure)
            .expect_err("connector error response must become a fixed host failure");
        let (encoded, failed) = encode_run_once_response(&Err(failure));
        assert!(failed);
        assert_eq!(
            serde_json::from_str::<Value>(&encoded).expect("invoke failure JSON"),
            json!({"type":"error","error":{"code":"n8n_invoke_failed"}})
        );
        assert!(!encoded.contains(private_message));
        assert!(!encoded.contains("PRIVATE-N8N-PROVIDER"));

        let mut malformed_success = invoke_response_with_metrics(Vec::new());
        malformed_success.error = Some(fcp_core::FcpError::External {
            service: "PRIVATE-N8N-PROVIDER".to_string(),
            message: private_message.to_string(),
            status_code: None,
            retryable: false,
            retry_after: None,
        });
        assert!(accept_n8n_run_once_invoke_response(malformed_success).is_err());
    }

    #[test]
    fn n8n_run_once_invoke_classification_is_bounded_and_redaction_safe() {
        assert_eq!(
            n8n_run_once_dispatch_diagnostic(StatusCode::BAD_REQUEST),
            N8nRunOnceInvokeDiagnostic::Dispatch4xx
        );
        assert_eq!(
            n8n_run_once_dispatch_diagnostic(StatusCode::BAD_GATEWAY),
            N8nRunOnceInvokeDiagnostic::Dispatch5xx
        );
        assert_eq!(
            n8n_run_once_dispatch_diagnostic(StatusCode::TEMPORARY_REDIRECT),
            N8nRunOnceInvokeDiagnostic::DispatchOther
        );

        let cases = [
            (None, N8nRunOnceInvokeDiagnostic::ResponseExternalUnknown),
            (Some(401), N8nRunOnceInvokeDiagnostic::ResponseExternal4xx),
            (Some(403), N8nRunOnceInvokeDiagnostic::ResponseExternal4xx),
            (Some(404), N8nRunOnceInvokeDiagnostic::ResponseExternal4xx),
            (Some(429), N8nRunOnceInvokeDiagnostic::ResponseExternal4xx),
            (Some(418), N8nRunOnceInvokeDiagnostic::ResponseExternal4xx),
            (Some(502), N8nRunOnceInvokeDiagnostic::ResponseExternal5xx),
            (Some(503), N8nRunOnceInvokeDiagnostic::ResponseExternal5xx),
            (Some(302), N8nRunOnceInvokeDiagnostic::ResponseExternalOther),
        ];
        for (status_code, expected) in cases {
            let error = FcpError::External {
                service: "PRIVATE-SERVICE-CANARY".to_string(),
                message: "PRIVATE-MESSAGE-CANARY".to_string(),
                status_code,
                retryable: false,
                retry_after: None,
            };
            let diagnostic = n8n_run_once_response_diagnostic(&error);
            assert_eq!(diagnostic, expected);
            assert!(!diagnostic.label().contains("PRIVATE"));
        }

        let rate_limited = FcpError::RateLimited {
            retry_after_ms: 1,
            violation: None,
        };
        assert_eq!(
            n8n_run_once_response_diagnostic(&rate_limited),
            N8nRunOnceInvokeDiagnostic::ResponseRateLimited
        );
    }

