    #[test]
    fn n8n_draft_mutation_digest_matches_connector_golden_vectors() {
        let credential_one = n8n_run_once_mutation_digest(
            "n8n.workflows.create_draft",
            &n8n_mutation_digest_golden_input("credential-1"),
        )
        .expect("credential-1 mutation digest");
        let credential_two = n8n_run_once_mutation_digest(
            "n8n.workflows.create_draft",
            &n8n_mutation_digest_golden_input("credential-2"),
        )
        .expect("credential-2 mutation digest");

        assert_eq!(
            (credential_one.as_str(), credential_two.as_str()),
            (
                "blake3-256:d34cb28e2a1b6d54e559a6e2b25219b3ffc825daad1582e3a2fbde1ac69c80ad",
                "blake3-256:c1f951ef0958caacd4526da532b481f63eb2620b4fd1f6719a150a5f16997e64"
            )
        );
        assert_ne!(credential_one, credential_two);
    }

    #[test]
    fn n8n_draft_settings_canonicalization_is_fail_closed() {
        let base = json!({
            "name": "Draft",
            "project_id": "project-1",
            "graph": {"nodes": [], "connections": {}},
            "guard": {
                "approvalRef": "approval",
                "idempotencyKey": "33333333-4444-4555-8666-777777777777",
                "precondition": {}
            }
        });
        assert_eq!(
            canonical_n8n_draft_settings("n8n.workflows.create_draft", &base)
                .expect("omitted settings"),
            json!({"availableInMCP": false})
        );

        for setting in [
            json!(null),
            json!({"executionOrder": "v1"}),
            json!({"availableInMCP": false}),
        ] {
            let mut input = base.clone();
            input["graph"]["settings"] = setting;
            assert!(validate_n8n_draft_input("n8n.workflows.create_draft", &input).is_ok());
            assert_eq!(
                canonical_n8n_draft_settings("n8n.workflows.create_draft", &input)
                    .expect("accepted settings")
                    .get("availableInMCP"),
                Some(&Value::Bool(false))
            );
        }

        for setting in [json!(true), json!("true"), json!({"availableInMCP": null})] {
            let mut input = base.clone();
            input["graph"]["settings"] = setting;
            assert!(validate_n8n_draft_input("n8n.workflows.create_draft", &input).is_err());
        }
        let mut update = base.clone();
        update["id"] = json!("workflow-1");
        update["guard"]["precondition"] = json!({
            "versionId": "draft-v1",
            "activeVersionId": null,
            "active": false,
            "isArchived": false,
            "stateDigest": format!("blake3-256:{}", "a".repeat(64))
        });
        assert_eq!(
            canonical_n8n_draft_settings("n8n.workflows.update_draft", &update)
                .expect("omitted update settings"),
            json!({})
        );
        update["graph"]["settings"] = json!({"executionOrder": "v1"});
        assert!(canonical_n8n_draft_settings("n8n.workflows.update_draft", &update).is_ok());
        update["graph"]["settings"] = json!({"availableInMCP": false});
        assert!(canonical_n8n_draft_settings("n8n.workflows.update_draft", &update).is_err());

        let mut non_object = base;
        non_object["graph"]["settings"] = json!(true);
        assert!(validate_n8n_draft_input("n8n.workflows.create_draft", &non_object).is_err());
    }

    #[test]
    fn n8n_workflow_lifecycle_plan_is_strictly_bound_and_redacted() {
        let config = run_once_n8n_draft_test_config();
        let state_digest = format!("blake3-256:{}", "a".repeat(64));
        let input = N8nReadOnlyRunOnceInput {
            schema: N8N_READ_ONLY_RUN_ONCE_SCHEMA.to_string(),
            server_id: N8nReadOnlyServerId::Eec,
            operation: "n8n.workflows.lifecycle".to_string(),
            zone_id: ZoneId::work().to_string(),
            resource_uri: "fwc-n8n://eec/workflows/workflow%2D1".to_string(),
            input: json!({
                "id": "workflow-1",
                "action": "publish",
                "versionId": "version-1",
                "guard": {
                    "approvalRef": "lifecycle-approval",
                    "idempotencyKey": "00000000-0000-4000-8000-000000000003",
                    "precondition": {
                        "versionId": "draft-v1",
                        "activeVersionId": null,
                        "active": false,
                        "isArchived": false,
                        "stateDigest": state_digest
                    }
                }
            }),
            approval_token: None,
            deadline_ms: None,
            correlation_id: Some("11111111-2222-4333-8444-555555555555".to_string()),
        };
        let plan = build_n8n_read_only_run_once_plan(input.clone(), &config)
            .expect("lifecycle input must be admitted");
        assert_eq!(plan.resource_uri, "fwc-n8n://eec/workflows/workflow%2D1");
        let (material, graph_digest, mutation_digest) =
            n8n_run_once_approval_material(&plan).expect("lifecycle approval material");
        assert!(graph_digest.is_empty());
        assert!(mutation_digest.starts_with("blake3-256:"));
        let material_text = material.to_string();
        for private_value in [
            "lifecycle-approval",
            "00000000-0000-4000-8000-000000000003",
            "workflow-1",
        ] {
            assert!(!material_text.contains(private_value));
        }
        assert!(material.get("workflow_id_digest").is_some());
        assert!(material.get("idempotency_key_hash").is_some());

        let mut unsupported_action = input.clone();
        unsupported_action.input["action"] = json!("activate");
        assert!(build_n8n_read_only_run_once_plan(unsupported_action, &config).is_err());

        let mut missing_lifecycle_pointer = input;
        missing_lifecycle_pointer.input["guard"]["precondition"]
            .as_object_mut()
            .expect("precondition object")
            .remove("activeVersionId");
        assert!(build_n8n_read_only_run_once_plan(missing_lifecycle_pointer, &config).is_err());
    }

    #[test]
    fn n8n_draft_approval_binds_exact_request_input_hash() {
        let config = run_once_n8n_draft_test_config();
        let plan = build_n8n_read_only_run_once_plan(
            n8n_draft_test_input(
                "n8n.workflows.update_draft",
                "33333333-4444-4555-8666-777777777777",
            ),
            &config,
        )
        .expect("typed update plan");
        let signing_key = fcp_crypto::ed25519::Ed25519SigningKey::generate();
        let token = signed_external_approval(
            "chat-draft-approval",
            "fcp.n8n",
            plan.operation.as_str(),
            n8n_run_once_binding_hash(
                plan.server_id,
                &plan.resource_uri,
                plan.operation.as_str(),
                &plan.input,
            )
            .expect("request binding hash"),
            Vec::new(),
            ZoneId::work(),
            &signing_key,
        );
        let ApprovalScope::Execution(scope) = &token.scope else {
            panic!("draft approval must use execution scope");
        };
        assert!(scope.input_constraints.is_empty());
        assert_eq!(
            scope.input_hash,
            Some(
                n8n_run_once_binding_hash(
                    plan.server_id,
                    &plan.resource_uri,
                    plan.operation.as_str(),
                    &plan.input,
                )
                .unwrap(),
            )
        );
        let mut changed_input = plan.input.clone();
        changed_input["graph"]["nodes"] = json!([{"id": "changed"}]);
        assert_ne!(
            scope.input_hash,
            Some(
                n8n_run_once_binding_hash(
                    plan.server_id,
                    &plan.resource_uri,
                    plan.operation.as_str(),
                    &changed_input,
                )
                .unwrap(),
            )
        );
        validate_external_n8n_approval(
            Some(&token),
            "chat-draft-approval",
            "fcp.n8n",
            plan.operation.as_str(),
            &ZoneId::work(),
            scope.input_hash.expect("input hash"),
            &[],
            Some(&signing_key.verifying_key()),
        )
        .expect("external owner approval verifies");
    }

    #[test]
    fn n8n_external_approval_rejects_missing_invalid_and_mismatched_before_dispatch() {
        let config = run_once_n8n_draft_test_config();
        let plan = build_n8n_read_only_run_once_plan(
            n8n_draft_test_input(
                "n8n.workflows.update_draft",
                "77777777-8888-4999-8aaa-bbbbbbbbbbbb",
            ),
            &config,
        )
        .expect("typed update plan");
        let signing_key = fcp_crypto::ed25519::Ed25519SigningKey::generate();
        let binding_hash = n8n_run_once_binding_hash(
            plan.server_id,
            &plan.resource_uri,
            plan.operation.as_str(),
            &plan.input,
        )
        .expect("request binding hash");
        let token = signed_external_approval(
            "chat-approval-2",
            "fcp.n8n",
            plan.operation.as_str(),
            binding_hash,
            Vec::new(),
            ZoneId::work(),
            &signing_key,
        );

        assert!(
            validate_external_n8n_approval(
                None,
                "chat-approval-2",
                "fcp.n8n",
                plan.operation.as_str(),
                &ZoneId::work(),
                binding_hash,
                &[],
                Some(&signing_key.verifying_key()),
            )
            .is_err()
        );

        let wrong_key = fcp_crypto::ed25519::Ed25519SigningKey::generate();
        assert!(
            validate_external_n8n_approval(
                Some(&token),
                "chat-approval-2",
                "fcp.n8n",
                plan.operation.as_str(),
                &ZoneId::work(),
                binding_hash,
                &[],
                Some(&wrong_key.verifying_key()),
            )
            .is_err()
        );

        let mismatched_hash = n8n_run_once_binding_hash(
            plan.server_id,
            "fwc-n8n://eec/workflows/other",
            plan.operation.as_str(),
            &plan.input,
        )
        .expect("mismatched binding hash");
        assert!(
            validate_external_n8n_approval(
                Some(&token),
                "chat-approval-2",
                "fcp.n8n",
                plan.operation.as_str(),
                &ZoneId::work(),
                mismatched_hash,
                &[],
                Some(&signing_key.verifying_key()),
            )
            .is_err()
        );
    }

    #[test]
    fn n8n_draft_approval_allows_only_the_exact_policy_input() {
        let config = run_once_n8n_draft_test_config();
        let plan = build_n8n_read_only_run_once_plan(
            n8n_draft_test_input(
                "n8n.workflows.create_draft",
                "12121212-3434-4567-8abc-def012345678",
            ),
            &config,
        )
        .expect("typed create plan");
        let approval_key = fcp_crypto::ed25519::Ed25519SigningKey::generate();
        let approval = signed_external_approval(
            "chat-draft-approval",
            "fcp.n8n",
            plan.operation.as_str(),
            n8n_run_once_binding_hash(
                plan.server_id,
                &plan.resource_uri,
                plan.operation.as_str(),
                &plan.input,
            )
            .expect("request binding hash"),
            Vec::new(),
            ZoneId::work(),
            &approval_key,
        );
        let capability_key = fcp_crypto::ed25519::Ed25519SigningKey::generate();
        let (request, _) = build_n8n_read_only_invoke_request(
            plan,
            test_capability_token(
                &capability_key,
                "n8n.workflows.write",
                "n8n.workflows.create_draft",
                ZoneId::work().as_str(),
            ),
            Some(approval),
        );
        let exact_hash = n8n_run_once_binding_hash(
            N8nReadOnlyServerId::Eec,
            "fwc-n8n://eec/projects/project%2D1",
            request.operation.as_str(),
            &request.input,
        )
        .expect("exact request binding hash");
        let exact = simulate_policy_decision(&PolicySimulationInput {
            zone_policy: host_runtime_policy(ZoneId::work()),
            invoke_request: request.clone(),
            transport: TransportMode::Lan,
            checkpoint_fresh: true,
            revocation_fresh: true,
            execution_approval_required: true,
            sanitizer_receipts: Vec::new(),
            related_object_ids: Vec::new(),
            request_object_id: None,
            request_input_hash: Some(exact_hash),
            safety_tier: SafetyTier::Risky,
            principal: Some("agent:fwc-n8n".to_string()),
            capability_id: Some("n8n.workflows.write".to_string()),
            provenance_record: None,
            now_ms: Some(n8n_run_once_now_ms()),
            posture_attestation: None,
        })
        .expect("exact policy simulation");
        assert_eq!(exact.decision, Decision::Allow);

        let mut changed_request = request;
        changed_request.input["name"] = json!("Changed after approval");
        let changed_hash = n8n_run_once_binding_hash(
            N8nReadOnlyServerId::Eec,
            "fwc-n8n://eec/projects/project%2D1",
            changed_request.operation.as_str(),
            &changed_request.input,
        )
        .expect("changed request binding hash");
        let changed = simulate_policy_decision(&PolicySimulationInput {
            zone_policy: host_runtime_policy(ZoneId::work()),
            invoke_request: changed_request,
            transport: TransportMode::Lan,
            checkpoint_fresh: true,
            revocation_fresh: true,
            execution_approval_required: true,
            sanitizer_receipts: Vec::new(),
            related_object_ids: Vec::new(),
            request_object_id: None,
            request_input_hash: Some(changed_hash),
            safety_tier: SafetyTier::Risky,
            principal: Some("agent:fwc-n8n".to_string()),
            capability_id: Some("n8n.workflows.write".to_string()),
            provenance_record: None,
            now_ms: Some(n8n_run_once_now_ms()),
            posture_attestation: None,
        })
        .expect("changed policy simulation");
        assert_eq!(changed.decision, Decision::Deny);
    }

