    #[fcp_async_core::runtime::test]
    async fn bluebubbles_ingress_route_accept_loop_stops_on_shutdown() {
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind host ingress listener");
        let addr = listener.local_addr().expect("listener should expose addr");
        let app = axum::Router::new().route(
            BLUEBUBBLES_INGRESS_ROUTE,
            post(|| async {
                (
                    StatusCode::ACCEPTED,
                    Json(json!({
                        "accepted": true,
                        "route": BLUEBUBBLES_INGRESS_ROUTE,
                        "source": "fcp_host_accept_loop"
                    })),
                )
            }),
        );
        let (shutdown_tx, shutdown_rx) = fcp_async_core::channel::watch::channel(false);
        let server = task::spawn(async move { serve_tcp(listener, app, shutdown_rx).await });

        let mut stream = fcp_async_core::net::TcpStream::connect(addr)
            .await
            .expect("connect to host ingress listener");
        let request = format!(
            "POST {BLUEBUBBLES_INGRESS_ROUTE} HTTP/1.1\r\n\
             Host: {addr}\r\n\
             Content-Type: application/json\r\n\
             Content-Length: 2\r\n\
             Connection: close\r\n\
             \r\n\
             {{}}"
        );
        stream
            .write_all(request.as_bytes())
            .await
            .expect("write ingress request");
        stream.flush().await.expect("flush ingress request");

        let mut response = Vec::new();
        stream
            .read_to_end(&mut response)
            .await
            .expect("read ingress response");
        let response = String::from_utf8(response).expect("http response should be utf-8");
        assert!(
            response.contains("202 Accepted"),
            "expected route response over host accept loop, got {response}"
        );
        assert!(
            response.contains("fcp_host_accept_loop"),
            "expected route body from host accept-loop app, got {response}"
        );
        let _ = stream.shutdown(std::net::Shutdown::Both);

        shutdown_tx
            .send(true)
            .expect("shutdown receiver should still be live");
        let server_result = server.await.expect("serve_tcp task should join");
        server_result.expect("serve_tcp should exit cleanly after shutdown");

        let mut stopped_accepting = false;
        for _ in 0..5 {
            match fcp_async_core::net::TcpStream::connect(addr).await {
                Ok(stream) => {
                    let _ = stream.shutdown(std::net::Shutdown::Both);
                }
                Err(_) => {
                    stopped_accepting = true;
                    break;
                }
            }
            fcp_async_core::time::sleep(Duration::from_millis(10)).await;
        }
        assert!(
            stopped_accepting,
            "host ingress listener still accepted connections after shutdown"
        );
    }

    const HOST_TELEGRAM_TEST_BOT_ID: &str = "123456";
    const HOST_TELEGRAM_TEST_BOT_SECRET: &str = "ABCDEFGHIJKLMNOPQRSTUVWXyz012345";

    fn host_telegram_test_bot_credential() -> String {
        format!("{HOST_TELEGRAM_TEST_BOT_ID}:{HOST_TELEGRAM_TEST_BOT_SECRET}")
    }

    fn host_telegram_token_path(method: &str) -> String {
        format!("/bot{}/{method}", host_telegram_test_bot_credential())
    }

    struct HostTelegramLoopbackServer {
        base_url: String,
        addr: std::net::SocketAddr,
        stop: Arc<AtomicBool>,
        handle: thread::JoinHandle<()>,
        request_paths: Arc<StdMutex<Vec<String>>>,
    }

    impl HostTelegramLoopbackServer {
        fn start() -> Self {
            let listener =
                StdTcpListener::bind("127.0.0.1:0").expect("bind host Telegram loopback server");
            let addr = listener
                .local_addr()
                .expect("host Telegram loopback address");
            let stop = Arc::new(AtomicBool::new(false));
            let request_paths = Arc::new(StdMutex::new(Vec::new()));
            let thread_stop = Arc::clone(&stop);
            let thread_paths = Arc::clone(&request_paths);
            let handle = thread::spawn(move || {
                for stream in listener.incoming() {
                    if thread_stop.load(Ordering::SeqCst) {
                        break;
                    }
                    match stream {
                        Ok(mut stream) => {
                            handle_host_telegram_loopback_request(&mut stream, &thread_paths);
                        }
                        Err(_) => break,
                    }
                }
            });

            Self {
                base_url: format!("http://{addr}"),
                addr,
                stop,
                handle,
                request_paths,
            }
        }

        fn request_paths_snapshot(&self) -> Vec<String> {
            self.request_paths
                .lock()
                .expect("request path log lock")
                .clone()
        }

        fn shutdown(self) -> Vec<String> {
            self.stop.store(true, Ordering::SeqCst);
            if let Ok(mut stream) = StdTcpStream::connect(self.addr) {
                let _ = stream.write_all(
                    b"GET /__shutdown HTTP/1.1\r\nHost: loopback\r\nConnection: close\r\n\r\n",
                );
            }
            self.handle
                .join()
                .expect("host Telegram loopback thread joins");
            self.request_paths
                .lock()
                .expect("request path log lock")
                .clone()
        }
    }

    fn handle_host_telegram_loopback_request(
        stream: &mut StdTcpStream,
        request_paths: &Arc<StdMutex<Vec<String>>>,
    ) {
        let Some((method, path)) = read_host_telegram_loopback_request(stream) else {
            return;
        };
        request_paths
            .lock()
            .expect("request path log lock")
            .push(path.clone());

        let path_without_query = path.split('?').next().unwrap_or(path.as_str());
        let get_me_path = host_telegram_token_path("getMe");
        let get_updates_path = host_telegram_token_path("getUpdates");
        let body = if method == "GET" && path_without_query == get_me_path {
            json!({
                "ok": true,
                "result": {
                    "id": 123456789,
                    "is_bot": true,
                    "first_name": "Host Loopback Bot",
                    "username": "host_loopback_bot"
                }
            })
        } else if method == "POST" && path_without_query == get_updates_path {
            json!({ "ok": true, "result": [] })
        } else {
            json!({
                "ok": false,
                "description": format!("unexpected host Telegram loopback route: {method} {path}")
            })
        };
        write_host_telegram_loopback_response(stream, &body);
    }

    fn read_host_telegram_loopback_request(stream: &mut StdTcpStream) -> Option<(String, String)> {
        let _ = stream.set_read_timeout(Some(Duration::from_secs(2)));
        let mut buffer = Vec::new();
        let mut chunk = [0u8; 1024];
        let header_end = loop {
            let read = stream.read(&mut chunk).ok()?;
            if read == 0 {
                return None;
            }
            buffer.extend_from_slice(&chunk[..read]);
            if let Some(position) = buffer.windows(4).position(|window| window == b"\r\n\r\n") {
                break position + 4;
            }
            if buffer.len() > 16 * 1024 {
                return None;
            }
        };

        let headers = String::from_utf8_lossy(&buffer[..header_end]);
        let request_line = headers.lines().next()?;
        let mut parts = request_line.split_whitespace();
        let method = parts.next()?.to_string();
        let path = parts.next()?.to_string();
        let content_length = headers.lines().find_map(|line| {
            let (name, value) = line.split_once(':')?;
            name.eq_ignore_ascii_case("content-length")
                .then(|| value.trim().parse::<usize>().ok())
                .flatten()
        });
        if let Some(content_length) = content_length {
            while buffer.len().saturating_sub(header_end) < content_length {
                let read = stream.read(&mut chunk).ok()?;
                if read == 0 {
                    break;
                }
                buffer.extend_from_slice(&chunk[..read]);
            }
        }
        Some((method, path))
    }

    fn write_host_telegram_loopback_response(stream: &mut StdTcpStream, body: &Value) {
        let body = body.to_string();
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            body.len(),
            body
        );
        let _ = stream.write_all(response.as_bytes());
        let _ = stream.flush();
    }

    fn telegram_connector_rpc_result(result: fcp_core::FcpResult<Value>) -> Value {
        match result {
            Ok(value) => json!({ "result": value }),
            Err(error) => json!({ "error": { "message": error.to_string() } }),
        }
    }

